import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { refreshContent, toggleLikeOpportunityAsync, toggleSaveOpportunityAsync } from '../../../store/contentSlice';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';

import { cn } from '../../../utils/cn';

const TrendingOpportunities = () => {
  const opportunities = useSelector((state) =>
    state.content.allOpportunities.filter(opp => opp.trending)
  );

  const user = useSelector((state) => state.auth.user);
  const navigate = useNavigate();
  const { addToast } = useToast();
  const dispatch = useDispatch();

  const [likedIds, setLikedIds] = useState([]);
  const [savedIds, setSavedIds] = useState([]);
  const [isProcessing, setIsProcessing] = useState({});
  const [likedAnimating, setLikedAnimating] = useState({});

  useEffect(() => {
    if (user?.id) {
      const fetchInteractions = async () => {
        try {
          const [liked, saved] = await Promise.all([
            supabaseService.getLikedOpportunities(user.id),
            supabaseService.getSavedOpportunities(user.id)
          ]);
          setLikedIds(liked || []);
          setSavedIds(saved.map(s => s.id) || []);
        } catch (error) {
          console.error("Error fetching interactions:", error);
        }
      };
      fetchInteractions();
    }
  }, [user]);

  const handleLike = async (e, opportunityId) => {
    e.preventDefault();
    e.stopPropagation();

    if (!user) {
      addToast("Please login to like opportunities", "info");
      return;
    }

    if (isProcessing[opportunityId]) return;

    setIsProcessing(prev => ({ ...prev, [opportunityId]: true }));
    setLikedAnimating(prev => ({ ...prev, [opportunityId]: true }));
    setTimeout(() => setLikedAnimating(prev => ({ ...prev, [opportunityId]: false })), 450);

    // Optimistic update
    const isLiked = likedIds.includes(opportunityId);
    if (isLiked) {
      setLikedIds(prev => prev.filter(id => id !== opportunityId));
    } else {
      setLikedIds(prev => [...prev, opportunityId]);
    }

    try {
      await supabaseService.toggleLikeOpportunity(user.id, opportunityId);
      // Silent refresh
      dispatch(refreshContent());
    } catch (error) {
      // Revert if error
      if (isLiked) {
        setLikedIds(prev => [...prev, opportunityId]);
      } else {
        setLikedIds(prev => prev.filter(id => id !== opportunityId));
      }
      addToast("Failed to update like status", "error");
    } finally {
      setIsProcessing(prev => ({ ...prev, [opportunityId]: false }));
    }
  };

  const handleSave = async (e, opportunityId) => {
    e.preventDefault();
    e.stopPropagation();

    if (!user) {
      addToast("Please login to bookmark opportunities", "info");
      return;
    }

    if (isProcessing[opportunityId]) return;

    setIsProcessing(prev => ({ ...prev, [opportunityId]: true }));

    // Optimistic update
    const isSaved = savedIds.includes(opportunityId);
    if (isSaved) {
      setSavedIds(prev => prev.filter(id => id !== opportunityId));
    } else {
      setSavedIds(prev => [...prev, opportunityId]);
    }

    try {
      const result = await supabaseService.toggleSaveOpportunity(user.id, opportunityId);
      addToast(result.saved ? "Opportunity bookmarked!" : "Bookmark removed", "success");
      // Silent refresh
      dispatch(refreshContent());
    } catch (error) {
      // Revert if error
      if (isSaved) {
        setSavedIds(prev => [...prev, opportunityId]);
      } else {
        setSavedIds(prev => prev.filter(id => id !== opportunityId));
      }
      addToast("Failed to save opportunity", "error");
    } finally {
      setIsProcessing(prev => ({ ...prev, [opportunityId]: false }));
    }
  };

  const getDeadlineBadgeClass = (daysLeft) => {
    if (daysLeft === null) return "deadline-badge safe text-primary bg-primary/10 border-primary/20";
    if (daysLeft <= 0) return "deadline-badge expired bg-gray-500/20 text-gray-500 border-gray-500/20";
    if (daysLeft <= 15) return "deadline-badge urgent";
    if (daysLeft <= 30) return "deadline-badge warning";
    return "deadline-badge text-primary bg-primary/10 border-primary/20";
  };

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8 md:mb-12">
          <div>
            <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-2">
              Trending Opportunities
            </h2>
            <p className="text-sm md:text-base lg:text-lg text-[var(--color-muted-foreground)]">
              Most viewed and applied opportunities this week
            </p>
          </div>
          <Link
            to="/opportunity-discovery"
            className="inline-flex items-center gap-2 text-[var(--color-secondary)] hover:text-[var(--color-primary)] font-semibold transition-colors duration-300 text-sm md:text-base"
          >
            <span>View All</span>
            <Icon name="ArrowRight" size={20} />
          </Link>
        </div>

        <div className="flex gap-4 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide pl-1 lg:pl-0 lg:grid lg:grid-cols-3 lg:gap-6 lg:overflow-visible lg:pb-0">
          {opportunities?.map((opportunity) => {
            const isExpired = opportunity?.daysLeft !== null && opportunity?.daysLeft <= 0;
            return (
              <Link
                key={opportunity?.id}
                to={`/opportunity-detail/${opportunity?.id}`}
                className={cn("opportunity-card group flex flex-col h-full shrink-0 w-[80vw] sm:w-[60vw] snap-center lg:w-auto lg:shrink lg:snap-align-none", isExpired && "opacity-80")}
              >
                <div className="relative h-48 md:h-56 rounded-xl overflow-hidden mb-4">
                  <Image
                    src={opportunity?.image}
                    alt={opportunity?.imageAlt}
                    className={cn(
                      "w-full h-full object-cover group-hover:scale-110 transition-transform duration-500",
                      isExpired && "grayscale-[0.5]"
                    )}
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/20 to-transparent"></div>

                  {opportunity?.verified && (
                    <div className={cn(
                      "absolute top-3 left-3 px-3 py-1 text-white text-xs font-semibold rounded-full flex items-center gap-1",
                      isExpired ? "bg-gray-400/50 text-gray-200 grayscale opacity-70" : "bg-[var(--color-success)]"
                    )}>
                      <Icon name="CheckCircle" size={12} />
                      <span>Verified</span>
                    </div>
                  )}

                  <div className="absolute top-3 right-3 flex flex-col gap-2">
                    <div className={getDeadlineBadgeClass(opportunity?.daysLeft)}>
                      <Icon name={isExpired ? "AlertCircle" : "Clock"} size={12} />
                      <span>{isExpired ? "Expired" : (opportunity?.daysLeft === null ? (opportunity?.deadline || "No Deadline") : `${opportunity?.daysLeft} days left`)}</span>
                    </div>

                    <div className="flex gap-2 justify-end">
                      <button
                        onClick={(e) => {
                          if (!isExpired) handleSave(e, opportunity.id);
                          else {
                            e.preventDefault();
                            e.stopPropagation();
                          }
                        }}
                        className={cn(
                          "w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 backdrop-blur-md",
                          savedIds.includes(opportunity.id) ? 'bg-[var(--color-accent)] text-white shadow-lg' : 'bg-black/40 text-white hover:bg-black/60 border border-white/20',
                          isExpired && "grayscale opacity-70 cursor-not-allowed"
                        )}
                        title={isExpired ? "Cannot save expired opportunity" : (savedIds.includes(opportunity.id) ? "Remove bookmark" : "Bookmark")}
                        disabled={isExpired}
                      >
                        <Icon
                          name="Bookmark"
                          size={16}
                          fill={savedIds.includes(opportunity.id) ? "currentColor" : "none"}
                        />
                      </button>
                    </div>
                  </div>

                  <div className="absolute bottom-3 left-3 right-3">
                    <span className={cn(
                      "inline-block px-3 py-1 backdrop-blur-md text-white text-[10px] md:text-xs font-bold rounded-full border border-white/20 uppercase tracking-wider",
                      isExpired ? "bg-gray-500/40" : "bg-black/60"
                    )}>
                      {opportunity?.type}
                    </span>
                  </div>
                </div>

                <div className="space-y-3 flex-1 flex flex-col">
                  <h3 className={cn(
                    "text-base md:text-lg font-bold line-clamp-2 transition-colors duration-300",
                    isExpired ? "text-gray-500" : "text-[var(--color-primary)] group-hover:text-[var(--color-secondary)]"
                  )}>
                    {opportunity?.title}
                  </h3>

                  <div className="flex items-center gap-2 text-sm text-[var(--color-muted-foreground)]">
                    <Icon name="Building2" size={16} />
                    <span className="line-clamp-1">{opportunity?.organization}</span>
                  </div>

                  <div className="flex items-center gap-2 sm:gap-4 text-xs sm:text-sm text-[var(--color-muted-foreground)] mb-4 min-w-0">
                    <div className="flex items-center gap-1 min-w-0">
                      <Icon name="MapPin" size={14} className="shrink-0" />
                      <span className="truncate">{opportunity?.location}</span>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      <Icon name="DollarSign" size={14} />
                      <span className="truncate">{opportunity?.stipend}</span>
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2 mt-auto">
                    {opportunity?.tags?.slice(0, 3)?.map((tag, index) => (
                      <span
                        key={index}
                        className="px-2 py-1 bg-[var(--color-muted)] text-[var(--color-muted-foreground)] text-xs rounded-md"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>

                  <div className="flex items-center justify-between pt-3 border-t border-[var(--color-border)] mt-4">
                    <div className="flex items-center gap-3 ml-auto">
                      <div className="flex items-center gap-1 text-xs text-[var(--color-muted-foreground)]">
                        <Icon name="Users" size={14} />
                        <span>{opportunity?.applicants?.toLocaleString()}</span>
                      </div>

                      <button
                        onClick={(e) => {
                          if (!isExpired) handleLike(e, opportunity.id);
                          else {
                            e.preventDefault();
                            e.stopPropagation();
                          }
                        }}
                        className={cn(
                          "relative flex items-center gap-1 text-xs transition-all heart-hover p-2 -m-2",
                          likedAnimating[opportunity.id] ? 'animate-heart-pop' : '',
                          likedIds.includes(opportunity.id) ? 'text-rose-500 font-bold scale-110' : 'text-[var(--color-muted-foreground)] hover:text-rose-500',
                          isExpired && "grayscale opacity-70 cursor-not-allowed"
                        )}
                        title={isExpired ? "Cannot like expired opportunity" : (likedIds.includes(opportunity.id) ? "Unlike" : "Like")}
                        disabled={isExpired}
                      >
                        {likedAnimating[opportunity.id] && !isExpired && (
                          <>
                            <span className="heart-particle animate-ribbon bg-rose-500" style={{ '--burst-transform': 'translate(-200%, -200%)', '--burst-rotate': '-45deg' }}></span>
                            <span className="heart-particle animate-ribbon bg-blue-500" style={{ '--burst-transform': 'translate(100%, -250%)', '--burst-rotate': '10deg' }}></span>
                            <span className="heart-particle animate-ribbon bg-amber-500" style={{ '--burst-transform': 'translate(200%, -150%)', '--burst-rotate': '45deg' }}></span>
                            <span className="heart-particle animate-ribbon bg-emerald-500" style={{ '--burst-transform': 'translate(-150%, 100%)', '--burst-rotate': '-120deg' }}></span>
                            <span className="heart-particle animate-ribbon bg-purple-500" style={{ '--burst-transform': 'translate(0%, 200%)', '--burst-rotate': '0deg' }}></span>
                          </>
                        )}
                        <Icon
                          name="Heart"
                          size={16}
                          fill={likedIds.includes(opportunity.id) ? "currentColor" : "none"}
                        />
                        <span>{opportunity?.likes_count || 0}</span>
                      </button>
                    </div>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default TrendingOpportunities;