import store from '../../store/store';
import { logout, setSessionTimeout } from '../../store/authSlice';
import { supabase } from '../supabaseClient';

/**
 * Session Manager - Handles auto-logout and session timeout
 */

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const TIMEOUT_WARNING = 5 * 60 * 1000; // 5 minutes before timeout
let timeoutId = null;
let warningTimeoutId = null;
let activityTimeout = null;
let suspensionSubscription = null;
let suspensionPollInterval = null;

/**
 * Initialize session management
 * Sets up activity listeners and timeout handlers
 */
export const initializeSessionManagement = () => {
  // Add activity event listeners
  const activityEvents = ['mousedown', 'keydown', 'scroll', 'touchstart', 'click'];

  activityEvents.forEach((event) => {
    document.addEventListener(event, handleActivity, true);
  });

  // Check session validity on app load
  checkSessionValidity();

  // Initialize Real-time Suspension Listener
  setupSuspensionListener();

  // Polling Fallback: Check suspension status every 30 seconds
  // This ensures security if real-time replication isn't enabled
  if (suspensionPollInterval) clearInterval(suspensionPollInterval);
  suspensionPollInterval = setInterval(checkSuspensionStatus, 30000);

  return () => {
    // Cleanup function to remove listeners
    activityEvents.forEach((event) => {
      document.removeEventListener(event, handleActivity, true);
    });

    // Cleanup Real-time subscription
    if (suspensionSubscription) {
      supabase.removeChannel(suspensionSubscription);
    }

    // Cleanup polling
    if (suspensionPollInterval) {
      clearInterval(suspensionPollInterval);
    }
  };
};

/**
 * Check if the user has been suspended (Polling Fallback)
 */
const checkSuspensionStatus = async () => {
  const state = store.getState().auth;
  if (!state.isAuthenticated || !state.user?.id) return;

  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('suspended')
      .eq('id', state.user.id)
      .single();

    if (!error && data?.suspended === true) {
      console.warn('User suspended detected via polling. Logging out...');
      handleSuspensionKickout();
    }
  } catch (err) {
    console.error('Error checking suspension status:', err);
  }
};

/**
 * Shared logout logic for suspension
 */
const handleSuspensionKickout = async () => {
  try {
    await supabase.auth.signOut();
  } catch (e) {
    console.error('Failed to sign out backend', e);
  }
  store.dispatch(logout());
  window.location.href = '/login?error=suspended';
};

/**
 * Shared logout logic for deletion
 */
const handleDeletionKickout = async () => {
  try {
    await supabase.auth.signOut();
  } catch (e) {
    console.error('Failed to sign out backend', e);
  }
  store.dispatch(logout());
  window.location.href = '/login?error=deleted';
};

/**
 * Setup Real-time Listener for User Suspension and Role Changes
 */
const setupSuspensionListener = () => {
  const state = store.getState().auth;
  if (!state.isAuthenticated || !state.user?.id) return;

  if (suspensionSubscription) {
    supabase.removeChannel(suspensionSubscription);
  }

  // Note: For this to work instantly, "Profiles" table REPLICATION must be enabled in Supabase Dashboard
  suspensionSubscription = supabase
    .channel('auth_state_changes') // Changed to descriptive channel title
    .on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'profiles',
        filter: `id=eq.${state.user.id}`,
      },
      (payload) => {
        if (payload.new && payload.new.suspended === true) {
          console.warn('User suspended in real-time. Logging out...');
          handleSuspensionKickout();
        }
      }
    )
    .on(
      'postgres_changes',
      {
        event: 'DELETE',
        schema: 'public',
        table: 'profiles',
        filter: `id=eq.${state.user.id}`,
      },
      (payload) => {
        console.warn('User account deleted in real-time. Logging out...');
        handleDeletionKickout();
      }
    )
    .subscribe();
};

/**
 * Handle user activity - reset timeout on any activity
 */
const handleActivity = () => {
  if (store.getState().auth.isAuthenticated) {
    resetSessionTimeout();
  }
};

/**
 * Reset session timeout - called on user activity
 */
export const resetSessionTimeout = () => {
  // Clear existing timeouts
  if (timeoutId) clearTimeout(timeoutId);
  if (warningTimeoutId) clearTimeout(warningTimeoutId);

  // Set warning timeout (5 minutes before logout)
  warningTimeoutId = setTimeout(() => {
    const state = store.getState().auth;
    if (state.isAuthenticated) {
      store.dispatch(
        setSessionTimeout({
          showWarning: true,
          message: 'Your session will expire in 5 minutes due to inactivity.',
        })
      );
    }
  }, SESSION_TIMEOUT - TIMEOUT_WARNING);

  // Set logout timeout
  timeoutId = setTimeout(() => {
    const state = store.getState().auth;
    if (state.isAuthenticated) {
      forceLogout();
      // Optionally redirect or show message
      console.warn('Session expired due to inactivity');
    }
  }, SESSION_TIMEOUT);
};

/**
 * Clear all session timeouts
 */
export const clearSessionTimeouts = () => {
  if (timeoutId) clearTimeout(timeoutId);
  if (warningTimeoutId) clearTimeout(warningTimeoutId);
  if (activityTimeout) clearTimeout(activityTimeout);
};

/**
 * Check if session is still valid
 * Validates token expiration and user data
 */
export const checkSessionValidity = () => {
  const token = localStorage.getItem('authToken');
  const loginTime = localStorage.getItem('loginTime');
  const user = localStorage.getItem('user');

  // Check if any essential data is missing
  if (!token || !loginTime || !user) {
    forceLogout();
    return false;
  }

  // Check if session has expired (24 hour max session)
  const currentTime = new Date().getTime();
  const sessionDuration = currentTime - parseInt(loginTime);
  const maxSessionDuration = 24 * 60 * 60 * 1000; // 24 hours

  if (sessionDuration > maxSessionDuration) {
    forceLogout();
    return false;
  }

  return true;
};

/**
 * Extend session - called when user continues after warning
 */
export const extendSession = () => {
  clearSessionTimeouts();
  resetSessionTimeout();
  store.dispatch(setSessionTimeout(null));
};

/**
 * Get remaining session time in seconds
 */
export const getRemainingSessionTime = () => {
  const loginTime = localStorage.getItem('loginTime');
  if (!loginTime) return 0;

  const currentTime = new Date().getTime();
  const elapsedTime = currentTime - parseInt(loginTime);
  const remainingTime = SESSION_TIMEOUT - elapsedTime;

  return Math.max(0, Math.ceil(remainingTime / 1000));
};

/**
 * Format remaining time for display
 */
export const formatRemainingTime = () => {
  const seconds = getRemainingSessionTime();
  const minutes = Math.floor(seconds / 60);
  const secs = seconds % 60;

  if (minutes === 0) {
    return `${secs}s`;
  }

  return `${minutes}m ${secs}s`;
};

/**
 * Force logout (manual logout)
 */
export const forceLogout = async () => {
  clearSessionTimeouts();
  try {
    await supabase.auth.signOut();
  } catch (e) {
    console.error('Failed to sign out backend', e);
  }
  store.dispatch(logout());
};

/**
 * Get session info
 */
export const getSessionInfo = () => {
  const loginTime = localStorage.getItem('loginTime');
  const user = localStorage.getItem('user');

  if (!loginTime || !user) {
    return null;
  }

  return {
    loginTime: new Date(parseInt(loginTime)),
    remainingTime: getRemainingSessionTime(),
    remainingTimeFormatted: formatRemainingTime(),
    user: JSON.parse(user),
  };
};
