import React, { useState, useEffect, useCallback } from 'react';
import Icon from '../AppIcon';

/**
 * NetworkStatusIndicator
 * 
 * Monitors network quality and shows a persistent pill at the bottom left
 * of the screen.
 */

const QUALITY = {
    OFFLINE: 'offline',
    POOR: 'poor',
    FAIR: 'fair',
    GOOD: 'good',
};

const PING_URL = `${window.location.origin}/favicon.ico`;
const PING_INTERVAL_MS = 15_000;     // probe every 15 s
const PING_TIMEOUT_MS  =  5_000;     // wait up to 5 s for the probe

const measureRTT = () =>
    new Promise((resolve) => {
        const start = Date.now();
        const controller = new AbortController();
        const tid = setTimeout(() => { controller.abort(); resolve(Infinity); }, PING_TIMEOUT_MS);

        fetch(`${PING_URL}?_=${start}`, { method: 'HEAD', cache: 'no-store', signal: controller.signal })
            .then(() => { clearTimeout(tid); resolve(Date.now() - start); })
            .catch(() => { clearTimeout(tid); resolve(Infinity); });
    });

const getConnectionQuality = async () => {
    // 1. Hard offline guard from browser API
    if (!navigator.onLine) return QUALITY.OFFLINE;

    // 2. Connection API hint (best effort, not universal)
    const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (conn?.type === 'none') return QUALITY.OFFLINE;

    // 3. Latency probe
    const rtt = await measureRTT();

    if (rtt === Infinity) return QUALITY.OFFLINE;
    if (rtt > 1200)        return QUALITY.POOR;
    if (rtt > 500)         return QUALITY.FAIR;
    return QUALITY.GOOD;
};

const QUALITY_CONFIG = {
    [QUALITY.OFFLINE]: {
        label: 'Offline',
        sublabel: 'No Connection',
        icon: 'WifiOff',
        barClass: 'bg-red-600 dark:bg-red-700 shadow-red-500/30',
        textClass: 'text-white',
        dotClass: 'bg-white',
    },
    [QUALITY.POOR]: {
        label: 'Poor',
        sublabel: 'High Latency',
        icon: 'SignalLow',
        barClass: 'bg-red-500/95 dark:bg-red-600/95 shadow-red-500/20',
        textClass: 'text-white',
        dotClass: 'bg-white animate-pulse',
    },
    [QUALITY.FAIR]: {
        label: 'Fair',
        sublabel: 'Slow Connection',
        icon: 'SignalMedium',
        barClass: 'bg-amber-500/95 dark:bg-amber-600/95 shadow-amber-500/20',
        textClass: 'text-white',
        dotClass: 'bg-white animate-pulse',
    },
    [QUALITY.GOOD]: {
        label: 'Online',
        sublabel: 'Good Connection',
        icon: 'Wifi',
        barClass: 'bg-black/50 dark:bg-white/10 hover:bg-black/70 dark:hover:bg-white/20 backdrop-blur-md shadow-black/10',
        textClass: 'text-white',
        dotClass: 'bg-green-500',
    },
};

const NetworkStatusIndicator = () => {
    const [quality, setQuality] = useState(null);   // null = not yet measured

    const handleQualityChange = useCallback((newQuality) => {
        setQuality(prev => {
            if (prev === newQuality) return prev;            // no change
            return newQuality;
        });
    }, []);

    useEffect(() => {
        let running = true;

        const probe = async () => {
            const q = await getConnectionQuality();
            if (running) handleQualityChange(q);
        };

        // Immediate probe
        probe();

        // Periodic probing
        const interval = setInterval(probe, PING_INTERVAL_MS);

        // Browser online/offline events as fast triggers
        const onOffline = () => handleQualityChange(QUALITY.OFFLINE);
        const onOnline  = () => probe();          // re-measure; don't just assume GOOD

        window.addEventListener('offline', onOffline);
        window.addEventListener('online', onOnline);

        // Connection API change event
        const conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
        conn?.addEventListener('change', probe);

        return () => {
            running = false;
            clearInterval(interval);
            window.removeEventListener('offline', onOffline);
            window.removeEventListener('online', onOnline);
            conn?.removeEventListener('change', probe);
        };
    }, [handleQualityChange]);

    if (!quality) return null; // Still measuring

    const cfg = QUALITY_CONFIG[quality] || QUALITY_CONFIG[QUALITY.GOOD];

    return (
        <div
            className={`fixed bottom-4 left-4 z-[9999] flex items-center gap-2.5 px-3 py-2 rounded-2xl shadow-xl transition-all duration-300 ease-out cursor-default group ${cfg.barClass} ${cfg.textClass}`}
            role="status"
            aria-live="polite"
        >
            {/* Pulsing dot (only shown for offline/poor/fair, or colored green for good) */}
            <span className={`w-2 h-2 rounded-full shrink-0 ${cfg.dotClass}`} />

            {/* Signal bars */}
            <div className="flex items-end gap-[2px] h-3.5 shrink-0">
                {[1, 2, 3, 4].map(bar => {
                    const active =
                        quality === QUALITY.GOOD   ? bar <= 4 :
                        quality === QUALITY.FAIR   ? bar <= 2 :
                        quality === QUALITY.POOR   ? bar <= 1 :
                        false;
                    return (
                        <div
                            key={bar}
                            style={{ height: `${bar * 25}%` }}
                            className={`w-[3px] rounded-sm transition-all duration-300 ${active ? (quality === QUALITY.GOOD ? 'bg-white' : 'bg-white') : 'bg-white/20'}`}
                        />
                    );
                })}
            </div>

            {/* Text details (hidden on small screens unless hovered to save space) */}
            <div className="flex-col hidden sm:flex max-w-0 sm:max-w-xs overflow-hidden opacity-0 sm:opacity-100 group-hover:max-w-xs group-hover:opacity-100 transition-all duration-300 ml-1 pr-1">
                <span className="font-black italic text-[11px] leading-tight uppercase tracking-wider">{cfg.label}</span>
                <span className="text-[10px] opacity-70 whitespace-nowrap leading-tight">{cfg.sublabel}</span>
            </div>
        </div>
    );
};

export default NetworkStatusIndicator;
