import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { extendSession, forceLogout } from '../../utils/auth/sessionManager';
import Button from './Button';
import Icon from '../AppIcon';

/**
 * SessionWarningModal - Shows when user is about to be logged out due to inactivity
 */
const SessionWarningModal = () => {
  const dispatch = useDispatch();
  const { sessionTimeout } = useSelector((state) => state.auth);
  const [countdownTime, setCountdownTime] = useState(300); // 5 minutes in seconds

  // Countdown timer
  useEffect(() => {
    if (!sessionTimeout?.showWarning) {
      setCountdownTime(300);
      return;
    }

    const interval = setInterval(() => {
      setCountdownTime((prev) => {
        if (prev <= 1) {
          // Time's up, force logout
          forceLogout();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [sessionTimeout?.showWarning]);

  const handleContinue = () => {
    extendSession();
    setCountdownTime(300);
  };

  const handleLogout = () => {
    forceLogout();
  };

  if (!sessionTimeout?.showWarning) {
    return null;
  }

  const minutes = Math.floor(countdownTime / 60);
  const seconds = countdownTime % 60;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[200] p-4">
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl max-w-md w-full animate-in">
        {/* Header */}
        <div className="bg-gradient-to-r from-warning to-red-500 text-white p-6 rounded-t-lg">
          <div className="flex items-center gap-3">
            <Icon name="AlertTriangle" size={24} />
            <h2 className="text-xl font-bold">Session Expiring Soon</h2>
          </div>
        </div>

        {/* Content */}
        <div className="p-6 space-y-4">
          <p className="text-gray-700 dark:text-gray-300">
            Your session will expire due to inactivity. You will be logged out in:
          </p>

          {/* Countdown */}
          <div className="bg-red-50 dark:bg-red-900/20 border-2 border-red-200 dark:border-red-800 rounded-lg p-4 text-center">
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-2">
              Time remaining:
            </p>
            <p className="text-4xl font-bold text-red-600 dark:text-red-400 font-mono">
              {String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
            </p>
          </div>

          <p className="text-sm text-gray-600 dark:text-gray-400">
            Click "Continue Session" to stay logged in, or you will be logged out automatically.
          </p>
        </div>

        {/* Footer */}
        <div className="flex gap-3 p-6 border-t border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/50 rounded-b-lg">
          <Button
            variant="outline"
            fullWidth
            onClick={handleLogout}
            className="text-red-600 dark:text-red-400 border-red-200 dark:border-red-800"
          >
            Logout Now
          </Button>
          <Button
            fullWidth
            onClick={handleContinue}
            className="bg-gradient-to-r from-success to-green-500 hover:shadow-lg"
          >
            Continue Session
          </Button>
        </div>
      </div>
    </div>
  );
};

export default SessionWarningModal;
