import React, { useEffect, Suspense } from "react";
import { BrowserRouter, Routes as RouterRoutes, Route, Navigate, useLocation } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import ScrollToTop from "components/ScrollToTop";
import ScrollToTopButton from "components/ui/ScrollToTopButton";
import CookieConsent from "components/ui/CookieConsent";
import SessionWarningModal from "components/ui/SessionWarningModal";
import ErrorBoundary from "components/ErrorBoundary";
import Homepage from './pages/homepage';
import NotFound from "pages/NotFound";
import Unauthorized from "pages/Unauthorized";

const AdminDashboard = React.lazy(() => import('./pages/admin-dashboard'));
const InstructorDashboard = React.lazy(() => import('./pages/instructor-dashboard'));
const StudentDashboard = React.lazy(() => import('./pages/student-dashboard'));
const Login = React.lazy(() => import('./pages/login'));
const Signup = React.lazy(() => import('./pages/signup'));
const ForgotPassword = React.lazy(() => import('./pages/forgot-password'));
const OpportunityDetail = React.lazy(() => import('./pages/opportunity-detail'));
const Contact = React.lazy(() => import('./pages/contact'));
const OpportunityDiscovery = React.lazy(() => import('./pages/opportunity-discovery'));
const About = React.lazy(() => import('./pages/about'));
const BuyCoffee = React.lazy(() => import('./pages/support'));
const Profile = React.lazy(() => import('./pages/profile/index'));
const Academy = React.lazy(() => import('./pages/academy'));
const CoursePlayer = React.lazy(() => import('./pages/academy/CoursePlayer'));
const GrowthVault = React.lazy(() => import('./pages/academy/GrowthVault'));
const LUCStore = React.lazy(() => import('./pages/store'));
const JoinTheBuild = React.lazy(() => import('./pages/JoinTheBuild'));
const HoneypotTrap = React.lazy(() => import('./pages/HoneypotTrap'));
const BecomeInstructor = React.lazy(() => import('./pages/academy/BecomeInstructor'));
const BrainstormSessions = React.lazy(() => import('./pages/academy/BrainstormSessions'));
const LiveSessionPage = React.lazy(() => import('./pages/academy/LiveSessionPage'));
const RecruiterPortal = React.lazy(() => import('./pages/recruiter-portal'));
const InstructorStorefront = React.lazy(() => import('./pages/academy/InstructorStorefront'));
const HallOfFame = React.lazy(() => import('./pages/academy/HallOfFame'));
const ProjectSquadsHub = React.lazy(() => import('./pages/academy/ProjectSquadsHub'));
const FoundersHub = React.lazy(() => import('./pages/academy/FoundersHub'));
const AcademyCommons = React.lazy(() => import('./pages/academy/AcademyCommons'));
const CourseCatalog = React.lazy(() => import('./pages/academy/CourseCatalog'));
const DealRoom = React.lazy(() => import('./pages/syndicate/DealRoom'));
const EmergencyDisable = React.lazy(() => import('./pages/admin/EmergencyDisable'));

import { ProtectedRoute } from './utils/auth/ProtectedRoute';
import { restoreSession } from './store/authSlice';
import { initializeSessionManagement } from './utils/auth/sessionManager';
import { supabaseService } from './services/supabaseService';

const RouteActivityTracker = () => {
  const location = useLocation();
  const { user } = useSelector((state) => state.auth);

  useEffect(() => {
    // Silently log the page view to the audit logs whenever the route changes
    supabaseService.logActivity('page_view', { path: location.pathname, search: location.search }, user?.email || null);
  }, [location, user?.email]);

  return null;
};

const Routes = () => {
  const dispatch = useDispatch();
  const { isAuthenticated } = useSelector((state) => state.auth);

  // Restore session on app load
  useEffect(() => {
    dispatch(restoreSession());
  }, [dispatch]);

  // Initialize session management (auto-logout, timeouts, etc.)
  useEffect(() => {
    const cleanup = initializeSessionManagement();
    return cleanup;
  }, [isAuthenticated]);

  return (
    <>
      <RouteActivityTracker />
      <ErrorBoundary>
        <ScrollToTop />
        <Suspense fallback={<div className="flex h-screen w-full items-center justify-center bg-slate-950"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>}>
          <RouterRoutes>
            {/* Honeypot Traps - Catch common malicious/bot probes */}
            <Route path="/wp-admin/*" element={<HoneypotTrap />} />
            <Route path="/wp-login.php" element={<HoneypotTrap />} />
            <Route path="/wp-config.php*" element={<HoneypotTrap />} />
            <Route path="/phpmyadmin/*" element={<HoneypotTrap />} />
            <Route path="/.env" element={<HoneypotTrap />} />
            <Route path="/.git/*" element={<HoneypotTrap />} />
            <Route path="/.ssh/*" element={<HoneypotTrap />} />
            <Route path="/.vscode/*" element={<HoneypotTrap />} />
            <Route path="/.idea/*" element={<HoneypotTrap />} />
            <Route path="/backup*" element={<HoneypotTrap />} />
            <Route path="/database.sql*" element={<HoneypotTrap />} />
            <Route path="/admin.php*" element={<HoneypotTrap />} />
            <Route path="/actuator/*" element={<HoneypotTrap />} />
            <Route path="/v1/config" element={<HoneypotTrap />} />
            <Route path="/v2/_catalog" element={<HoneypotTrap />} />
            <Route path="/node_modules/*" element={<HoneypotTrap />} />
            {/* Public Routes */}
            <Route path="/" element={<Homepage />} />
            <Route path="/homepage" element={<Homepage />} />
            <Route path="/opportunity-detail/:id" element={<OpportunityDetail />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/opportunity-discovery" element={<OpportunityDiscovery />} />
            <Route path="/about" element={<About />} />
            <Route path="/buy-coffee" element={<BuyCoffee />} />
            <Route path="/store" element={<LUCStore />} />
            <Route path="/join-the-build" element={<JoinTheBuild />} />
            <Route path="/academy" element={<Academy />} />
            <Route path="/academy/courses" element={<CourseCatalog />} />
            <Route path="/academy/course/:id" element={<CoursePlayer />} />
            <Route path="/academy/lesson/:id" element={<CoursePlayer />} />
            <Route path="/academy/vault" element={<GrowthVault />} />
            <Route path="/academy/become-instructor" element={<BecomeInstructor />} />
            <Route path="/academy/brainstorm" element={<BrainstormSessions />} />
            <Route path="/academy/live/:meetingId" element={<LiveSessionPage />} />
            <Route path="/academy/hall-of-fame" element={<HallOfFame />} />
            <Route path="/academy/project-squads" element={<ProjectSquadsHub />} />
            <Route path="/academy/founders-hub" element={<FoundersHub />} />
            <Route path="/academy/commons" element={<AcademyCommons />} />
            <Route path="/instructor/:instructorId" element={<InstructorStorefront />} />
            <Route path="/recruiter-portal" element={<RecruiterPortal />} />
            <Route path="/syndicate" element={<DealRoom />} />

            {/* Auth Routes */}
            <Route path="/admin-login" element={<Navigate to="/login" replace />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />

            {/* Emergency Admin Bypass - No ProtectedRoute, standalone auth check */}
            <Route path="/admin/emergency" element={<EmergencyDisable />} />

            {/* Convenience shortcut */}
            <Route
              path="/admin"
              element={
                isAuthenticated ? (
                  <Navigate to="/admin-dashboard" replace />
                ) : (
                  <Navigate to="/login" replace />
                )
              }
            />

            {/* Protected Routes - Admin Only */}
            <Route
              path="/admin-dashboard"
              element={
                <ProtectedRoute
                  element={<AdminDashboard />}
                  allowedRoles={['admin', 'moderator', 'stealth']}
                />
              }
            />
            <Route
              path="/instructor-dashboard"
              element={
                <ProtectedRoute
                  element={<InstructorDashboard />}
                  allowedRoles={['instructor', 'tutor', 'admin', 'moderator', 'stealth']}
                />
              }
            />
            <Route
              path="/student-dashboard"
              element={
                <ProtectedRoute
                  element={<StudentDashboard />}
                />
              }
            />
            <Route
              path="/profile"
              element={
                <ProtectedRoute
                  element={<Profile />}
                />
              }
            />

            {/* Authorization Error */}
            <Route path="/unauthorized" element={<Unauthorized />} />

            {/* Catch-all Route */}
            <Route path="*" element={<NotFound />} />
          </RouterRoutes>
        </Suspense>
        <ScrollToTopButton />
        <CookieConsent />
        <SessionWarningModal />
      </ErrorBoundary>
    </>
  );
};

export default Routes;
