import React, { useState, useRef, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { logout } from '../store/authSlice';
import { clearActivity } from '../store/activitySlice';
import { forceLogout, getSessionInfo, formatRemainingTime } from '../utils/auth/sessionManager';
import Icon from './AppIcon';
import ConfirmationModal from './ui/ConfirmationModal';

const UserProfileDropdown = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [sessionInfo, setSessionInfo] = useState(null);
  const dropdownRef = useRef(null);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { user, role, roles } = useSelector((state) => state.auth);
  const { courseProgress } = useSelector((state) => state.activity);

  const isAdmin = role === 'admin' || role === 'moderator' || roles?.includes('admin') || roles?.includes('moderator');
  const isInstructor = role === 'instructor' || role === 'tutor' || roles?.includes('instructor') || roles?.includes('tutor');
  
  // Only show Student Dashboard for Instructors/Admins if they are actually enrolled in something
  const hasStudentActivity = Object.keys(courseProgress || {}).length > 0;
  const isRegularScholar = !isAdmin && !isInstructor;
  const showStudentDashboard = isRegularScholar || hasStudentActivity;

  // Update session info periodically
  useEffect(() => {
    const updateSessionInfo = () => {
      const info = getSessionInfo();
      setSessionInfo(info);
    };

    updateSessionInfo();
    const interval = setInterval(updateSessionInfo, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, []);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = () => {
    dispatch(logout());
    dispatch(clearActivity());
    forceLogout();
    navigate('/login');
  };

  if (!user) return null;

  const getRoleBadgeColor = () => {
    switch (role?.toLowerCase()) {
      case 'admin':
        return 'bg-red-100 dark:bg-red-900/20 text-red-700 dark:text-red-300';
      case 'moderator':
        return 'bg-blue-100 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300';
      default:
        return 'bg-gray-100 dark:bg-gray-900/20 text-gray-700 dark:text-gray-300';
    }
  };

  const getGreeting = () => {
    if (user?.created_at) {
      const created = new Date(user.created_at);
      const now = new Date();
      const diffInHours = (now - created) / (1000 * 60 * 60);
      if (diffInHours < 24) return 'Welcome Aboard,';
    }

    const hour = new Date().getHours();
    if (hour < 12) return 'Good Morning,';
    if (hour < 18) return 'Good Afternoon,';
    return 'Good Evening,';
  };

  return (
    <div className="relative" ref={dropdownRef}>
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
        aria-expanded={isOpen}
        aria-label="User profile menu"
      >
        {/* Avatar */}
        <div className="flex-shrink-0">
          {user?.avatar ? (
            <img
              src={user.avatar}
              alt={user.name}
              className="w-8 h-8 rounded-full border-2 border-primary"
            />
          ) : (
            <div className="w-8 h-8 rounded-full bg-gradient-to-r from-primary to-secondary flex items-center justify-center text-white text-sm font-semibold">
              {user?.name?.charAt(0)?.toUpperCase()}
            </div>
          )}
        </div>

        {/* User Info */}
        <div className="hidden sm:block text-left">
          <p className="text-xs text-primary font-medium">
            {getGreeting()}
          </p>
          <p className="text-sm font-semibold text-gray-900 dark:text-white">
            {user?.name}
          </p>
        </div>

        {/* Chevron Icon */}
        <Icon
          name={isOpen ? 'ChevronUp' : 'ChevronDown'}
          size={16}
          className="text-gray-500 dark:text-gray-400"
        />
      </button>

      {/* Dropdown Menu */}
      {isOpen && (
        <div className="absolute right-0 mt-2 w-64 bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 z-70">
          {/* Header */}
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-700">
            <div className="flex items-center gap-3 mb-3">
              {user?.avatar ? (
                <img
                  src={user.avatar}
                  alt={user.name}
                  className="w-12 h-12 rounded-full border-2 border-primary"
                />
              ) : (
                <div className="w-12 h-12 rounded-full bg-gradient-to-r from-primary to-secondary flex items-center justify-center text-white font-semibold">
                  {user?.name?.charAt(0)?.toUpperCase()}
                </div>
              )}
              <div className="flex-1">
                <p className="text-xs text-primary font-medium mb-0.5">
                  {getGreeting()}
                </p>
                <p className="text-sm font-bold text-gray-900 dark:text-white">
                  {user?.name}
                </p>
                <p className="text-xs text-gray-500 dark:text-gray-400">
                  {user?.email}
                </p>
              </div>
            </div>

            {/* Role Badge */}
            <div className="flex items-center gap-2">
              <span
                className={`inline-block px-3 py-1 rounded-full text-xs font-semibold ${getRoleBadgeColor()}`}
              >
                {role?.charAt(0).toUpperCase() + role?.slice(1)}
              </span>
            </div>
          </div>

          {/* Session Info */}
          {sessionInfo && (
            <div className="px-4 py-3 bg-blue-50 dark:bg-blue-900/20 border-b border-gray-200 dark:border-gray-700">
              <div className="text-xs text-gray-600 dark:text-gray-400">
                <div className="flex items-center gap-2 mb-1">
                  <Icon name="Clock" size={14} />
                  <span>Session remaining:</span>
                </div>
                <p className="text-sm font-semibold text-primary ml-6">
                  {formatRemainingTime()}
                </p>
              </div>
            </div>
          )}

          {/* Menu Items */}
          <div className="py-2">
            {isAdmin && (
              <button
                onClick={() => {
                  navigate('/admin-dashboard');
                  setIsOpen(false);
                }}
                className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors"
              >
                <Icon name="LayoutDashboard" size={16} />
                <span>Admin Dashboard</span>
              </button>
            )}

            {(isInstructor || isAdmin) && (
              <button
                onClick={() => {
                  navigate('/instructor-dashboard');
                  setIsOpen(false);
                }}
                className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors"
              >
                <Icon name="Presentation" size={16} />
                <span>Instructor Dashboard</span>
              </button>
            )}

            {showStudentDashboard && (
              <button
                onClick={() => {
                  navigate('/student-dashboard');
                  setIsOpen(false);
                }}
                className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors"
              >
                <Icon name="LayoutDashboard" size={16} />
                <span>Student Dashboard</span>
              </button>
            )}

            <button
              onClick={() => {
                navigate('/profile', { state: { tab: 'account' } });
                setIsOpen(false);
              }}
              className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors"
            >
              <Icon name="User" size={16} />
              <span>Profile Settings</span>
            </button>

            <button
              onClick={() => {
                navigate('/profile', { state: { tab: 'preferences' } });
                setIsOpen(false);
              }}
              className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2 transition-colors"
            >
              <Icon name="Settings" size={16} />
              <span>Preferences</span>
            </button>

            <div className="my-2 border-t border-gray-200 dark:border-gray-700" />

            <button
              onClick={() => {
                setIsOpen(false);
                setShowLogoutConfirm(true);
              }}
              className="w-full px-4 py-2 text-left text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-2 transition-colors"
            >
              <Icon name="LogOut" size={16} />
              <span>Logout</span>
            </button>
          </div>
        </div>
      )}

      {/* Logout Confirmation Modal */}
      <ConfirmationModal
        isOpen={showLogoutConfirm}
        onClose={() => setShowLogoutConfirm(false)}
        onConfirm={handleLogout}
        title="Confirm Logout"
        message="Are you sure you want to log out of your account? You will need to sign in again to access personalized features."
        confirmText="Logout"
        cancelText="Stay logged in"
        type="danger"
      />
    </div>
  );
};

export default UserProfileDropdown;
