import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Icon from '../AppIcon';
import { supabaseService } from '../../services/supabaseService';
import { cn } from '../../utils/cn';
import { useSelector } from 'react-redux';

const BroadcastBanner = () => {
    const navigate = useNavigate();
    const { isAuthenticated, user } = useSelector(state => state.auth);
    const [activeBroadcast, setActiveBroadcast] = useState(null);
    const [isDismissed, setIsDismissed] = useState(false);
    const [lastBroadcastId, setLastBroadcastId] = useState(null);

    useEffect(() => {
        console.log("BroadcastBanner mounted, checking for alerts...");
        fetchLatestBroadcast();

        // 1. Listen for Realtime Broadcasts (Instant)
        const channel = supabaseService.supabase.channel('platform_notifications');
        
        channel
            .on(
                'broadcast',
                { event: 'NEW_BROADCAST' },
                ({ payload }) => {
                    console.log("New broadcast received via Realtime:", payload);
                    setActiveBroadcast(payload);
                    setIsDismissed(false);
                    setLastBroadcastId(payload.id);
                }
            )
            .on(
                'broadcast',
                { event: 'DELETE_BROADCAST' },
                ({ payload }) => {
                    console.log("Broadcast deletion received:", payload);
                    if (activeBroadcast && (payload.id === activeBroadcast.id)) {
                        setActiveBroadcast(null);
                    }
                }
            )
            // 2. Listen for Database Changes (Postgres) - specifically for deletions
            .on(
                'postgres_changes',
                { event: '*', schema: 'public', table: 'instructor_announcements' },
                (payload) => {
                    console.log("Announcement DB change detected:", payload);
                    if (payload.eventType === 'DELETE') {
                        // If the currently active broadcast was deleted, hide the banner
                        if (activeBroadcast && (payload.old.id === activeBroadcast.id)) {
                            setActiveBroadcast(null);
                        } else {
                            // Otherwise refresh to see if there's another relevant one
                            fetchLatestBroadcast();
                        }
                    } else {
                        fetchLatestBroadcast();
                    }
                }
            )
            .subscribe((status) => {
                console.log("BroadcastBanner subscription status:", status);
            });

        return () => {
            supabaseService.supabase.removeChannel(channel);
        };
    }, [activeBroadcast?.id]);

    const fetchLatestBroadcast = async () => {
        try {
            // Fetch the most recent announcement from the last 7 days
            const weekAgo = new Date();
            weekAgo.setDate(weekAgo.getDate() - 7);

            const { data, error } = await supabaseService.supabase
                .from('instructor_announcements')
                .select('*')
                .gte('created_at', weekAgo.toISOString())
                .order('created_at', { ascending: false })
                .limit(1);

            console.log("Latest broadcast fetch result:", { data, error });

            if (!error && data && data.length > 0) {
                const broadcast = data[0];
                // Optional: Check if user has already dismissed this specific ID (could use localStorage)
                const dismissedId = localStorage.getItem('luc_dismissed_broadcast');
                if (dismissedId !== broadcast.id.toString()) {
                    setActiveBroadcast(broadcast);
                    setLastBroadcastId(broadcast.id);
                }
            }
        } catch (err) {
            console.error("Failed to fetch latest broadcast", err);
        }
    };

    const handleDismiss = () => {
        setIsDismissed(true);
        if (activeBroadcast) {
            localStorage.setItem('luc_dismissed_broadcast', activeBroadcast.id.toString());
        }
    };

    if (!activeBroadcast || isDismissed) return null;

    // Determine banner color based on type
    const bannerConfig = {
        alert: "bg-destructive shadow-[0_4px_20px_rgba(220,38,38,0.4)]",
        update: "bg-brand-blue shadow-[0_4px_20px_rgba(14,165,233,0.4)]",
        assignment: "bg-secondary shadow-[0_4px_20px_rgba(8,145,178,0.4)]",
        info: "bg-slate-800 shadow-[0_4px_20px_rgba(30,41,59,0.4)]"
    };

    return (
        <AnimatePresence>
            <motion.div 
                key={activeBroadcast.id}
                initial={{ y: -100, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: -100, opacity: 0 }}
                className={cn(
                    "relative w-full z-[90] px-4 py-2 flex items-center justify-center transition-all pointer-events-auto",
                    bannerConfig[activeBroadcast.type] || bannerConfig.info
                )}
            >
                <div className="max-w-7xl w-full flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center text-white shrink-0">
                            <Icon 
                                name={activeBroadcast.type === 'alert' ? "AlertTriangle" : "Megaphone"} 
                                size={16} 
                                className={activeBroadcast.is_critical ? "animate-bounce" : ""}
                            />
                        </div>
                        <div className="min-w-0">
                            <div className="flex items-center gap-2 mb-0.5">
                                <p className="text-white text-[10px] font-black uppercase tracking-widest leading-none">
                                    {activeBroadcast.type === 'alert' ? "Important Announcement" : "Instructor Broadcast"}
                                </p>
                                {activeBroadcast.is_critical && (
                                    <span className="px-1.5 py-0.5 bg-white text-black text-[8px] font-black uppercase rounded">Critical</span>
                                )}
                            </div>
                            <h4 className="text-white text-xs font-bold truncate italic tracking-tight">
                                {activeBroadcast.title}: <span className="opacity-80 font-medium not-italic">{activeBroadcast.content}</span>
                            </h4>
                        </div>
                    </div>

                    <div className="flex items-center gap-2 shrink-0">
                        <button 
                            onClick={() => {
                                if (activeBroadcast.course_id) {
                                    navigate(`/academy/course/${activeBroadcast.course_id}`);
                                } else {
                                    navigate('/academy');
                                }
                                handleDismiss();
                            }}
                            className="bg-white text-[10px] font-black px-4 py-1.5 rounded-full text-black hover:scale-105 active:scale-95 transition-all"
                        >
                            VIEW DETAILS
                        </button>
                        
                        <button 
                            onClick={handleDismiss}
                            className="p-1.5 text-white/60 hover:text-white hover:bg-white/10 rounded-full transition-all"
                        >
                            <Icon name="X" size={14} />
                        </button>
                    </div>
                </div>
            </motion.div>
        </AnimatePresence>
    );
};

export default BroadcastBanner;
