import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { supabaseService } from '../services/supabaseService';

const calculateDaysLeft = (deadline) => {
  if (!deadline) return null;
  const target = new Date(deadline);
  if (isNaN(target.getTime())) return null; // Handle non-date strings like "Rolling"
  const diff = target - new Date();
  return Math.ceil(diff / (1000 * 60 * 60 * 24));
};

// Async Thunks
export const fetchAllContent = createAsyncThunk(
  'content/fetchAll',
  async (_, { rejectWithValue }) => {
    try {
      const dbOpportunities = await supabaseService.getOpportunities();
      const siteContent = await supabaseService.getSiteContent();

      // Normalize opportunities
      const opportunities = dbOpportunities.map(opp => ({
        ...opp,
        daysLeft: calculateDaysLeft(opp.deadline),
        imageAlt: opp.image_alt || opp.title,
        organizationLogo: opp.organization_logo,
        shortDescription: opp.short_description,
        detailedDescription: opp.detailed_description,
        fundingType: opp.funding_type,
        applicationLink: opp.application_link,
        benefitsList: opp.benefits_list || [],
        requirementsList: opp.requirements_list || [],
        processList: opp.process_list || [],
        duration: opp.duration,
        educationLevel: opp.education_level,
        eligibility: opp.eligibility,
        language: opp.language,
        successStories: opp.success_stories || [],
      }));

      return { opportunities, siteContent };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

