export const updateRatingAsync = createAsyncThunk(
  'content/updateRating',
  async ({ courseId, userId, rating, comment, userName = 'LUC Student' }, { getState, rejectWithValue, dispatch }) => {
    try {
      // 1. Submit to new course_reviews table
      await supabaseService.submitReview({ userId, courseId, rating, comment });

      // 2. Fetch all reviews to calculate new average
      const reviews = await supabaseService.getCourseReviews(courseId);

      const formattedReviews = reviews.map(r => ({
        id: r.id,
        userId: r.user_id,
        userName: r.profiles?.full_name || 'LUC Student',
        avatar: r.profiles?.avatar_url,
        rating: r.rating,
        comment: r.comment,
        date: r.created_at
      }));

      const totalRating = reviews.reduce((sum, r) => sum + r.rating, 0);
      const newAvgRating = (totalRating / reviews.length).toFixed(1);

      // 3. Update the global site_content cache ONLY IF user is admin
      const contentState = getState().content;
      const userRole = getState().auth.role;
      if (userRole !== 'admin') {
        // For regular users, just update the local Redux state for this specific course
        return { type: 'other', courseId, reviews: formattedReviews, rating: newAvgRating };
      }

      let updatedAcademy = [...contentState.academy];
      let updatedVault = [...contentState.vault];
      let targetType = null;

      const processUpdate = (list) => {
        const index = list.findIndex(c => c.id.toString() === courseId.toString());
        if (index === -1) return null;
        const course = list[index];
        return {
          ...course,
          rating: newAvgRating,
          reviews: formattedReviews.slice(0, 50)
        };
      };

      const updatedAcademyItem = processUpdate(updatedAcademy);
      if (updatedAcademyItem) {
        const index = updatedAcademy.findIndex(c => c.id.toString() === courseId.toString());
        updatedAcademy[index] = updatedAcademyItem;
        targetType = 'academy';
      } else {
        const updatedVaultItem = processUpdate(updatedVault);
        if (updatedVaultItem) {
          const index = updatedVault.findIndex(c => c.id.toString() === courseId.toString());
          updatedVault[index] = updatedVaultItem;
          targetType = 'vault';
        }
      }

      if (targetType === 'academy') {
        await supabaseService.updateSiteContent('academy', updatedAcademy);
        return { type: 'academy', data: updatedAcademy };
      } else if (targetType === 'vault') {
        await supabaseService.updateSiteContent('vault', updatedVault);
        return { type: 'vault', data: updatedVault };
      }

      return { type: 'other', courseId, reviews: formattedReviews, rating: newAvgRating };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

export const deleteReviewAsync = createAsyncThunk(
  'content/deleteReview',
  async ({ id, courseId, date, userId }, { getState, rejectWithValue }) => {
    try {
      if (id) {
        await supabaseService.deleteCourseReview(id);
      }

      const state = getState().content;
      let updatedAcademy = [...state.academy];
      let updatedVault = [...state.vault];
      let targetType = null;

      const processDelete = (list) => {
        const index = list.findIndex(c => c.id.toString() === courseId.toString());
        if (index === -1) return null;

        const course = list[index];
        const reviews = [...(course.reviews || [])];

        // Find review by date or userId
        const reviewIndex = reviews.findIndex(r =>
          (userId && r.userId === userId) || (r.date === date)
        );

        if (reviewIndex === -1) return null;

        const removedReview = reviews[reviewIndex];
        reviews.splice(reviewIndex, 1);

        const removedRatingValue = parseFloat(removedReview.rating) || 0;

        let newRating = 0;
        let newStudentCount = Math.max(0, (parseInt(course.students) || 0) - 1);
        const currentRating = parseFloat(course.rating) || 0;
        const oldCount = newStudentCount + 1;

        if (newStudentCount > 0) {
          newRating = ((currentRating * oldCount) - removedRatingValue) / newStudentCount;
        } else {
          newRating = 0.0;
        }

        return {
          ...course,
          rating: newRating.toFixed(1),
          students: newStudentCount,
          reviews: reviews
        };
      };

      const updatedAcademyItem = processDelete(updatedAcademy);
      if (updatedAcademyItem) {
        const index = updatedAcademy.findIndex(c => c.id.toString() === courseId.toString());
        updatedAcademy[index] = updatedAcademyItem;
        targetType = 'academy';
      } else {
        const updatedVaultItem = processDelete(updatedVault);
        if (updatedVaultItem) {
          const index = updatedVault.findIndex(c => c.id.toString() === courseId.toString());
          updatedVault[index] = updatedVaultItem;
          targetType = 'vault';
        }
      }

      const contentState = getState().content;
      const userRole = getState().auth.role;
      if (userRole !== 'admin') {
        const item = updatedAcademyItem || updatedVaultItem;
        return { type: 'other', courseId, reviews: item?.reviews, rating: item?.rating };
      }

      if (targetType === 'academy') {
        await supabaseService.updateSiteContent('academy', updatedAcademy);
        return { type: 'academy', data: updatedAcademy };
      } else if (targetType === 'vault') {
        await supabaseService.updateSiteContent('vault', updatedVault);
        return { type: 'vault', data: updatedVault };
      }

      const finalItem = updatedAcademyItem || updatedVaultItem;
      return { type: 'other', courseId, reviews: finalItem?.reviews, rating: finalItem?.rating };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

export const enrollStudentAsync = createAsyncThunk(
  'content/enrollStudent',
  async ({ courseId, type }, { getState, rejectWithValue }) => {
    try {
      const state = getState().content;
      const user = getState().auth.user;
      let updatedAcademy = [...state.academy];
      let updatedVault = [...state.vault];
      let targetType = null;
      let price = 0;
      let isNewEnrollment = true;

      const processEnrollment = (list) => {
        const index = list.findIndex(c => c.id.toString() === courseId.toString());
        if (index === -1) return null;

        const course = list[index];
        price = course.price || 0;

        // Only increment if it's a new enrollment in the DB
        const newCount = isNewEnrollment ? (parseInt(course.students) || 0) + 1 : (parseInt(course.students) || 0);

        return {
          ...course,
          students: newCount
        };
      };

      // 1. Identify Target Type & Price (Read-Only first)
      const findItem = (list) => list.find(c => c.id.toString() === courseId.toString());

      let identifiedType = type;
      if (!identifiedType) {
        if (findItem(updatedAcademy)) identifiedType = 'academy';
        else if (findItem(updatedVault)) identifiedType = 'vault';
      }

      if (identifiedType === 'academy') targetType = 'academy';
      else if (identifiedType === 'vault') targetType = 'vault';

      // Get price if possible
      if (targetType) {
        const item = targetType === 'academy' ? findItem(updatedAcademy) : findItem(updatedVault);
        if (item) price = item.price || 0;
      }

      // 2. Database Sync (Critical Step)
      if (user?.id && targetType) {
        try {
          // Attempt to enroll. Logic inside supabaseService usually inserts.
          // If insert succeeds, it's new. If it fails with unique constraint, it's existing.
          await supabaseService.enrollUser(user.id, targetType, courseId.toString(), price);
          isNewEnrollment = true;
        } catch (dbErr) {
          if (dbErr.code === '23505' || dbErr.message?.includes('unique constraint')) {
            // User is already enrolled in DB.
            isNewEnrollment = false;
            // We can continue, but we won't increment the global count.
          } else {
            console.error("Database enrollment failed:", dbErr);
            // If other error, we might still want to update local UI? 
            // Better to fail safe.
          }
        }
      } else {
        // Guest user? Always "new" locally but no DB record.
        isNewEnrollment = true;
      }

      // 3. Update Redux Local State (Count) & Site Content
      // If NOT new (duplicate DB), we skip updating the site content (JSON) to prevent count inflation.
      // But we still return the data so Redux state is consistent.

      // If !isNewEnrollment, we might just return early to avoid unnecesary JSON writes.
      if (!isNewEnrollment && user?.id) {
        return { type: 'no-op' };
      }

      let updatedAcademyItem = null;
      let updatedVaultItem = null;

      if (targetType === 'academy') {
        updatedAcademyItem = processEnrollment(updatedAcademy);
        if (updatedAcademyItem) {
          const index = updatedAcademy.findIndex(c => c.id.toString() === courseId.toString());
          updatedAcademy[index] = updatedAcademyItem;
        }
      } else if (targetType === 'vault') {
        updatedVaultItem = processEnrollment(updatedVault);
        if (updatedVaultItem) {
          const index = updatedVault.findIndex(c => c.id.toString() === courseId.toString());
          updatedVault[index] = updatedVaultItem;
        }
      }

      const userRole = getState().auth.role;
      // Only Admin writes the new count to the JSON blob
      if (userRole !== 'admin') {
        // Should we return the incremented count for local display? Yes.
        const item = updatedAcademyItem || updatedVaultItem;
        return { type: 'other', courseId, students: item?.students };
      }

      if (targetType === 'academy') {
        await supabaseService.updateSiteContent('academy', updatedAcademy);
        return { type: 'academy', data: updatedAcademy };
      } else if (targetType === 'vault') {
        await supabaseService.updateSiteContent('vault', updatedVault);
        return { type: 'vault', data: updatedVault };
      }

      const finalItem = updatedAcademyItem || updatedVaultItem;
      return { type: 'other', courseId, students: finalItem?.students };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

export const unenrollStudentAsync = createAsyncThunk(
  'content/unenrollStudent',
  async ({ courseId, type }, { getState, rejectWithValue }) => {
    try {
      const state = getState().content;
      const user = getState().auth.user;
      let updatedAcademy = [...state.academy];
      let updatedVault = [...state.vault];
      let targetType = null;

      if (!user?.id) return rejectWithValue('User not authenticated');

      // 1. Identify Target Type
      const findItem = (list) => list.find(c => c.id.toString() === courseId.toString());

      let identifiedType = type;
      if (!identifiedType) {
        if (findItem(updatedAcademy)) identifiedType = 'academy';
        else if (findItem(updatedVault)) identifiedType = 'vault';
      }

      if (identifiedType === 'academy') targetType = 'academy';
      else if (identifiedType === 'vault') targetType = 'vault';

      // 2. Database Unenrollment (Critical Step)
      if (targetType) {
        await supabaseService.unenrollUser(user.id, targetType, courseId.toString());
      } else {
        return rejectWithValue('Course type could not be determined');
      }

      // 3. Process decrement in global content
      const processUnenrollment = (list) => {
        const index = list.findIndex(c => c.id.toString() === courseId.toString());
        if (index === -1) return null;

        const course = list[index];
        const currentCount = parseInt(course.students) || 0;
        const newCount = Math.max(0, currentCount - 1);

        return {
          ...course,
          students: newCount
        };
      };

      let updatedAcademyItem = null;
      let updatedVaultItem = null;

      if (targetType === 'academy') {
        updatedAcademyItem = processUnenrollment(updatedAcademy);
        if (updatedAcademyItem) {
          const index = updatedAcademy.findIndex(c => c.id.toString() === courseId.toString());
          updatedAcademy[index] = updatedAcademyItem;
        }
      } else if (targetType === 'vault') {
        updatedVaultItem = processUnenrollment(updatedVault);
        if (updatedVaultItem) {
          const index = updatedVault.findIndex(c => c.id.toString() === courseId.toString());
          updatedVault[index] = updatedVaultItem;
        }
      }

      const userRole = getState().auth.role;
      // Only Admin writes the new count to the JSON blob
      if (userRole !== 'admin') {
        const item = updatedAcademyItem || updatedVaultItem;
        return { type: 'other', courseId, students: item?.students };
      }

      if (targetType === 'academy') {
        await supabaseService.updateSiteContent('academy', updatedAcademy);
        return { type: 'academy', data: updatedAcademy };
      } else if (targetType === 'vault') {
        await supabaseService.updateSiteContent('vault', updatedVault);
        return { type: 'vault', data: updatedVault };
      }

      const finalItem = updatedAcademyItem || updatedVaultItem;
      return { type: 'other', courseId, students: finalItem?.students };
    } catch (err) {
      return rejectWithValue(err.message);
    }
  }
);

