const contentSlice = createSlice({
  name: 'content',
  initialState,
  reducers: {
    setSiteContentItem: (state, action) => {
      const { id, data } = action.payload;
      if (id === 'maintenance_mode') state.maintenanceMode = data;
      if (id === 'hero') state.hero = { ...state.hero, ...data };
      if (id === 'cta') state.cta = data;
      if (id === 'stats') state.stats = data;
      if (id === 'academy') state.academy = data;
      if (id === 'vault') state.vault = data;
      if (id === 'instructors') state.instructors = data;
      if (id === 'spotlight') state.spotlight = data;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchAllContent.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchAllContent.fulfilled, (state, action) => {
        state.isLoading = false;
        const siteContent = action.payload.siteContent || {};

        state.allOpportunities = action.payload.opportunities || [];

        // Merge instead of overwrite to preserve defaults if DB keys are missing partial data
        if (siteContent.hero) state.hero = { ...state.hero, ...siteContent.hero };
        if (siteContent.cta) state.cta = { ...state.cta, ...siteContent.cta };
        if (siteContent.stats) state.stats = siteContent.stats;
        if (siteContent.categories) state.categories = siteContent.categories;
        if (siteContent.stories) state.successStories = siteContent.stories;

        if (siteContent.about) {
          const dbAbout = siteContent.about;
          state.about = {
            ...state.about,
            ...dbAbout,
            hero: { ...state.about.hero, ...(dbAbout.hero || {}) },
            mission: { ...state.about.mission, ...(dbAbout.mission || {}) },
            verification: { ...state.about.verification, ...(dbAbout.verification || {}) },
            team: { ...state.about.team, ...(dbAbout.team || {}) },
            impact: { ...state.about.impact, ...(dbAbout.impact || {}) },
            partners: { ...state.about.partners, ...(dbAbout.partners || {}) },
            guidelines: { ...state.about.guidelines, ...(dbAbout.guidelines || {}) },
            disclaimer: { ...state.about.disclaimer, ...(dbAbout.disclaimer || {}) },
            cta: { ...state.about.cta, ...(dbAbout.cta || {}) },
          };
        }

        if (siteContent.contact) {
          const dbContact = siteContent.contact;
          state.contact = {
            ...state.contact,
            ...dbContact,
            hero: { ...state.contact.hero, ...(dbContact.hero || {}) },
            whatsapp: { ...state.contact.whatsapp, ...(dbContact.whatsapp || {}) },
            methods: { ...state.contact.methods, ...(dbContact.methods || {}) },
            faqs: { ...state.contact.faqs, ...(dbContact.faqs || {}) },
            location: { ...state.contact.location, ...(dbContact.location || {}) },
          };
        }

        if (siteContent.maintenance_mode) state.maintenanceMode = siteContent.maintenance_mode;

        const mergeStats = (list) => {
          if (!list) return [];
          return list.map(course => {
            const stats = state.liveStats[course.id.toString()];
            if (stats) {
              return {
                ...course,
                likes: stats.likes !== undefined ? stats.likes : course.likes,
                rating: stats.rating !== undefined ? stats.rating : course.rating,
                reviews: stats.reviews !== undefined ? stats.reviews : course.reviews
              };
            }
            return course;
          });
        };

        if (siteContent.academy) state.academy = mergeStats(siteContent.academy);
        if (siteContent.academy_tracks) state.academyTracks = siteContent.academy_tracks;
        if (siteContent.vault) state.vault = mergeStats(siteContent.vault);
        if (siteContent.instructors) state.instructors = siteContent.instructors;
        if (siteContent.spotlight) state.spotlight = siteContent.spotlight;
        if (siteContent.academy_sample) state.academySample = { ...state.academySample, ...siteContent.academy_sample };
      })
      .addCase(updateInstructorsAsync.fulfilled, (state, action) => {
        state.instructors = action.payload;
      })
      .addCase(fetchAllContent.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload;
      })
      .addCase(updateHeroAsync.fulfilled, (state, action) => {
        state.hero = action.payload;
      })
      .addCase(updateStatsAsync.fulfilled, (state, action) => {
        state.stats = action.payload;
      })
      .addCase(updateCTAAsync.fulfilled, (state, action) => {
        state.cta = action.payload;
      })
      .addCase(updateAboutAsync.fulfilled, (state, action) => {
        state.about = action.payload;
      })
      .addCase(updateContactAsync.fulfilled, (state, action) => {
        state.contact = action.payload;
      })
      .addCase(updateAcademyAsync.fulfilled, (state, action) => {
        state.academy = action.payload;
      })
      .addCase(updateAcademyTracksAsync.fulfilled, (state, action) => {
        state.academyTracks = action.payload;
      })
      .addCase(updateVaultAsync.fulfilled, (state, action) => {
        state.vault = action.payload;
      })
      .addCase(updateSpotlightAsync.fulfilled, (state, action) => {
        state.spotlight = action.payload;
      })
      .addCase(updateAcademySampleAsync.fulfilled, (state, action) => {
        state.academySample = action.payload;
      })
      .addCase(updateStoriesAsync.fulfilled, (state, action) => {
        state.successStories = action.payload;
      })
      .addCase(updateRatingAsync.fulfilled, (state, action) => {
        if (action.payload.type === 'academy') {
          state.academy = action.payload.data;
        } else if (action.payload.type === 'vault') {
          state.vault = action.payload.data;
        } else if (action.payload.type === 'other') {
          const { courseId, reviews, rating } = action.payload;

          // Update Cache
          if (!state.liveStats[courseId.toString()]) state.liveStats[courseId.toString()] = {};
          state.liveStats[courseId.toString()].reviews = reviews;
          state.liveStats[courseId.toString()].rating = rating;

          const update = (list) => {
            const idx = list.findIndex(c => c.id.toString() === courseId.toString());
            if (idx !== -1) {
              list[idx].reviews = reviews;
              list[idx].rating = rating;
            }
          };
          update(state.academy);
          update(state.vault);
        }
      })
      .addCase(fetchReviewsAsync.fulfilled, (state, action) => {
        const { courseId, reviews } = action.payload;

        // Update Cache
        if (!state.liveStats[courseId.toString()]) state.liveStats[courseId.toString()] = {};
        state.liveStats[courseId.toString()].reviews = reviews;

        const calcRating = (revs) => {
          if (!revs || revs.length === 0) return "0.0";
          const total = revs.reduce((sum, r) => sum + r.rating, 0);
          return (total / revs.length).toFixed(1);
        };
        const rating = calcRating(reviews);
        state.liveStats[courseId.toString()].rating = rating;

        const update = (list) => {
          const idx = list.findIndex(c => c.id.toString() === courseId.toString());
          if (idx !== -1) {
            list[idx].reviews = reviews;
            list[idx].rating = rating;
          }
        };
        update(state.academy);
        update(state.vault);
      })
      .addCase(deleteReviewAsync.fulfilled, (state, action) => {
        if (action.payload.type === 'academy') {
          state.academy = action.payload.data;
        } else if (action.payload.type === 'vault') {
          state.vault = action.payload.data;
        } else if (action.payload.type === 'other') {
          const { courseId, reviews, rating } = action.payload;
          const update = (list) => {
            const idx = list.findIndex(c => c.id.toString() === courseId.toString());
            if (idx !== -1) {
              list[idx].reviews = reviews;
              list[idx].rating = rating;
            }
          };
          update(state.academy);
          update(state.vault);
        }
      })
      .addCase(enrollStudentAsync.fulfilled, (state, action) => {
        if (!action.payload) return;
        if (action.payload.type === 'no-op') return;

        if (action.payload.type === 'academy') {
          state.academy = action.payload.data;
        } else if (action.payload.type === 'vault') {
          state.vault = action.payload.data;
        } else if (action.payload.type === 'other') {
          const { courseId, students } = action.payload;
          const update = (list) => {
            const idx = list.findIndex(c => c.id.toString() === courseId.toString());
            if (idx !== -1) {
              list[idx].students = students;
            }
          };
          update(state.academy);
          update(state.vault);
        }
      })
      .addCase(unenrollStudentAsync.fulfilled, (state, action) => {
        if (!action.payload) return;

        if (action.payload.type === 'academy') {
          state.academy = action.payload.data;
        } else if (action.payload.type === 'vault') {
          state.vault = action.payload.data;
        } else if (action.payload.type === 'other') {
          const { courseId, students } = action.payload;
          const update = (list) => {
            const idx = list.findIndex(c => c.id.toString() === courseId.toString());
            if (idx !== -1) {
              list[idx].students = students;
            }
          };
          update(state.academy);
          update(state.vault);
        }
      })
      .addCase(toggleLikeCourseAsync.fulfilled, (state, action) => {
        if (action.payload.type === 'academy') {
          state.academy = action.payload.data;
        } else if (action.payload.type === 'vault') {
          state.vault = action.payload.data;
        } else if (action.payload.type === 'other') {
          const { courseId, likes } = action.payload;

          // Update Cache
          if (!state.liveStats[courseId.toString()]) state.liveStats[courseId.toString()] = {};
          state.liveStats[courseId.toString()].likes = likes;

          const update = (list) => {
            const idx = list.findIndex(c => c.id.toString() === courseId.toString());
            if (idx !== -1) {
              list[idx].likes = likes;
            }
          };
          update(state.academy);
          update(state.vault);
        }
      })
      .addCase(fetchLikesAsync.fulfilled, (state, action) => {
        const { courseId, likes } = action.payload;

        // Update Cache
        if (!state.liveStats[courseId.toString()]) state.liveStats[courseId.toString()] = {};
        state.liveStats[courseId.toString()].likes = likes;

        const update = (list) => {
          const idx = list.findIndex(c => c.id.toString() === courseId.toString());
          if (idx !== -1) {
            list[idx].likes = likes;
          }
        };
        update(state.academy);
        update(state.vault);
      })
      .addCase(addOpportunityAsync.fulfilled, (state, action) => {
        state.allOpportunities.unshift(action.payload);
      })
      .addCase(updateOpportunityAsync.fulfilled, (state, action) => {
        const index = state.allOpportunities.findIndex(o => o.id === action.payload.id);
        if (index !== -1) {
          state.allOpportunities[index] = action.payload;
        }
      })
      .addCase(deleteOpportunityAsync.fulfilled, (state, action) => {
        state.allOpportunities = state.allOpportunities.filter(o => String(o.id) !== String(action.payload));
      })
      .addCase(fetchSavedOpportunitiesAsync.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchSavedOpportunitiesAsync.fulfilled, (state, action) => {
        state.isLoading = false;
        state.savedOpportunities = action.payload;
        // Also update idMap for quick lookup
        action.payload.forEach(opp => {
          state.idMap[opp.id] = true;
        });
      })
      .addCase(fetchSavedOpportunitiesAsync.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload;
      })
      .addCase(toggleSaveOpportunityAsync.fulfilled, (state, action) => {
        const { opportunityId, saved } = action.payload;
        state.idMap[opportunityId] = saved;

        if (saved) {
          // Add to saved list if not already there
          const opp = state.allOpportunities.find(o => o.id === opportunityId);
          if (opp && !state.savedOpportunities.some(o => o.id === opportunityId)) {
            state.savedOpportunities.unshift(opp);
          }
        } else {
          // Remove from saved list
          state.savedOpportunities = state.savedOpportunities.filter(o => o.id !== opportunityId);
        }
      })
      .addCase(toggleLikeOpportunityAsync.fulfilled, (state, action) => {
        const { opportunityId, liked, count } = action.payload;

        // Update liked list
        if (liked) {
          if (!state.likedOpportunities.includes(opportunityId)) {
            state.likedOpportunities.push(opportunityId);
          }
        } else {
          state.likedOpportunities = state.likedOpportunities.filter(id => id !== opportunityId);
        }

        // Update counts in all lists
        const updateCount = (list) => {
          const item = list.find(o => o.id === opportunityId);
          if (item) {
            // If count returned from server, use it. Else estimate.
            if (count !== undefined) item.likes_count = count;
            else item.likes_count = (item.likes_count || 0) + (liked ? 1 : -1);
          }
        };
        updateCount(state.allOpportunities);
        updateCount(state.savedOpportunities);
      })
      .addCase(fetchLikedOpportunitiesAsync.fulfilled, (state, action) => {
        state.likedOpportunities = action.payload;
      })
      .addCase(trackViewAsync.fulfilled, (state, action) => {
        const oppId = action.payload;
        const process = (list) => {
          const item = list.find(o => o.id === oppId);
          if (item) item.views = (item.views || 0) + 1;
        };
        process(state.allOpportunities);
        process(state.savedOpportunities);
      })
      .addCase(trackApplicantAsync.fulfilled, (state, action) => {
        const oppId = action.payload;
        const process = (list) => {
          const item = list.find(o => o.id === oppId);
          if (item) item.applicants = (item.applicants || 0) + 1;
        };
        process(state.allOpportunities);
        process(state.savedOpportunities);
      })
      .addCase(refreshContent.fulfilled, (state, action) => {
        // Silent update: just swap the data, no loading flag change
        state.allOpportunities = action.payload.opportunities;

        const siteContent = action.payload.siteContent;
        if (siteContent) {
          const mergeStats = (list) => {
            if (!list) return [];
            return list.map(course => {
              const stats = state.liveStats[course.id.toString()];
              if (stats) {
                return {
                  ...course,
                  likes: stats.likes !== undefined ? stats.likes : course.likes,
                  rating: stats.rating !== undefined ? stats.rating : course.rating,
                  reviews: stats.reviews !== undefined ? stats.reviews : course.reviews
                };
              }
              return course;
            });
          };

          if (siteContent.academy) state.academy = mergeStats(siteContent.academy);
          if (siteContent.vault) state.vault = mergeStats(siteContent.vault);
          if (siteContent.academy_tracks) state.academyTracks = siteContent.academy_tracks;
          if (siteContent.instructors) state.instructors = siteContent.instructors;
          if (siteContent.spotlight) state.spotlight = siteContent.spotlight;
          if (siteContent.academy_sample) state.academySample = { ...state.academySample, ...siteContent.academy_sample };
          if (siteContent.hero) state.hero = { ...state.hero, ...siteContent.hero };
          if (siteContent.stats) state.stats = siteContent.stats;
          if (siteContent.cta) state.cta = siteContent.cta;
          if (siteContent.maintenance_mode) state.maintenanceMode = siteContent.maintenance_mode;
        }
      })
      .addCase(updateMaintenanceModeAsync.fulfilled, (state, action) => {
        state.maintenanceMode = action.payload;
      });
  },
});

export const { setSiteContentItem } = contentSlice.actions;
export default contentSlice.reducer;
