const REF_KEY = 'luc_discount_ref';
const PROMO_KEY = 'luc_discount_promo';

export function captureDiscountParams() {
    const params = new URLSearchParams(window.location.search);
    const ref = params.get('ref');
    const promo = params.get('promo');

    if (ref) {
        localStorage.setItem(REF_KEY, ref.trim().toUpperCase());
    }
    if (promo) {
        localStorage.setItem(PROMO_KEY, promo.trim().toUpperCase());
    }
}

export function getStoredReferralCode() {
    return localStorage.getItem(REF_KEY) || '';
}

export function getStoredPromoCode() {
    return localStorage.getItem(PROMO_KEY) || '';
}

export function clearStoredDiscountParams() {
    localStorage.removeItem(REF_KEY);
    localStorage.removeItem(PROMO_KEY);
}
