import React from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import CourseCard from '../../academy/components/CourseCard';

import { useSelector } from 'react-redux';
import { normalizeId, compareIds } from '../../../utils/idUtils';
import { supabaseService } from '../../../services/supabaseService';

const AcademyPreview = () => {
    const navigate = useNavigate();
    const user = useSelector((state) => state.auth.user);
    const academyCourses = useSelector((state) => state.content.academy) || [];
    const academyTracks = useSelector((state) => state.content.academyTracks) || [];
    const courseProgress = useSelector((state) => state.activity.courseProgress) || {};
    const featuredCourses = academyCourses.slice(0, 3);
    const [likedCourses, setLikedCourses] = React.useState(() => {
        return JSON.parse(localStorage.getItem('luc_liked_courses') || '[]');
    });
    const [trackEnrollments, setTrackEnrollments] = React.useState([]);

    React.useEffect(() => {
        if (user?.id) {
            supabaseService.getStudentTrackEnrollments(user.id)
                .then(data => setTrackEnrollments(data || []))
                .catch(() => setTrackEnrollments([]));
        }
    }, [user?.id]);

    const handleEnroll = (course) => {
        const cid = normalizeId(course.id);
        const parentTrack = academyTracks.find(t =>
            (t.courses || []).some(cId => compareIds(cId, course.id))
        );
        const isDirectEnrolled = !!courseProgress?.[cid];
        const isTrackEnrolled = parentTrack && trackEnrollments.some(e => compareIds(e.track_id, parentTrack.id));
        const isEnrolledFlag = isDirectEnrolled || isTrackEnrolled;

        if (isEnrolledFlag) {
            navigate(`/academy/course/${course.id}`, { state: { course } });
        } else if (parentTrack) {
            navigate(`/academy?track=${parentTrack.id}`);
        } else {
            navigate(`/academy?enroll=${course.id}`);
        }
    };

    const handleLike = (courseId) => {
        setLikedCourses(prev => {
            const newLiked = prev.includes(courseId)
                ? prev.filter(id => id !== courseId)
                : [...prev, courseId];
            localStorage.setItem('luc_liked_courses', JSON.stringify(newLiked));
            return newLiked;
        });
    };

    return (
    <section className="py-24 bg-slate-900 relative overflow-hidden">
        {/* Background Decorations */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-primary/5 rounded-full blur-3xl -mr-48 -mt-48" />
        <div className="absolute bottom-0 left-0 w-96 h-96 bg-secondary/5 rounded-full blur-3xl -ml-48 -mb-48" />

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
            <div className="flex flex-col md:flex-row md:items-end justify-between mb-16 gap-8">
                <div className="max-w-2xl">
                    <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/5 border border-white/10 mb-6 backdrop-blur-md">
                        <Icon name="GraduationCap" size={14} className="text-secondary" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-white">LUC Global Academy</span>
                    </div>
                    <h2 className="text-4xl md:text-6xl font-black text-white leading-[0.9] italic tracking-tighter">
                        Beyond Discovery, <br />
                        <span className="bg-gradient-to-r from-secondary to-brand-blue bg-clip-text text-transparent">Master Your Future</span>
                    </h2>
                    <p className="mt-6 text-lg text-slate-400 font-medium leading-relaxed">
                        Join an elite league of scholars mastering high-impact skills that win world-class opportunities.
                    </p>
                </div>
                <Button
                    variant="default"
                    size="lg"
                    iconName="ArrowRight"
                    iconPosition="right"
                    className="bg-white text-slate-950 hover:bg-secondary hover:text-white font-black italic rounded-2xl py-6 px-10 shadow-2xl"
                    onClick={() => navigate('/academy')}
                >
                    Explore Curriculum
                </Button>
            </div>

            <div className="flex gap-6 md:gap-10 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide pl-1 lg:pl-0 lg:grid lg:grid-cols-3 lg:gap-10 lg:overflow-visible lg:pb-0">
                {featuredCourses.map((course) => {
                    const cid = normalizeId(course.id);
                    const enrollment = courseProgress?.[cid];
                    const parentTrack = academyTracks.find(t =>
                        (t.courses || []).some(cId => compareIds(cId, course.id))
                    );
                    const isTrackEnrolled = parentTrack && trackEnrollments.some(e => compareIds(e.track_id, parentTrack.id));
                    const isEnrolledFlag = !!enrollment || isTrackEnrolled;
                    const isLikedFlag = likedCourses.includes(cid);

                    return (
                        <div key={course.id} className="animate-in fade-in slide-in-from-bottom-4 duration-700 shrink-0 w-[80vw] sm:w-[60vw] snap-center lg:w-auto lg:shrink lg:snap-align-none">
                            <CourseCard
                                course={{
                                    ...course,
                                    progress: enrollment?.percentage || 0
                                }}
                                isEnrolled={isEnrolledFlag}
                                onEnroll={() => handleEnroll(course)}
                                isLiked={isLikedFlag}
                                onLike={() => handleLike(cid || course.id)}
                                likeCount={(course.likes || 0) + (isLikedFlag ? 1 : 0)}
                            />
                        </div>
                    );
                })}
            </div>

            {/* Mobile CTA */}
            <div className="mt-12 text-center md:hidden">
                <Button
                    variant="outline"
                    fullWidth
                    className="border-white/10 text-white font-black italic rounded-2xl py-6"
                    onClick={() => navigate('/academy')}
                >
                    View All Academy Courses
                </Button>
            </div>
        </div>
    </section>
    );
};

export default AcademyPreview;
