import React, { useState, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Icon from '../AppIcon';
import { supabaseService } from '../../services/supabaseService';
import { useToast } from '../../contexts/ToastContext';
import { cn } from '../../utils/cn';

const StudentNotificationBell = () => {
    const { isAuthenticated, user, role, roles } = useSelector((state) => state.auth);
    const { courseProgress } = useSelector((state) => state.activity);
    
    // Determine if user should see student notifications (anyone authenticated who isn't explicitly viewing admin view)
    const isStudentOrGeneral = isAuthenticated;
    
    const [notifications, setNotifications] = useState([]);
    const [isOpen, setIsOpen] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);
    const dropdownRef = useRef(null);
    const navigate = useNavigate();

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Helper to get persisted arrays
    const getPersistedList = (key) => {
        try {
            return JSON.parse(localStorage.getItem(key)) || [];
        } catch {
            return [];
        }
    };

    // Helper to save to persisted arrays
    const saveToPersistedList = (key, newItems) => {
        try {
            const existing = getPersistedList(key);
            const combined = Array.from(new Set([...existing, ...newItems]));
            localStorage.setItem(key, JSON.stringify(combined));
        } catch (err) {
            console.error('Failed to save to localStorage', err);
        }
    };

    // Initial Fetch & Real-time setup
    useEffect(() => {
        if (!isStudentOrGeneral) return;

        const loadAnnouncements = async () => {
            try {
                const enrolledCourseIds = Object.keys(courseProgress || {});
                const clearedIds = getPersistedList('clearedStudentNotifs');
                const readIds = getPersistedList('readStudentNotifs');

                const announcements = await supabaseService.getStudentAnnouncements(enrolledCourseIds);
                
                let mappedItems = announcements.map(a => ({
                    id: `ann_${a.id}`,
                    type: a.course_id ? 'COURSE_ANNOUNCEMENT' : 'GLOBAL_ANNOUNCEMENT',
                    title: a.title,
                    subtitle: a.content || `Announcement from ${a.instructor?.full_name || 'LUC Academy'}`,
                    date: a.created_at,
                    read: readIds.includes(`ann_${a.id}`),
                    is_critical: a.is_critical,
                    targetPath: '/student-dashboard',
                    targetTab: 'overview'
                }));

                if (user) {
                    // 1. Wallet Transactions (Last 7 days)
                    try {
                        const txs = await supabaseService.getWalletTransactions(user.id);
                        if (txs) {
                            const recentTxs = txs.filter(t => new Date(t.created_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000));
                            mappedItems.push(...recentTxs.map(t => ({
                                id: `tx_${t.id}`,
                                type: 'WALLET_TRANSACTION',
                                title: t.amount > 0 ? `+${t.amount} LUC Earned` : `${t.amount} LUC Spent`,
                                subtitle: t.description || 'Wallet Transaction',
                                date: t.created_at,
                                read: readIds.includes(`tx_${t.id}`),
                                targetPath: '/student-dashboard',
                                targetTab: 'luc-wallet'
                            })));
                        }
                    } catch(e) {}

                    // 2. Achievements / Certificates (Last 30 days)
                    try {
                        const certs = await supabaseService.getStudentCertificates(user.id);
                        if (certs) {
                            const recentCerts = certs.filter(c => new Date(c.issue_date) > new Date(Date.now() - 30 * 24 * 60 * 60 * 1000));
                            mappedItems.push(...recentCerts.map(c => ({
                                id: `cert_${c.id}`,
                                type: 'ACHIEVEMENT',
                                title: 'New Certificate Earned!',
                                subtitle: `You earned a certificate for ${c.course?.title || 'a course'}`,
                                date: c.issue_date,
                                read: readIds.includes(`cert_${c.id}`),
                                targetPath: '/student-dashboard',
                                targetTab: 'badges'
                            })));
                        }
                    } catch(e) {}

                    // 3. Project Squads (Recently joined)
                    try {
                        const squads = await supabaseService.getSquads(user.id);
                        if (squads) {
                            const recentSquads = squads.filter(s => new Date(s.joined_at || s.created_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000));
                            mappedItems.push(...recentSquads.map(s => ({
                                id: `sq_${s.squad_id}`,
                                type: 'SQUAD',
                                title: 'Project Squad Update',
                                subtitle: `You joined ${s.squad?.name || 'a new squad'}`,
                                date: s.joined_at || s.created_at,
                                read: readIds.includes(`sq_${s.squad_id}`),
                                targetPath: '/student-dashboard',
                                targetTab: 'project-squads'
                            })));
                        }
                    } catch(e) {}

                    // 4. Study Mates (Pending requests)
                    try {
                        const { data: mateData } = await supabaseService.supabase
                            .from('study_mates')
                            .select('id, created_at, status, requester:profiles!requester_id(full_name)')
                            .eq('receiver_id', user.id)
                            .eq('status', 'pending');
                        
                        if (mateData) {
                            mappedItems.push(...mateData.map(m => ({
                                id: `mate_${m.id}`,
                                type: 'STUDY_MATE',
                                title: 'New Study Mate Request',
                                subtitle: `${m.requester?.full_name || 'Someone'} wants to connect!`,
                                date: m.created_at,
                                read: readIds.includes(`mate_${m.id}`),
                                targetPath: '/student-dashboard',
                                targetTab: 'study-mates'
                            })));
                        }
                    } catch(e) {}

                    // 5. Payment Requests & Confirmation Statuses
                    try {
                        const { data: myPayments } = await supabaseService.supabase
                            .from('payment_requests')
                            .select('*')
                            .eq('user_id', user.id)
                            .order('created_at', { ascending: false })
                            .limit(10);
                        
                        if (myPayments) {
                            mappedItems.push(...myPayments.map(p => ({
                                id: `pay_${p.id}`,
                                type: p.status === 'confirmed' ? 'PAYMENT_CONFIRMED' : (p.status === 'declined' ? 'PAYMENT_DECLINED' : 'PAYMENT_PENDING'),
                                title: p.status === 'confirmed' 
                                    ? 'Payment Confirmed! 🎉' 
                                    : (p.status === 'declined' ? 'Payment Declined' : 'Payment Processing'),
                                subtitle: p.status === 'confirmed'
                                    ? `Your payment for ${p.course_title} was confirmed!`
                                    : (p.status === 'declined' ? `Payment for ${p.course_title} was declined.` : `Payment receipt submitted for ${p.course_title}`),
                                date: p.updated_at || p.created_at,
                                read: readIds.includes(`pay_${p.id}`),
                                targetPath: p.status === 'confirmed' ? '/student-dashboard' : '/academy',
                                targetTab: 'overview'
                            })));
                        }
                    } catch(e) {}

                    // 6. Upcoming Live Sessions
                    try {
                        const { data: sessions } = await supabaseService.supabase
                            .from('live_sessions')
                            .select('*')
                            .gte('scheduled_at', new Date().toISOString())
                            .order('scheduled_at', { ascending: true })
                            .limit(5);

                        if (sessions) {
                            mappedItems.push(...sessions.map(s => ({
                                id: `session_${s.id}`,
                                type: 'LIVE_SESSION',
                                title: `Upcoming Live Session: ${s.title}`,
                                subtitle: `Scheduled for ${new Date(s.scheduled_at).toLocaleDateString()} at ${new Date(s.scheduled_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`,
                                date: s.scheduled_at,
                                read: readIds.includes(`session_${s.id}`),
                                targetPath: `/academy/live/${s.id}`,
                                targetTab: 'overview'
                            })));
                        }
                    } catch(e) {}
                }

                const allItems = mappedItems
                    .filter(item => !clearedIds.includes(item.id))
                    .sort((a, b) => new Date(b.date) - new Date(a.date));
                
                setNotifications(allItems);
                setUnreadCount(allItems.filter(i => !i.read).length);
            } catch (err) {
                console.error("Failed to load student notifications", err);
            }
        };

        loadAnnouncements();

        // Setup real-time listener for the bell
        const channel = supabaseService.supabase.channel('platform_notifications');
        
        channel.on('broadcast', { event: 'NEW_BROADCAST' }, ({ payload }) => {
            const enrolledCourseIds = Object.keys(courseProgress || {});
            
            // Check if this broadcast is relevant to the student
            // Relevant if it's global (course_id is null/undefined) or they are enrolled in the course
            if (payload.course_id && !enrolledCourseIds.includes(payload.course_id)) {
                return;
            }

            const newId = `ann_${payload.id}`;
            const clearedIds = getPersistedList('clearedStudentNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                type: payload.course_id ? 'COURSE_ANNOUNCEMENT' : 'GLOBAL_ANNOUNCEMENT',
                title: payload.title,
                subtitle: payload.content || 'New Announcement',
                date: new Date().toISOString(),
                read: false,
                is_critical: payload.is_critical,
                targetPath: '/student-dashboard'
            };
            
            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
        });

        channel.subscribe();

        // User-specific payment & enrollment notification channel
        let userChannel = null;
        if (user?.id) {
            userChannel = supabaseService.supabase.channel(`payment_${user.id}`);
            userChannel.on('broadcast', { event: 'PAYMENT_CONFIRMED' }, ({ payload }) => {
                const newId = `pay_confirm_${Date.now()}`;
                const newNotif = {
                    id: newId,
                    type: 'PAYMENT_CONFIRMED',
                    title: 'Payment Confirmed! 🎉',
                    subtitle: `Your payment for ${payload.courseTitle || 'your track'} was confirmed!`,
                    date: new Date().toISOString(),
                    read: false,
                    targetPath: '/student-dashboard',
                    targetTab: 'overview'
                };
                setNotifications(prev => [newNotif, ...prev]);
                setUnreadCount(prev => prev + 1);
            });
            userChannel.subscribe();
        }

        return () => {
            channel.unsubscribe();
            if (userChannel) userChannel.unsubscribe();
        };
    }, [isStudentOrGeneral, courseProgress]);

    if (!isStudentOrGeneral) return null;

    const handleNotificationClick = (notif) => {
        // Mark as read locally and persist
        if (!notif.read) {
            setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
            setUnreadCount(prev => Math.max(0, prev - 1));
            saveToPersistedList('readStudentNotifs', [notif.id]);
        }
        
        setIsOpen(false);
        navigate(notif.targetPath, { state: { tab: notif.targetTab } });
    };

    const markAllAsRead = () => {
        const unreadIds = notifications.filter(n => !n.read).map(n => n.id);
        if (unreadIds.length > 0) {
            saveToPersistedList('readStudentNotifs', unreadIds);
        }
        setNotifications(prev => prev.map(n => ({ ...n, read: true })));
        setUnreadCount(0);
    };

    const clearNotifications = () => {
        const allIds = notifications.map(n => n.id);
        if (allIds.length > 0) {
            saveToPersistedList('clearedStudentNotifs', allIds);
        }
        setNotifications([]);
        setUnreadCount(0);
    };

    const getIconForType = (type, isCritical) => {
        if (isCritical) return 'AlertCircle';
        switch (type) {
            case 'GLOBAL_ANNOUNCEMENT': return 'Globe';
            case 'COURSE_ANNOUNCEMENT': return 'GraduationCap';
            case 'WALLET_TRANSACTION': return 'Coins';
            case 'ACHIEVEMENT': return 'Award';
            case 'SQUAD': return 'Rocket';
            case 'STUDY_MATE': return 'Users';
            case 'PAYMENT_CONFIRMED': return 'CheckCircle2';
            case 'PAYMENT_DECLINED': return 'XCircle';
            case 'PAYMENT_PENDING': return 'Clock';
            case 'LIVE_SESSION': return 'Radio';
            default: return 'Bell';
        }
    };

    const getColorForType = (type, isCritical) => {
        if (isCritical) return "bg-destructive/20 text-destructive";
        switch (type) {
            case 'GLOBAL_ANNOUNCEMENT': return "bg-brand-blue/20 text-brand-blue";
            case 'COURSE_ANNOUNCEMENT': return "bg-primary/20 text-primary";
            case 'WALLET_TRANSACTION': return "bg-amber-500/20 text-amber-500";
            case 'ACHIEVEMENT': return "bg-secondary/20 text-secondary";
            case 'SQUAD': return "bg-purple-500/20 text-purple-500";
            case 'STUDY_MATE': return "bg-success/20 text-success";
            case 'PAYMENT_CONFIRMED': return "bg-success/20 text-success";
            case 'PAYMENT_DECLINED': return "bg-destructive/20 text-destructive";
            case 'PAYMENT_PENDING': return "bg-amber-500/20 text-amber-500";
            case 'LIVE_SESSION': return "bg-red-500/20 text-red-500";
            default: return "bg-primary/20 text-primary";
        }
    };

    return (
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 text-foreground/70 hover:text-primary transition-colors rounded-full hover:bg-muted"
            >
                <Icon name="Bell" size={20} />
                {unreadCount > 0 && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-primary text-white text-[10px] font-bold rounded-full flex items-center justify-center shadow-sm border border-background">
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                )}
            </button>

            {isOpen && (
                <div className="fixed sm:absolute top-[70px] sm:top-auto left-4 right-4 sm:left-auto sm:right-0 sm:mt-2 w-auto sm:w-96 bg-card border border-border rounded-2xl shadow-xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-4 border-b border-border flex items-center justify-between bg-muted/30">
                        <h3 className="font-bold text-sm">Notifications</h3>
                        <div className="flex items-center gap-3">
                            {unreadCount > 0 && (
                                <button 
                                    onClick={markAllAsRead}
                                    className="text-[10px] uppercase tracking-wider font-bold text-primary hover:text-primary/80 transition-colors"
                                >
                                    Mark read
                                </button>
                            )}
                            {notifications.length > 0 && (
                                <button 
                                    onClick={clearNotifications}
                                    className="text-[10px] uppercase tracking-wider font-bold text-destructive hover:text-destructive/80 transition-colors flex items-center gap-1"
                                >
                                    <Icon name="Trash2" size={12} /> Clear all
                                </button>
                            )}
                        </div>
                    </div>

                    <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                        {notifications.length === 0 ? (
                            <div className="p-8 text-center flex flex-col items-center text-muted-foreground">
                                <Icon name="CheckCircle" size={32} className="mb-2 opacity-50" />
                                <p className="text-sm font-medium">You're all caught up!</p>
                                <p className="text-xs opacity-70">No new alerts.</p>
                            </div>
                        ) : (
                            <div className="divide-y divide-border">
                                {notifications.map(notif => (
                                    <div 
                                        key={notif.id}
                                        onClick={() => handleNotificationClick(notif)}
                                        className={cn(
                                            "p-4 hover:bg-muted/50 cursor-pointer transition-colors flex gap-3",
                                            !notif.read ? "bg-primary/5" : ""
                                        )}
                                    >
                                        <div className={cn(
                                            "w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-0.5",
                                            getColorForType(notif.type, notif.is_critical)
                                        )}>
                                            <Icon name={getIconForType(notif.type, notif.is_critical)} size={14} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <p className="text-sm font-bold text-foreground truncate">{notif.title}</p>
                                            <p className="text-xs text-muted-foreground line-clamp-2">{notif.subtitle}</p>
                                            <p className="text-[10px] text-muted-foreground mt-1 font-medium">
                                                {new Date(notif.date).toLocaleDateString()}
                                            </p>
                                        </div>
                                        {!notif.read && (
                                            <div className="w-2 h-2 rounded-full bg-primary shrink-0 self-center" />
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default StudentNotificationBell;
