import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import Icon from '../AppIcon';
import SubmitOpportunityModal from '../../pages/homepage/components/SubmitOpportunityModal';
import PartnershipModal from '../../pages/homepage/components/PartnershipModal';

const Footer = () => {
  const currentYear = new Date()?.getFullYear();
  const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
  const [isPartnershipModalOpen, setIsPartnershipModalOpen] = useState(false);

  const openSubmitModal = (e) => {
    e.preventDefault();
    setIsSubmitModalOpen(true);
  };

  const openPartnershipModal = (e) => {
    e.preventDefault();
    setIsPartnershipModalOpen(true);
  };

  const footerSections = [
    {
      title: 'Platform',
      links: [
        { label: 'Home', path: '/homepage' },
        { label: 'Opportunities', path: '/opportunity-discovery' },
        { label: 'About Us', path: '/about' },
        { label: 'Contact', path: '/contact' },
      ],
    },
    {
      title: 'Resources',
      links: [
        { label: 'LUC Academy', path: '/academy' },
        { label: 'Teach on LUC', path: '/academy/become-instructor' },
        { label: 'Success Stories', path: '/homepage#success-stories' },
        { label: 'Community Guidelines', path: '/about#guidelines' },
      ],
    },
    {
      title: 'Support',
      links: [
        { label: 'Buy us a Coffee', path: '/buy-coffee' },
        { label: 'Help Center', path: '/contact?type=technical#contact-form' },
        { label: 'Report Issue', path: '/contact?type=technical#contact-form' },
        { label: 'Privacy Policy', path: '/about#privacy' },
        { label: 'Terms of Service', path: '/about#terms' },
      ],
    },
    {
      title: 'Connect',
      links: [
        { label: 'WhatsApp Community', path: 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V' },
        { label: 'Partner With Us', path: '/contact?type=partnership#contact-form' },
        { label: 'Submit Opportunity', path: '/contact?type=opportunity#contact-form' },
        { label: 'Share Feedback', path: '/contact?type=feedback#contact-form' },
      ],
    },
  ];

  const socialLinks = [
    { icon: 'Facebook', label: 'Facebook', url: '#' },
    { icon: 'Twitter', label: 'Twitter', url: '#' },
    { icon: 'Instagram', label: 'Instagram', url: '#' },
    { icon: 'Linkedin', label: 'LinkedIn', url: '#' },
  ];

  return (
    <footer className="footer-container">
      <div className="footer-content">
        <div className="footer-grid">
          {footerSections?.map((section) => (
            <div key={section?.title}>
              <h3 className="footer-section-title">{section?.title}</h3>
              <ul className="footer-links">
                {section?.links?.map((link) => (
                  <li key={link?.label}>
                    {link.path.startsWith('http') ? (
                      <a
                        href={link.path}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="footer-link"
                      >
                        {link.label}
                      </a>
                    ) : (link.label === 'Submit Opportunity') ? (
                      <button
                        onClick={openSubmitModal}
                        className="footer-link text-left bg-transparent border-none p-0 cursor-pointer"
                        type="button"
                      >
                        {link.label}
                      </button>
                    ) : (link.label === 'Partner With Us') ? (
                      <button
                        onClick={openPartnershipModal}
                        className="footer-link text-left bg-transparent border-none p-0 cursor-pointer"
                        type="button"
                      >
                        {link.label}
                      </button>
                    ) : (
                      <Link to={link?.path} className="footer-link">
                        {link?.label}
                      </Link>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="footer-bottom">
          <p className="footer-copyright">
            © {currentYear} LUC Hub. Empowering dreams through community-driven discovery.
          </p>
          <div className="footer-social">
            {socialLinks?.map((social) => (
              <a
                key={social?.label}
                href={social?.url}
                className="footer-social-link"
                aria-label={social?.label}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Icon name={social?.icon} size={20} />
              </a>
            ))}
          </div>
        </div>
      </div>
      <SubmitOpportunityModal isOpen={isSubmitModalOpen} onClose={() => setIsSubmitModalOpen(false)} />
      <PartnershipModal isOpen={isPartnershipModalOpen} onClose={() => setIsPartnershipModalOpen(false)} />
    </footer>
  );
};

export default Footer;