import React, { useState, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { logout } from '../../store/authSlice';
import { clearActivity } from '../../store/activitySlice';
import { setMobileMenuOpen } from '../../store/uiSlice';
import Icon from '../AppIcon';
import Button from './Button';
import ThemeToggle from './ThemeToggle';
import { getSessionInfo, formatRemainingTime } from '../../utils/auth/sessionManager';
import UserProfileDropdown from '../UserProfileDropdown';
import ConfirmationModal from './ConfirmationModal';
import AdminNotificationBell from './AdminNotificationBell.jsx';
import StudentNotificationBell from './StudentNotificationBell.jsx';

const Header = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [sessionInfo, setSessionInfo] = useState(null);
  const location = useLocation();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isAuthenticated, user, role, roles } = useSelector((state) => state.auth);
  const { courseProgress } = useSelector((state) => state.activity);

  const isAdmin = role === 'admin' || role === 'moderator' || roles?.includes('admin') || roles?.includes('moderator');
  const isInstructor = role === 'instructor' || role === 'tutor' || roles?.includes('instructor') || roles?.includes('tutor');

  const hasStudentActivity = Object.keys(courseProgress || {}).length > 0;
  const isRegularScholar = !isAdmin && !isInstructor;
  const showStudentDashboard = isRegularScholar || hasStudentActivity;

  // Close mobile menu on route change
  useEffect(() => {
    setIsMobileMenuOpen(false);
    dispatch(setMobileMenuOpen(false));
  }, [location.pathname]);

  // Update session info periodically for mobile menu
  useEffect(() => {
    if (!isMobileMenuOpen || !isAuthenticated) return;

    const updateSessionInfo = () => {
      const info = getSessionInfo();
      setSessionInfo(info);
    };

    updateSessionInfo();
    const interval = setInterval(updateSessionInfo, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, [isMobileMenuOpen, isAuthenticated]);

  const handleLogout = () => {
    dispatch(logout());
    dispatch(clearActivity());
    navigate('/login');
  };

  const getGreeting = () => {
    if (user?.created_at) {
      const created = new Date(user.created_at);
      const now = new Date();
      const diffInHours = (now - created) / (1000 * 60 * 60);
      if (diffInHours < 24) return 'Welcome Aboard,';
    }

    const hour = new Date().getHours();
    if (hour < 12) return 'Good Morning,';
    if (hour < 18) return 'Good Afternoon,';
    return 'Good Evening,';
  };

  const navigationItems = [
    { path: '/homepage', label: 'Home' },
    { path: '/opportunity-discovery', label: 'Opportunities' },
    { path: '/academy', label: 'LUC Academy' },
    { path: '/recruiter-portal', label: 'Hire Talent' },
    { path: '/join-the-build', label: 'Builders' },
    { path: '/store', label: 'Store' },
  ];

  const isActivePath = (path) => location?.pathname === path;
  const isAdminDashboard = location?.pathname === '/admin-dashboard';

  const toggleMobileMenu = () => {
    const next = !isMobileMenuOpen;
    setIsMobileMenuOpen(next);
    dispatch(setMobileMenuOpen(next));
  };

  return (
    <>
      <header className="header-container">
        <div className="header-content">
          <Link to="/homepage" className="header-logo">
            <div className="header-logo-icon flex items-center justify-center overflow-hidden" style={{ backgroundColor: '#ffffff', backgroundImage: 'none', boxShadow: 'none' }}>
              <img src="/luc.ico" alt="LUC logo" className="w-7 h-7 object-contain" />
            </div>
            <span className="header-logo-text flex items-center gap-2.5">
              <span className="text-[#1e40af] dark:text-[#60a5fa] font-black uppercase tracking-tight">LUC</span>
              <span className="text-gradient font-black not-italic">Hub</span>
            </span>
          </Link>

          {!isAdminDashboard && (
            <nav className="header-nav">
              {navigationItems?.map((item) => (
                <Link
                  key={item?.path}
                  to={item?.path}
                  className={`header-nav-link ${isActivePath(item?.path) ? 'active' : ''}`}
                >
                  {item?.label}
                </Link>
              ))}
            </nav>
          )}

          <div className="flex items-center gap-2 sm:gap-3 ml-auto">
            <div className="header-actions">
              <ThemeToggle />

              {/* Authenticated: show profile. Unauthenticated: show Login / Sign up */}
              {isAuthenticated ? (
                <div className="hidden md:flex items-center gap-2">
                  {isAdmin ? <AdminNotificationBell /> : <StudentNotificationBell />}
                  <UserProfileDropdown />
                </div>
              ) : (
                <>
                  <Link to="/login" className="hidden sm:inline-flex">
                    <Button
                      variant="outline"
                      size="sm"
                    >
                      Login
                    </Button>
                  </Link>

                  <Link to="/signup" className="hidden sm:inline-flex">
                    <Button
                      variant="default"
                      size="sm"
                    >
                      Sign Up
                    </Button>
                  </Link>
                </>
              )}
            </div>

            {isAuthenticated && (
              <div className="md:hidden flex items-center justify-center mr-1">
                {isAdmin ? <AdminNotificationBell /> : <StudentNotificationBell />}
              </div>
            )}

            <button
              onClick={toggleMobileMenu}
              className="mobile-menu-button relative z-40 w-11 h-11 sm:w-10 sm:h-10"
              aria-label="Toggle mobile menu"
            >
              <Icon name={isMobileMenuOpen ? 'X' : 'Menu'} size={20} className="relative -top-px sm:top-0" />
            </button>
          </div>
        </div>
      </header>
      <div className={`mobile-menu-overlay ${isMobileMenuOpen ? 'open' : 'closed'}`}>
        <div className="mobile-menu-content">
          <nav className="mobile-menu-nav">
            {navigationItems?.map((item) => (
              <Link
                key={item?.path}
                to={item?.path}
                className={`mobile-menu-link ${isActivePath(item?.path) ? 'active' : ''}`}
                onClick={() => setIsMobileMenuOpen(false)}
              >
                {item?.label}
              </Link>
            ))}
          </nav>

          <div className="flex flex-col gap-3 mt-8">
            {!isAuthenticated ? (
              <>
                <Link to="/login" onClick={() => setIsMobileMenuOpen(false)}>
                  <Button variant="outline" fullWidth size="lg">Login</Button>
                </Link>

                <Link to="/signup" onClick={() => setIsMobileMenuOpen(false)}>
                  <Button variant="default" fullWidth size="lg">Sign Up</Button>
                </Link>
              </>
            ) : (
              <>
                <div className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-gray-800 rounded-xl mb-2">
                  {user?.avatar ? (
                    <img
                      src={user.avatar}
                      alt={user.name}
                      className="w-10 h-10 rounded-full border-2 border-primary object-cover"
                    />
                  ) : (
                    <div className="w-10 h-10 rounded-full bg-gradient-to-r from-primary to-secondary flex items-center justify-center text-white font-bold shrink-0">
                      {user?.name?.charAt(0)?.toUpperCase()}
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-primary font-medium mb-0.5">{getGreeting()}</p>
                    <p className="text-sm font-bold text-gray-900 dark:text-white truncate">{user?.name}</p>
                    <p className="text-xs text-gray-500 dark:text-gray-400 truncate">{user?.email}</p>
                  </div>
                </div>

                {sessionInfo && (
                  <div className="px-3 py-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg mb-2 text-xs text-gray-600 dark:text-gray-400 flex items-center justify-between">
                    <div className="flex items-center gap-1.5">
                      <Icon name="Clock" size={12} />
                      <span>Session remaining:</span>
                    </div>
                    <span className="font-semibold text-primary">{formatRemainingTime()}</span>
                  </div>
                )}

                {isAdmin && (
                  <Link to="/admin-dashboard" onClick={() => setIsMobileMenuOpen(false)} className="w-full">
                    <Button variant="ghost" fullWidth iconName="LayoutDashboard" className="justify-start"> Admin Dashboard</Button>
                  </Link>
                )}

                {(isInstructor || isAdmin) && (
                  <Link to="/instructor-dashboard" onClick={() => setIsMobileMenuOpen(false)} className="w-full">
                    <Button variant="ghost" fullWidth iconName="Presentation" className="justify-start"> Instructor Dashboard</Button>
                  </Link>
                )}

                {showStudentDashboard && (
                  <Link to="/student-dashboard" onClick={() => setIsMobileMenuOpen(false)} className="w-full">
                    <Button variant="ghost" fullWidth iconName="LayoutDashboard" className="justify-start"> Student Dashboard</Button>
                  </Link>
                )}

                <Link to="/profile" onClick={() => setIsMobileMenuOpen(false)} className="w-full">
                  <Button variant="ghost" fullWidth iconName="User" className="justify-start"> Profile Settings</Button>
                </Link>

                <Link to="/profile" state={{ tab: 'preferences' }} onClick={() => setIsMobileMenuOpen(false)} className="w-full">
                  <Button variant="ghost" fullWidth iconName="Settings" className="justify-start"> Preferences</Button>
                </Link>

                <Button
                  variant="ghost"
                  fullWidth
                  iconName="LogOut"
                  className="justify-start text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20"
                  onClick={() => {
                    setIsMobileMenuOpen(false);
                    setShowLogoutConfirm(true);
                  }}
                >
                  Logout
                </Button>
              </>
            )}

            <div className="my-4 border-t border-gray-100 dark:border-gray-800" />

            <Link to="/recruiter-portal" onClick={() => setIsMobileMenuOpen(false)}>
              <Button variant="outline" fullWidth size="lg" iconName="UserCheck" className="justify-start">Hire Talent</Button>
            </Link>
            <Button
              variant="outline"
              fullWidth
              size="lg"
              iconName="MessageCircle"
              iconPosition="left"
              onClick={() => {
                window.open('https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V', '_blank');
                setIsMobileMenuOpen(false);
              }}
            >
              Join Community
            </Button>
            <Button
              variant="default"
              fullWidth
              size="lg"
              onClick={() => setIsMobileMenuOpen(false)}
            >
              Explore Opportunities
            </Button>
          </div>
        </div>
      </div>
      <ConfirmationModal
        isOpen={showLogoutConfirm}
        onClose={() => setShowLogoutConfirm(false)}
        onConfirm={() => {
          handleLogout();
          setShowLogoutConfirm(false);
        }}
        title="Confirm Logout"
        message="Are you sure you want to log out? You will need to sign in again to access your saved opportunities and profile."
        confirmText="Logout"
        cancelText="Cancel"
        type="danger"
      />
    </>
  );
};

export default Header;