import React, { createContext, useContext, useState, useCallback } from 'react';
import { createPortal } from 'react-dom';
import Icon from '../components/AppIcon';
import { cn } from '../utils/cn';

const ToastContext = createContext(null);

export const ToastProvider = ({ children }) => {
    const [toasts, setToasts] = useState([]);

    const addToast = useCallback((message, type = 'success', duration = 3000, onClick = null) => {
        const id = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        setToasts((prev) => [...prev, { id, message, type, onClick }]);

        setTimeout(() => {
            setToasts((prev) => prev.filter((t) => t.id !== id));
        }, duration);
    }, []);

    const removeToast = useCallback((id) => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
    }, []);

    return (
        <ToastContext.Provider value={{ addToast }}>
            {children}
            <div
                className="fixed top-20 left-1/2 -translate-x-1/2 z-[300] flex flex-col items-center gap-3 w-full max-w-md px-4"
                style={{ pointerEvents: 'none' }}
            >
                {toasts.map((toast) => (
                    <div
                        key={toast.id}
                        onClick={() => {
                            if (toast.onClick) {
                                toast.onClick();
                                removeToast(toast.id);
                            }
                        }}
                        className={cn(
                            "flex items-center gap-3 sm:gap-4 px-4 py-2.5 sm:px-6 sm:py-4 rounded-xl shadow-2xl border-2 w-full animate-in slide-in-from-top duration-300 pointer-events-auto",
                            toast.onClick ? "cursor-pointer active:scale-95 transition-transform" : "",
                            toast.type === 'success' && "bg-success border-success text-white",
                            toast.type === 'error' && "bg-error border-error text-white",
                            toast.type === 'warning' && "bg-warning border-warning text-white",
                            toast.type === 'info' && "bg-brand-blue border-brand-blue text-white"
                        )}
                    >
                        <div className="shrink-0 flex items-center justify-center">
                            <Icon
                                name={
                                    toast.type === 'success' ? 'CheckCircle' :
                                        toast.type === 'error' ? 'AlertCircle' :
                                            toast.type === 'warning' ? 'AlertTriangle' : 'Info'
                                }
                                size={typeof window !== 'undefined' && window.innerWidth < 640 ? 18 : 24}
                            />
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-xs sm:text-sm font-bold leading-tight">
                                {toast.message}
                                {toast.onClick && <span className="block text-[10px] opacity-70 mt-1 uppercase">Click to join</span>}
                            </p>
                        </div>
                        <button
                            type="button"
                            onClick={(e) => {
                                e.stopPropagation();
                                removeToast(toast.id);
                            }}
                            className="shrink-0 h-8 w-8 sm:h-9 sm:w-9 flex items-center justify-center rounded-full hover:bg-white/20 transition-colors cursor-pointer"
                        >
                            <Icon name="X" size={typeof window !== 'undefined' && window.innerWidth < 640 ? 16 : 20} className="pointer-events-none" />
                        </button>
                    </div>
                ))}
            </div>
        </ToastContext.Provider>
    );
};

export const useToast = () => {
    const context = useContext(ToastContext);
    if (!context) throw new Error('useToast must be used within ToastProvider');
    return context;
};
