import React, { useState, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Icon from '../AppIcon';
import { supabaseService } from '../../services/supabaseService';
import { useToast } from '../../contexts/ToastContext';
import { cn } from '../../utils/cn';

const AdminNotificationBell = () => {
    const { role, roles } = useSelector((state) => state.auth);
    const isAdmin = role === 'admin' || role === 'moderator' || roles?.includes('admin') || roles?.includes('moderator');
    
    const [notifications, setNotifications] = useState([]);
    const [isOpen, setIsOpen] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);
    const [activeFilter, setActiveFilter] = useState('ALL');
    const dropdownRef = useRef(null);
    const navigate = useNavigate();
    const { addToast } = useToast();

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Helper to get persisted arrays
    const getPersistedList = (key) => {
        try {
            return JSON.parse(localStorage.getItem(key)) || [];
        } catch {
            return [];
        }
    };

    // Helper to save to persisted arrays
    const saveToPersistedList = (key, newItems) => {
        try {
            const existing = getPersistedList(key);
            const combined = Array.from(new Set([...existing, ...newItems]));
            localStorage.setItem(key, JSON.stringify(combined));
        } catch (err) {
            console.error('Failed to save to localStorage', err);
        }
    };

    // Initial Fetch & Real-time setup
    useEffect(() => {
        if (!isAdmin) return;

        const loadPendingItems = async () => {
            try {
                const clearedIds = getPersistedList('clearedAdminNotifs');
                const readIds = getPersistedList('readAdminNotifs');

                // 1. Pending Payments
                let mappedPayments = [];
                try {
                    const payments = await supabaseService.getPaymentRequests('pending');
                    mappedPayments = (payments || []).map(p => ({
                        id: `pay_${p.id}`,
                        category: 'PAYMENTS',
                        type: 'PAYMENT_PENDING',
                        title: `Payment Pending: ₦${Number(p.amount || 0).toLocaleString()}`,
                        subtitle: `${p.user?.full_name || p.user?.email || 'A student'} paid for ${p.course_title || 'a track'}`,
                        date: p.created_at,
                        read: false,
                        targetTab: 'payments'
                    }));
                } catch (e) {}

                // 2. Pending LUC Withdrawals
                let mappedWithdrawals = [];
                try {
                    const withdrawals = await supabaseService.getAllLucWithdrawals();
                    const pendingWithdrawals = (withdrawals || []).filter(w => w.status === 'pending');
                    mappedWithdrawals = pendingWithdrawals.map(w => ({
                        id: `wdr_${w.id}`,
                        category: 'WITHDRAWALS',
                        type: 'WITHDRAWAL_PENDING',
                        title: `Withdrawal Request: ${w.amount_luc} LUC (₦${Number(w.amount_naira || 0).toLocaleString()})`,
                        subtitle: `Requested by ${w.user?.full_name || w.user?.email || 'A user'}`,
                        date: w.created_at,
                        read: false,
                        targetTab: 'withdrawals'
                    }));
                } catch (e) {}

                // 3. Course Drafts
                let mappedDrafts = [];
                try {
                    const drafts = await supabaseService.getPendingCourseDrafts();
                    mappedDrafts = (drafts || []).map(d => ({
                        id: `draft_${d.id}`,
                        category: 'DRAFTS',
                        type: 'COURSE_SUBMISSION',
                        title: `Course Submission: ${d.title}`,
                        subtitle: `Submitted by ${d.instructor?.full_name || 'An Instructor'}`,
                        date: d.updated_at || d.created_at,
                        read: false,
                        targetTab: 'course-drafts'
                    }));
                } catch (e) {}

                // 4. Opportunity Submissions
                let mappedSubmissions = [];
                try {
                    const submissions = await supabaseService.getOpportunitySubmissions();
                    const pendingSubmissions = (submissions || []).filter(s => s.status === 'pending');
                    mappedSubmissions = pendingSubmissions.map(s => ({
                        id: `opp_${s.id}`,
                        category: 'OPPORTUNITIES',
                        type: 'OPPORTUNITY_SUBMISSION',
                        title: `New Opportunity: ${s.title}`,
                        subtitle: `Shared by ${s.submitter_name}`,
                        date: s.created_at,
                        read: false,
                        targetTab: 'submissions'
                    }));
                } catch (e) {}

                // 5. Unread Contact Messages
                let mappedMessages = [];
                try {
                    const messages = await supabaseService.getContactMessages();
                    const unreadMessages = (messages || []).filter(m => m.status === 'unread');
                    mappedMessages = unreadMessages.map(m => ({
                        id: `msg_${m.id}`,
                        category: 'MESSAGES',
                        type: 'CONTACT_MESSAGE',
                        title: `Support Msg: ${m.subject}`,
                        subtitle: `From ${m.full_name}`,
                        date: m.created_at,
                        read: false,
                        targetTab: 'inbox'
                    }));
                } catch (e) {}

                // 6. Summer Camp Parent Registrations
                let mappedCampRegs = [];
                try {
                    const { data: campRegs } = await supabaseService.supabase
                        .from('camp_registrations')
                        .select('*')
                        .order('created_at', { ascending: false })
                        .limit(10);
                    if (campRegs) {
                        mappedCampRegs = campRegs.map(c => ({
                            id: `camp_${c.id}`,
                            category: 'REGISTRATIONS',
                            type: 'CAMP_REGISTRATION',
                            title: `Camp Registration: ${c.studentFullName || 'Student'}`,
                            subtitle: `${c.registration_type === 'parent' ? `Parent: ${c.parent_name || 'Guardian'}` : 'Self-registered'} · ${c.attendanceFormat || 'Online'}`,
                            date: c.created_at,
                            read: false,
                            targetTab: 'camp-parents'
                        }));
                    }
                } catch (e) {}

                const allItems = [
                    ...mappedPayments,
                    ...mappedWithdrawals,
                    ...mappedDrafts,
                    ...mappedSubmissions,
                    ...mappedMessages,
                    ...mappedCampRegs
                ]
                    .filter(item => !clearedIds.includes(item.id))
                    .map(item => ({
                        ...item,
                        read: readIds.includes(item.id)
                    }))
                    .sort((a, b) => new Date(b.date) - new Date(a.date));
                
                setNotifications(allItems);
                setUnreadCount(allItems.filter(i => !i.read).length);
            } catch (err) {
                console.error("Failed to load admin notifications", err);
            }
        };

        loadPendingItems();

        // Setup real-time listener for admin notifications
        const channel = supabaseService.supabase.channel('admin_notifications');
        
        channel.on('broadcast', { event: 'PAYMENT_PENDING' }, ({ payload }) => {
            const newId = `pay_${payload.id || Date.now()}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'PAYMENTS',
                type: 'PAYMENT_PENDING',
                title: `Payment Pending: ₦${Number(payload.amount || 0).toLocaleString()}`,
                subtitle: `${payload.userName || 'A student'} paid for ${payload.courseTitle || 'a track'}`,
                date: new Date().toISOString(),
                read: false,
                targetTab: 'payments'
            };

            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
            addToast(`💰 New Payment Pending from ${payload.userName || 'a student'}`, 'info');
        });

        channel.on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'contact_messages' }, (payload) => {
            const newMsg = payload.new;
            const newId = `msg_${newMsg.id}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'MESSAGES',
                type: 'CONTACT_MESSAGE',
                title: `Support Msg: ${newMsg.subject}`,
                subtitle: `From ${newMsg.full_name}`,
                date: newMsg.created_at || new Date().toISOString(),
                read: false,
                targetTab: 'inbox'
            };

            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
            addToast(`📩 New contact message from ${newMsg.full_name}`, 'info');
        });

        channel.on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'luc_withdrawal_requests' }, (payload) => {
            const newWdr = payload.new;
            const newId = `wdr_${newWdr.id}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'WITHDRAWALS',
                type: 'WITHDRAWAL_PENDING',
                title: `Withdrawal Request: ${newWdr.amount_luc} LUC`,
                subtitle: `Requested cashout of ₦${Number(newWdr.amount_naira || 0).toLocaleString()}`,
                date: newWdr.created_at || new Date().toISOString(),
                read: false,
                targetTab: 'withdrawals'
            };

            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
            addToast(`💸 New LUC Withdrawal Request: ${newWdr.amount_luc} LUC`, 'info');
        });

        channel.on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'camp_registrations' }, (payload) => {
            const newReg = payload.new;
            const newId = `camp_${newReg.id}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'REGISTRATIONS',
                type: 'CAMP_REGISTRATION',
                title: `Camp Registration: ${newReg.studentFullName || 'Student'}`,
                subtitle: `${newReg.registration_type === 'parent' ? `Parent: ${newReg.parent_name || 'Guardian'}` : 'Self-registered'}`,
                date: newReg.created_at || new Date().toISOString(),
                read: false,
                targetTab: 'camp-parents'
            };

            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
            addToast(`🚀 New Camp Registration: ${newReg.studentFullName || 'Student'}`, 'info');
        });

        channel.on('broadcast', { event: 'COURSE_SUBMITTED' }, ({ payload }) => {
            const newId = `draft_${payload.id}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'DRAFTS',
                type: 'COURSE_SUBMISSION',
                title: `Course Submission: ${payload.title}`,
                subtitle: `Submitted by ${payload.instructor_name}`,
                date: payload.submitted_at || new Date().toISOString(),
                read: false,
                targetTab: 'course-drafts'
            };
            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
            addToast(`📚 New Course Submitted: ${payload.title}`, 'info');
        });

        channel.on('broadcast', { event: 'NEW_OPPORTUNITY_SUBMISSION' }, ({ payload }) => {
            const newId = `opp_${payload.id}`;
            const clearedIds = getPersistedList('clearedAdminNotifs');
            if (clearedIds.includes(newId)) return;

            const newNotif = {
                id: newId,
                category: 'OPPORTUNITIES',
                type: 'OPPORTUNITY_SUBMISSION',
                title: `New Opportunity: ${payload.title}`,
                subtitle: `Shared by ${payload.submitter_name}`,
                date: new Date().toISOString(),
                read: false,
                targetTab: 'submissions'
            };
            setNotifications(prev => {
                if (prev.some(n => n.id === newId)) return prev;
                return [newNotif, ...prev];
            });
            setUnreadCount(prev => prev + 1);
        });

        channel.subscribe();

        return () => {
            supabaseService.supabase.removeChannel(channel);
        };
    }, [isAdmin]);

    if (!isAdmin) return null;

    const handleNotificationClick = (notif) => {
        // Mark as read locally and persist
        if (!notif.read) {
            setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
            setUnreadCount(prev => Math.max(0, prev - 1));
            saveToPersistedList('readAdminNotifs', [notif.id]);
        }
        
        setIsOpen(false);
        navigate('/admin-dashboard', { state: { activeTab: notif.targetTab } });
    };

    const markAllAsRead = () => {
        const unreadIds = notifications.filter(n => !n.read).map(n => n.id);
        if (unreadIds.length > 0) {
            saveToPersistedList('readAdminNotifs', unreadIds);
        }
        setNotifications(prev => prev.map(n => ({ ...n, read: true })));
        setUnreadCount(0);
    };

    const clearNotifications = () => {
        const allIds = notifications.map(n => n.id);
        if (allIds.length > 0) {
            saveToPersistedList('clearedAdminNotifs', allIds);
        }
        setNotifications([]);
        setUnreadCount(0);
    };

    const filteredNotifications = activeFilter === 'ALL'
        ? notifications
        : notifications.filter(n => n.category === activeFilter);

    const getIconForType = (type) => {
        switch (type) {
            case 'PAYMENT_PENDING': return 'CreditCard';
            case 'WITHDRAWAL_PENDING': return 'Coins';
            case 'COURSE_SUBMISSION': return 'BookOpen';
            case 'OPPORTUNITY_SUBMISSION': return 'Briefcase';
            case 'CONTACT_MESSAGE': return 'Mail';
            case 'CAMP_REGISTRATION': return 'GraduationCap';
            default: return 'Bell';
        }
    };

    const getColorForType = (type) => {
        switch (type) {
            case 'PAYMENT_PENDING': return "bg-amber-500/20 text-amber-500";
            case 'WITHDRAWAL_PENDING': return "bg-emerald-500/20 text-emerald-500";
            case 'COURSE_SUBMISSION': return "bg-brand-blue/20 text-brand-blue";
            case 'OPPORTUNITY_SUBMISSION': return "bg-purple-500/20 text-purple-500";
            case 'CONTACT_MESSAGE': return "bg-blue-500/20 text-blue-500";
            case 'CAMP_REGISTRATION': return "bg-indigo-500/20 text-indigo-500";
            default: return "bg-primary/20 text-primary";
        }
    };

    const filterTabs = [
        { id: 'ALL', label: 'All', count: notifications.length },
        { id: 'PAYMENTS', label: 'Payments', count: notifications.filter(n => n.category === 'PAYMENTS').length },
        { id: 'WITHDRAWALS', label: 'Withdrawals', count: notifications.filter(n => n.category === 'WITHDRAWALS').length },
        { id: 'DRAFTS', label: 'Drafts', count: notifications.filter(n => n.category === 'DRAFTS').length },
        { id: 'MESSAGES', label: 'Messages', count: notifications.filter(n => n.category === 'MESSAGES').length },
        { id: 'REGISTRATIONS', label: 'Camp', count: notifications.filter(n => n.category === 'REGISTRATIONS').length }
    ];

    return (
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 text-foreground/70 hover:text-primary transition-colors rounded-full hover:bg-muted"
                aria-label="Admin Notifications"
            >
                <Icon name="Bell" size={20} />
                {unreadCount > 0 && (
                    <span className="absolute top-0 right-0 w-4 h-4 bg-destructive text-white text-[10px] font-bold rounded-full flex items-center justify-center shadow-sm border border-background">
                        {unreadCount > 9 ? '9+' : unreadCount}
                    </span>
                )}
            </button>

            {isOpen && (
                <div className="fixed sm:absolute top-[70px] sm:top-auto left-4 right-4 sm:left-auto sm:right-0 sm:mt-2 w-auto sm:w-[420px] bg-card border border-border rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    {/* Header */}
                    <div className="p-4 border-b border-border flex items-center justify-between bg-muted/30">
                        <div className="flex items-center gap-2">
                            <Icon name="ShieldAlert" size={18} className="text-primary" />
                            <h3 className="font-bold text-sm text-foreground">Admin Control Desk</h3>
                            {unreadCount > 0 && (
                                <span className="px-2 py-0.5 text-[10px] font-black uppercase tracking-widest bg-primary/10 text-primary rounded-full">
                                    {unreadCount} New
                                </span>
                            )}
                        </div>
                        <div className="flex items-center gap-3">
                            {unreadCount > 0 && (
                                <button 
                                    onClick={markAllAsRead}
                                    className="text-[10px] uppercase tracking-wider font-bold text-primary hover:text-primary/80 transition-colors"
                                >
                                    Mark read
                                </button>
                            )}
                            {notifications.length > 0 && (
                                <button 
                                    onClick={clearNotifications}
                                    className="text-[10px] uppercase tracking-wider font-bold text-destructive hover:text-destructive/80 transition-colors flex items-center gap-1"
                                >
                                    <Icon name="Trash2" size={12} /> Clear all
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Filter Category Pills */}
                    <div className="flex items-center gap-1.5 p-2 bg-muted/20 border-b border-border overflow-x-auto custom-scrollbar">
                        {filterTabs.map(tab => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveFilter(tab.id)}
                                className={cn(
                                    "px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider whitespace-nowrap transition-all flex items-center gap-1",
                                    activeFilter === tab.id
                                        ? "bg-primary text-white shadow-sm"
                                        : "text-muted-foreground hover:bg-muted hover:text-foreground"
                                )}
                            >
                                {tab.label}
                                {tab.count > 0 && (
                                    <span className={cn(
                                        "px-1.5 py-0.5 text-[9px] rounded-full",
                                        activeFilter === tab.id ? "bg-white/20 text-white" : "bg-muted-foreground/15 text-muted-foreground"
                                    )}>
                                        {tab.count}
                                    </span>
                                )}
                            </button>
                        ))}
                    </div>

                    {/* Notification List */}
                    <div className="max-h-[420px] overflow-y-auto custom-scrollbar">
                        {filteredNotifications.length === 0 ? (
                            <div className="p-8 text-center flex flex-col items-center text-muted-foreground">
                                <Icon name="CheckCircle" size={32} className="mb-2 opacity-50 text-success" />
                                <p className="text-sm font-bold text-foreground">All cleared!</p>
                                <p className="text-xs opacity-70">No pending items in {activeFilter.toLowerCase()} category.</p>
                            </div>
                        ) : (
                            <div className="divide-y divide-border">
                                {filteredNotifications.map(notif => (
                                    <div 
                                        key={notif.id}
                                        onClick={() => handleNotificationClick(notif)}
                                        className={cn(
                                            "p-3.5 hover:bg-muted/50 cursor-pointer transition-all flex gap-3 group relative border-l-4",
                                            !notif.read ? "bg-primary/5 border-primary" : "border-transparent"
                                        )}
                                    >
                                        <div className={cn(
                                            "w-9 h-9 rounded-xl flex items-center justify-center shrink-0 mt-0.5 shadow-sm",
                                            getColorForType(notif.type)
                                        )}>
                                            <Icon name={getIconForType(notif.type)} size={16} />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center justify-between gap-2">
                                                <p className="text-xs font-black text-foreground truncate leading-snug">{notif.title}</p>
                                                <span className="text-[9px] text-muted-foreground whitespace-nowrap shrink-0">
                                                    {new Date(notif.date).toLocaleDateString([], { month: 'short', day: 'numeric' })}
                                                </span>
                                            </div>
                                            <p className="text-xs text-muted-foreground truncate mt-0.5">{notif.subtitle}</p>
                                            <div className="flex items-center gap-2 mt-2">
                                                <span className="text-[9px] font-black uppercase tracking-widest text-primary group-hover:underline flex items-center gap-0.5">
                                                    Review in Dashboard <Icon name="ArrowRight" size={10} />
                                                </span>
                                            </div>
                                        </div>
                                        {!notif.read && (
                                            <div className="w-2 h-2 rounded-full bg-primary shrink-0 self-center" />
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminNotificationBell;
