import React, { useState } from 'react';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import Icon from '../../../components/AppIcon';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';

const PartnershipModal = ({ isOpen, onClose }) => {
    const { addToast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [success, setSuccess] = useState(false);
    const [formData, setFormData] = useState({
        organization_name: '',
        contact_person: '',
        email: '',
        phone: '',
        website: '',
        partnership_type: '',
        message: ''
    });

    const partnershipTypes = [
        { value: 'academic', label: 'Academic Partnership (University/School)' },
        { value: 'corporate', label: 'Corporate Sponsorship' },
        { value: 'ngo', label: 'NGO/Non-Profit Collaboration' },
        { value: 'media', label: 'Media & Community Partner' },
        { value: 'other', label: 'Other Type of Partnership' }
    ];

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            await supabaseService.submitPartnershipRequest(formData);
            setSuccess(true);
            addToast('Partnership request submitted successfully!', 'success');
            setTimeout(() => {
                onClose();
                setSuccess(false);
                setFormData({
                    organization_name: '',
                    contact_person: '',
                    email: '',
                    phone: '',
                    website: '',
                    partnership_type: '',
                    message: ''
                });
            }, 3000);
        } catch (error) {
            console.error('Error submitting partnership:', error);
            addToast('Failed to submit request. Please try again.', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Become a Partner"
            size="xl"
        >
            {success ? (
                <div className="text-center py-12">
                    <div className="w-20 h-20 bg-success/10 rounded-full flex items-center justify-center mx-auto mb-6 text-success">
                        <Icon name="CheckCircle" size={48} />
                    </div>
                    <h3 className="text-2xl font-bold text-primary mb-2">Request Received!</h3>
                    <p className="text-muted-foreground">
                        Thank you for your interest in partnering with LUC Opportunities.
                        Our partnership team will review your information and get back to you shortly.
                    </p>
                </div>
            ) : (
                <form onSubmit={handleSubmit} className="space-y-6">
                    <p className="text-muted-foreground mb-6">
                        Join our mission to democratize access to global opportunities.
                        Tell us about your organization and how you'd like to collaborate.
                    </p>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Organization Name"
                            placeholder="e.g. Stanford University"
                            required
                            value={formData.organization_name}
                            onChange={(e) => handleChange('organization_name', e.target.value)}
                        />
                        <Input
                            label="Contact Person"
                            placeholder="Your Full Name"
                            required
                            value={formData.contact_person}
                            onChange={(e) => handleChange('contact_person', e.target.value)}
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Official Email"
                            type="email"
                            placeholder="partnership@yourorg.com"
                            required
                            value={formData.email}
                            onChange={(e) => handleChange('email', e.target.value)}
                        />
                        <Input
                            label="Phone Number"
                            placeholder="+1 (555) 000-0000"
                            value={formData.phone}
                            onChange={(e) => handleChange('phone', e.target.value)}
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Website URL"
                            placeholder="https://yourorg.com"
                            value={formData.website}
                            onChange={(e) => handleChange('website', e.target.value)}
                        />
                        <Select
                            label="Partnership Type"
                            placeholder="Select type"
                            required
                            options={partnershipTypes}
                            value={formData.partnership_type}
                            onChange={(val) => handleChange('partnership_type', val)}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-foreground mb-2">
                            Partnership Proposal / Message
                        </label>
                        <textarea
                            required
                            rows={4}
                            placeholder="Briefly describe what you'd like to achieve together..."
                            value={formData.message}
                            onChange={(e) => handleChange('message', e.target.value)}
                            className="w-full px-4 py-3 rounded-lg border border-border bg-background text-foreground focus:ring-2 focus:ring-primary/20 transition-all resize-none"
                        />
                    </div>

                    <div className="flex gap-3 pt-4">
                        <Button variant="ghost" fullWidth onClick={onClose} type="button">
                            Cancel
                        </Button>
                        <Button
                            variant="default"
                            fullWidth
                            type="submit"
                            loading={isSubmitting}
                        >
                            Submit Proposal
                        </Button>
                    </div>
                </form>
            )}
        </Modal>
    );
};

export default PartnershipModal;
