import React, { useMemo } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';

const CategorySection = () => {
  const { allOpportunities, categories: dbCategories } = useSelector((state) => state.content);

  const liveCategories = useMemo(() => {
    // If we have categories from DB, use them but update counts
    // Otherwise fallback to defaults
    const baseCategories = dbCategories.length > 0 ? dbCategories : [
      { id: 1, name: "Scholarships", icon: "GraduationCap", color: "from-emerald-500 to-teal-500", description: "Fully-funded and partial scholarships for all levels" },
      { id: 2, name: "Internships", icon: "Briefcase", color: "from-orange-500 to-rose-500", description: "Summer and year-round internships across industries" },
      { id: 3, name: "Fellowships", icon: "Users2", color: "from-blue-600 to-indigo-600", description: "Prestigious leadership and research programs" },
      { id: 4, name: "Competitions", icon: "Trophy", color: "from-amber-400 to-orange-600", description: "Showcase your skills and win prizes" },
      { id: 5, name: "Jobs", icon: "Target", color: "from-purple-500 to-pink-500", description: "Entry-level and professional career opportunities" },
      { id: 6, name: "Conferences", icon: "Globe", color: "from-cyan-500 to-blue-500", description: "Global events and networking opportunities" }
    ];

    return baseCategories.map(cat => ({
      ...cat,
      count: (allOpportunities || []).filter(opp => {
        const oppCat = (opp.category || '').toLowerCase();
        const catName = (cat.name || '').toLowerCase();
        // Match if identical, or if one contains the other (handling singular/plural)
        return oppCat === catName ||
          oppCat.includes(catName.replace(/s$/, '')) ||
          catName.includes(oppCat.replace(/s$/, ''));
      }).length
    }));
  }, [allOpportunities, dbCategories]);

  return (
    <section className="py-20 md:py-24 lg:py-32 bg-slate-950 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 left-1/4 w-64 h-64 bg-primary/5 blur-[100px] rounded-full" />
      <div className="absolute bottom-0 right-1/4 w-64 h-64 bg-secondary/5 blur-[100px] rounded-full" />

      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 relative z-10">
        <div className="text-center mb-16 md:mb-20">
          <h2 className="text-3xl md:text-5xl lg:text-6xl font-black text-white mb-6 italic tracking-tight">
            Discover Your <span className="bg-gradient-to-r from-secondary to-brand-blue bg-clip-text text-transparent">Path</span>
          </h2>
          <p className="text-base md:text-lg text-slate-400 max-w-2xl mx-auto font-medium">
            Tailored opportunities curated for the next generation of global achievers.
          </p>
        </div>

        <div className="flex gap-4 overflow-x-auto pb-4 snap-x snap-mandatory scrollbar-hide pl-1 lg:pl-0 lg:grid lg:grid-cols-3 lg:gap-8 lg:overflow-visible lg:pb-0">
          {liveCategories?.map((category) => (
            <Link
              key={category?.id}
              to="/opportunity-discovery"
              className="group relative bg-white/5 backdrop-blur-xl rounded-2xl p-5 sm:p-8 border border-white/5 hover:border-secondary/30 transition-all duration-500 hover:-translate-y-2 shadow-2xl shrink-0 w-[75vw] sm:w-[60vw] snap-center lg:w-auto lg:shrink lg:snap-align-none"
            >
              <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 rounded-2xl sm:rounded-[2rem]" />
              
              {category?.count > 5 && (
                <div className="absolute top-4 right-4 sm:top-6 sm:right-6 px-2.5 py-0.5 sm:px-3 sm:py-1 bg-secondary/20 text-secondary text-[9px] sm:text-[10px] font-black uppercase tracking-widest rounded-full flex items-center gap-1 border border-secondary/20">
                  <Icon name="TrendingUp" size={10} />
                  <span>Trending</span>
                </div>
              )}

              <div className={`w-12 h-12 sm:w-16 sm:h-16 rounded-xl sm:rounded-2xl bg-gradient-to-br ${category?.color} flex items-center justify-center mb-5 sm:mb-8 group-hover:scale-110 group-hover:rotate-3 transition-all duration-500 shadow-lg`}>
                <Icon name={category?.icon || 'Briefcase'} size={22} color="white" className="sm:hidden" />
                <Icon name={category?.icon || 'Briefcase'} size={28} color="white" className="hidden sm:block" />
              </div>

              <h3 className="text-lg sm:text-xl md:text-2xl font-black text-white mb-2 sm:mb-3 italic tracking-tight">
                {category?.name}
              </h3>
              <p className="text-xs sm:text-sm md:text-base text-slate-400 mb-5 sm:mb-8 font-medium leading-relaxed line-clamp-2">
                {category?.description}
              </p>

              <div className="flex items-center justify-between pt-4 sm:pt-6 border-t border-white/5">
                <div className="flex items-center gap-1.5 sm:gap-2 text-secondary">
                  <Icon name="FileText" size={14} className="sm:hidden" />
                  <Icon name="FileText" size={16} className="hidden sm:block" />
                  <span className="text-[10px] sm:text-xs font-black uppercase tracking-widest">{category?.count} Available</span>
                </div>
                <div className="w-8 h-8 sm:w-10 sm:h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 group-hover:bg-secondary group-hover:text-white transition-all duration-500">
                  <Icon name="ArrowRight" size={16} className="sm:hidden" />
                  <Icon name="ArrowRight" size={20} className="hidden sm:block" />
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
};

export default CategorySection;