import React, { useEffect } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { hasAnyRole, hasPermission } from './rbac';

/**
 * ProtectedRoute component wrapper for role-based access control
 * Redirects to login if not authenticated
 * Redirects to unauthorized if user lacks required role/permission
 */
export const ProtectedRoute = ({
  element,
  allowedRoles = [],
  requiredPermission = null,
  fallbackPath = '/login',
}) => {
  const navigate = useNavigate();
  const { isAuthenticated, role, roles: userRolesArray } = useSelector((state) => state.auth);

  useEffect(() => {
    // Check if user is authenticated
    if (!isAuthenticated) {
      navigate(fallbackPath);
      return;
    }

    // Check if user has required role
    const hasRequiredRole = allowedRoles.length === 0 || 
      hasAnyRole(role, allowedRoles) || 
      (Array.isArray(userRolesArray) && userRolesArray.some(r => allowedRoles.includes(r)));

    if (allowedRoles.length > 0 && !hasRequiredRole) {
      navigate('/unauthorized');
      return;
    }

    // Check if user has required permission
    if (requiredPermission && !hasPermission(role, requiredPermission)) {
      navigate('/unauthorized');
      return;
    }
  }, [isAuthenticated, role, allowedRoles, requiredPermission, navigate, fallbackPath]);

  if (!isAuthenticated) {
    return null;
  }

  const hasRequiredRole = allowedRoles.length === 0 || 
    hasAnyRole(role, allowedRoles) || 
    (Array.isArray(userRolesArray) && userRolesArray.some(r => allowedRoles.includes(r)));

  if (allowedRoles.length > 0 && !hasRequiredRole) {
    return null;
  }

  if (requiredPermission && !hasPermission(role, requiredPermission)) {
    return null;
  }

  return element;
};

/**
 * Hook to check authorization
 * Returns authorization status and redirect function
 */
export const useAuthorization = (allowedRoles = [], requiredPermission = null) => {
  const { isAuthenticated, role, roles: userRolesArray } = useSelector((state) => state.auth);
  const navigate = useNavigate();

  const isAuthorized =
    isAuthenticated &&
    (allowedRoles.length === 0 || hasAnyRole(role, allowedRoles) || (Array.isArray(userRolesArray) && userRolesArray.some(r => allowedRoles.includes(r)))) &&
    (!requiredPermission || hasPermission(role, requiredPermission));

  const redirectIfUnauthorized = (fallbackPath = '/login') => {
    if (!isAuthorized) {
      navigate(fallbackPath);
    }
  };

  return {
    isAuthorized,
    isAuthenticated,
    role,
    redirectIfUnauthorized,
  };
};

/**
 * Hook to check if user can access certain features
 */
export const useCanAccess = (allowedRoles = [], requiredPermission = null) => {
  const { isAuthenticated, role, roles: userRolesArray } = useSelector((state) => state.auth);

  return (
    isAuthenticated &&
    (allowedRoles.length === 0 || hasAnyRole(role, allowedRoles) || (Array.isArray(userRolesArray) && userRolesArray.some(r => allowedRoles.includes(r)))) &&
    (!requiredPermission || hasPermission(role, requiredPermission))
  );
};

/**
 * Wrapper component for role-based rendering
 * Only renders children if user has required access
 */
export const RoleGate = ({
  children,
  allowedRoles = [],
  requiredPermission = null,
  fallback = null,
}) => {
  const canAccess = useCanAccess(allowedRoles, requiredPermission);

  if (!canAccess) {
    return fallback;
  }

  return children;
};

export default ProtectedRoute;
