import React, { useEffect } from "react";
import { Provider, useDispatch, useSelector } from "react-redux";
import Routes from "./Routes";
import { ThemeProvider } from "./contexts/ThemeContext";
import SessionWarningModal from "./components/ui/SessionWarningModal";
import ScrollToTopButton from "./components/ui/ScrollToTopButton";
import store from "./store/store";
import { fetchAllContent, refreshContent, setSiteContentItem, enrollStudentAsync } from "./store/contentSlice";
import { syncUserActivity, startCourse } from "./store/activitySlice";
import { supabaseService } from "./services/supabaseService";
import { ToastProvider } from "./contexts/ToastContext";

import SplashScreen from "./components/ui/SplashScreen";
import GlobalChat from './components/chat/GlobalChat';
import LiveSessionBanner from './components/academy/LiveSessionBanner';
import BroadcastBanner from './components/academy/BroadcastBanner';
import SecurityGuard from "./components/security/SecurityGuard";
import { useToast } from "./contexts/ToastContext";
import { useNavigate, useLocation, BrowserRouter } from "react-router-dom";
import NetworkStatusIndicator from "./components/ui/NetworkStatusIndicator";

import MaintenanceMode from "./pages/errors/MaintenanceMode";
import { initGA, trackPageView } from "./utils/analytics";
import { captureDiscountParams } from "./utils/discountParams";
import { useFaviconBadge } from "./hooks/useFaviconBadge";
import { useTrafficSentinel } from "./hooks/useTrafficSentinel";
import LegalOnboardingOverlay from "./components/security/LegalOnboardingOverlay";
import { updateUserDetails } from "./store/authSlice";

const AppContent = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const { addToast } = useToast();
    const [showSplash, setShowSplash] = React.useState(true);
    const { user, role, roles, isAuthenticated } = useSelector(state => state.auth);
    const siteContent = useSelector(state => state.content.siteContent);
    const maintenanceMode = useSelector(state => state.content.maintenanceMode);
    const isMaintenanceMode = maintenanceMode?.active;

    // Activate Favicon Notification Badge
    useFaviconBadge();

    // Activate Traffic Sentinel (Internal Precision Tracking)
    useTrafficSentinel();

    // Ironclad Onboarding Check: Builders and Instructors must sign the contract
    const needsLegalSigning = isAuthenticated && 
        (roles?.includes('builder') || roles?.includes('instructor')) && 
        user?.legal_status !== 'signed' && 
        !showSplash;

    useEffect(() => {
        // Refresh legal status if missing from initial session
        const verifyLegalStatus = async () => {
            if (isAuthenticated && (roles?.includes('builder') || roles?.includes('instructor')) && !user?.legal_status) {
                const profile = await supabaseService.getProfile(user.id);
                if (profile?.legal_status) {
                    dispatch(updateUserDetails({ legal_status: profile.legal_status }));
                }
            }
        };
        verifyLegalStatus();
    }, [isAuthenticated, user?.id, roles]);

    useEffect(() => {
        // Initialize GA from DB config if available, otherwise fallback to ENV
        const gaConfig = siteContent?.analytics_config;
        initGA(gaConfig?.measurementId);
    }, [siteContent?.analytics_config]);

    useEffect(() => {
        dispatch(fetchAllContent());

        // Capture referral/promo codes from URL before they get consumed
        captureDiscountParams();

        // Track page view on route change
        trackPageView(location.pathname + location.search);

        // Silent Refresh on navigation to ensure data is always fresh
        if (window.lucSplashFinished) {
            dispatch(refreshContent());
        }
    }, [dispatch, location.pathname, location.search]);

    // Use a ref to prevent multiple triggers in a single session/render cycle
    const isProcessingReward = React.useRef(false);

    useEffect(() => {
        if (user?.id && !isProcessingReward.current) {
            dispatch(syncUserActivity(user.id));

            // Daily Login Reward Check
            const lastReward = localStorage.getItem(`luc_last_login_reward_${user.id}`);
            const today = new Date().toISOString().split('T')[0];
            
            if (lastReward !== today) {
                isProcessingReward.current = true;
                // Optimistically set today to prevent concurrent triggers
                localStorage.setItem(`luc_last_login_reward_${user.id}`, today);

                supabaseService.processWalletTransaction(
                    user.id,
                    5, 
                    'daily_login',
                    'Daily Login Reward',
                    `login_${user.id}_${today}`
                ).then(res => {
                    if (res?.success) {
                        setTimeout(() => {
                            addToast("Welcome back! +5 LUC Credits awarded. ☀️", "success");
                        }, 5000);
                    } else {
                        // If it failed and wasn't because of a duplicate constraint, 
                        // we might want to clear it, but usually best to leave it 
                        // to avoid spamming the RPC on every re-render.
                    }
                }).catch(() => {
                    // Silently fail, we've already marked today as attempted in localStorage
                }).finally(() => {
                    isProcessingReward.current = false;
                });
            }
        }

        // 1. Realtime Sync: Listen for site content changes (Spotlight, Hero, Stats)
        const contentChannel = supabaseService.subscribeToTable('site_content', (payload) => {
            if (payload.new) {
                dispatch(setSiteContentItem({ id: payload.new.id, data: payload.new.data }));
            }
            dispatch(refreshContent());
        });

        // 1.5. Dedicated System Broadcasts (Cannot be killed by component unmounts)
        const systemChannel = supabaseService.supabase.channel('system_broadcasts');
        systemChannel
            .on('broadcast', { event: 'MAINTENANCE_TOGGLE' }, ({ payload }) => {
                dispatch(setSiteContentItem({ id: 'maintenance_mode', data: payload }));
            })
            .subscribe();

        // 2. Global Notifications: Listen for new Live Sessions
        const notificationChannel = supabaseService.supabase.channel('platform_notifications');
        
        notificationChannel
            .on('broadcast', { event: 'NEW_LIVE_SESSION' }, ({ payload }) => {
                addToast(
                    `${payload.hostName} is live now: "${payload.title}"! Join them in the Academy.`, 
                    "success",
                    10000, // Show for 10 seconds
                    () => navigate('/academy') // Join action
                );
            })
            .on('broadcast', { event: 'LOBBY_INVITE' }, ({ payload }) => {
                if (payload.targetUserId === user?.id) {
                    addToast(
                        `${payload.hostName} added you to a ${payload.isScheduled ? 'scheduled' : 'live'} brainstorm lobby: "${payload.title}"!`, 
                        "info",
                        8000
                    );
                }
            })
            .on('broadcast', { event: 'SESSION_APPROVED' }, ({ payload }) => {
                const isMember = payload.hostId === user?.id || (payload.invitedMemberIds && payload.invitedMemberIds.includes(user?.id));
                if (isMember) {
                    addToast(
                        `Room Approved: "${payload.title}" is now ${payload.status === 'live' ? 'LIVE' : 'scheduled'}!`, 
                        "success",
                        15000,
                        payload.status === 'live' ? () => navigate(`/academy/live/${payload.meetingId}`) : null
                    );
                }
            })
            .subscribe();

        // 3. Payment Confirmation: Listen for admin confirming/rejecting bank transfers
        const paymentChannel = user?.id
            ? supabaseService.supabase.channel(`payment_${user.id}`)
            : null;

        if (paymentChannel) {
            paymentChannel
                .on('broadcast', { event: 'PAYMENT_CONFIRMED' }, ({ payload }) => {
                    dispatch(syncUserActivity(user.id));
                    if (payload.isTrack && payload.trackId) {
                        const academyContent = store.getState().content.academy || [];
                        const track = academyContent.find(c => c.isTrack && String(c.id) === String(payload.trackId));
                        if (track?.courses) {
                            track.courses.forEach(cId => {
                                dispatch(enrollStudentAsync({ courseId: cId, type: 'academy' }));
                                dispatch(startCourse({ courseId: cId }));
                            });
                        }
                    } else if (payload.courseId) {
                        dispatch(enrollStudentAsync({ courseId: payload.courseId, type: 'academy' }));
                        dispatch(startCourse({ courseId: payload.courseId }));
                    }
                    addToast(
                        `Payment confirmed! "${payload.courseTitle}" is now unlocked. Happy learning!`,
                        "success",
                        8000
                    );
                })
                .on('broadcast', { event: 'PAYMENT_REJECTED' }, ({ payload }) => {
                    addToast(
                        `Your payment for "${payload.courseTitle}" was not verified. Please contact support.`,
                        "error",
                        8000
                    );
                })
                .subscribe();
        }

        // 3. Silent Refresh: Re-fetch everything every 5 minutes as a fallback
        const intervalId = setInterval(() => {
            dispatch(refreshContent());
        }, 5 * 60 * 1000);

        return () => {
            clearInterval(intervalId);
            supabaseService.unsubscribe(contentChannel);
            systemChannel.unsubscribe();
            notificationChannel.unsubscribe();
            paymentChannel?.unsubscribe();
        };
    }, [dispatch, user?.id, addToast]);

    return (
        <SecurityGuard timeoutMinutes={30}>
            {showSplash && <SplashScreen onFinish={() => {
                setShowSplash(false);
                window.lucSplashFinished = true;
            }} />}
            
            {needsLegalSigning && (
                <LegalOnboardingOverlay 
                    user={user} 
                    onComplete={() => dispatch(updateUserDetails({ legal_status: 'signed' }))} 
                />
            )}

            {isMaintenanceMode && role !== 'admin' && !roles?.includes('admin') && !location.pathname.startsWith('/admin') && !location.pathname.startsWith('/login') && !location.pathname.startsWith('/signup') ? (
                <div className={`transition-opacity duration-1000 ${showSplash ? 'opacity-0' : 'opacity-100'}`}>
                    <MaintenanceMode />
                </div>
            ) : (
                <div className={`transition-opacity duration-1000 ${showSplash ? 'opacity-0' : 'opacity-100'}`}>
                    {/* Network Quality Indicator — always on top */}
                    <NetworkStatusIndicator />

                    {/* Global Notification Stack */}
                    <div className="fixed top-20 left-0 right-0 z-[100] flex flex-col pointer-events-none">
                        <LiveSessionBanner />
                        <BroadcastBanner />
                    </div>
                    
                    <Routes />
                    {!location.pathname.startsWith('/opportunity-detail') && <GlobalChat />}
                </div>
            )}
        </SecurityGuard>
    );
};

function App() {
  return (
    <Provider store={store}>
      <ThemeProvider>
        <ToastProvider>
          <BrowserRouter>
            <AppContent />
          </BrowserRouter>
        </ToastProvider>
      </ThemeProvider>
    </Provider>
  );
}


export default App;
