import React from 'react';
import { useNavigate } from 'react-router-dom';
import Modal from './Modal';
import Button from './Button';
import Icon from '../AppIcon';

const AuthRequiredModal = ({ isOpen, onClose, context = 'default', redirectTo = null }) => {
    const navigate = useNavigate();

    const handleNavigate = (path) => {
        navigate(path, { state: { from: redirectTo } });
        onClose();
    };

    const content = {
        live: {
            title: "Join the Conversation",
            message: "To jump into this live brainstorm, chat with members, and collaborate in real-time, you'll need to join the LUC community.",
            icon: "Radio"
        },
        host: {
            title: "Start Your Brainstorm",
            message: "To host your own rooms, lead discussions, and share your screen with the community, please login or sign up.",
            icon: "Zap"
        },
        default: {
            title: "Join the Community",
            message: "To access this premium feature and collaborate with other students, you need to be part of the LUC Academy.",
            icon: "Lock"
        }
    };

    const activeContent = content[context] || content.default;

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={activeContent.title}
            size="sm"
        >
            <div className="space-y-6 text-center py-4">
                <div className="w-20 h-20 bg-brand-blue/10 rounded-full flex items-center justify-center mx-auto mb-2 relative">
                    <Icon name={activeContent.icon} className="text-brand-blue" size={40} />
                    {context === 'live' && (
                        <span className="absolute top-4 right-4 w-3 h-3 bg-red-500 rounded-full animate-ping" />
                    )}
                </div>
                
                <div className="space-y-2">
                    <h3 className="text-xl font-black italic tracking-tight text-white uppercase">{activeContent.title}</h3>
                    <p className="text-sm text-slate-400 px-2 leading-relaxed">
                        {activeContent.message}
                    </p>
                </div>

                <div className="grid grid-cols-1 gap-3 pt-4">
                    <Button 
                        fullWidth 
                        onClick={() => handleNavigate('/login')}
                        className="font-black italic"
                    >
                        LOGIN TO HUB
                    </Button>
                    <Button 
                        variant="secondary" 
                        fullWidth 
                        onClick={() => handleNavigate('/signup')}
                        className="font-black italic"
                    >
                        SIGN UP FOR FREE
                    </Button>
                    <button 
                        onClick={onClose}
                        className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 hover:text-white transition-colors pt-2"
                    >
                        KEEP BROWSING
                    </button>
                </div>
            </div>
        </Modal>
    );
};

export default AuthRequiredModal;
