import React, { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { refreshContent } from '../../store/contentSlice';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import HeroSection from './components/HeroSection';
import CategorySection from './components/CategorySection';
import TrendingOpportunities from './components/TrendingOpportunities';
import AcademyPreview from './components/AcademyPreview';
import CommunityStats from './components/CommunityStats';
import CTASection from './components/CTASection';
import HallOfFameShowcase from '../academy/components/HallOfFameShowcase';
import NewsletterSection from './components/NewsletterSection';
import SummerCampBanner from '../academy/components/SummerCampBanner';

const Homepage = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  useEffect(() => {
    // Silent Refresh: Content on the homepage should stay fresh
    // This runs every 60 seconds while the user is looking at the landing page
    const interval = setInterval(() => {
      dispatch(refreshContent());
    }, 60 * 1000);

    return () => clearInterval(interval);
  }, [dispatch]);
  return (
    <div className="min-h-screen flex flex-col bg-[var(--color-background)]">
      <Header />

      <main className="flex-1">
        <SummerCampBanner onEnroll={() => navigate('/academy#tracks')} />
        <HeroSection />
        <CategorySection />
        <TrendingOpportunities />
        <AcademyPreview />
        <HallOfFameShowcase />
        <NewsletterSection />
        <CTASection />
      </main>

      <Footer />
    </div>
  );
};

export default Homepage;