/**
 * Role-based access control utilities
 */

// Define role hierarchy and permissions
export const ROLES = {
  ADMIN: 'admin',
  MODERATOR: 'moderator',
  VIEWER: 'viewer',
};

// Define permissions for each role
export const ROLE_PERMISSIONS = {
  admin: [
    'view_dashboard',
    'manage_opportunities',
    'manage_users',
    'moderate_content',
    'send_announcements',
    'view_analytics',
    'manage_admins',
    'export_reports',
  ],
  moderator: [
    'view_dashboard',
    'manage_opportunities',
    'moderate_content',
    'send_announcements',
    'view_analytics',
  ],
  viewer: [
    'view_dashboard',
  ],
};

/**
 * Check if a user has a specific role
 * @param {string} userRole - The user's current role
 * @param {string} requiredRole - The required role to check
 * @returns {boolean}
 */
export const hasRole = (userRole, requiredRole) => {
  if (!userRole || !requiredRole) return false;
  return userRole === requiredRole;
};

/**
 * Check if a user has a specific permission
 * @param {string} userRole - The user's current role
 * @param {string} permission - The required permission
 * @returns {boolean}
 */
export const hasPermission = (userRole, permission) => {
  if (!userRole) return false;
  const permissions = ROLE_PERMISSIONS[userRole] || [];
  return permissions.includes(permission);
};

/**
 * Check if a user has any of the specified roles
 * @param {string} userRole - The user's current role
 * @param {string[]} roles - Array of allowed roles
 * @returns {boolean}
 */
export const hasAnyRole = (userRole, roles) => {
  if (!userRole || !Array.isArray(roles)) return false;
  return roles.includes(userRole);
};

/**
 * Check if a user has all of the specified permissions
 * @param {string} userRole - The user's current role
 * @param {string[]} permissions - Array of required permissions
 * @returns {boolean}
 */
export const hasAllPermissions = (userRole, permissions) => {
  if (!userRole || !Array.isArray(permissions)) return false;
  return permissions.every((perm) => hasPermission(userRole, perm));
};

/**
 * Get all permissions for a role
 * @param {string} userRole - The user's current role
 * @returns {string[]}
 */
export const getRolePermissions = (userRole) => {
  return ROLE_PERMISSIONS[userRole] || [];
};

/**
 * Check if a user can perform a certain action based on role hierarchy
 * Admin > Moderator > Viewer
 * @param {string} userRole - The user's current role
 * @param {number} requiredLevel - The minimum role level required (0=viewer, 1=moderator, 2=admin)
 * @returns {boolean}
 */
export const hasMinimumRoleLevel = (userRole, requiredLevel) => {
  const roleLevels = {
    viewer: 0,
    moderator: 1,
    admin: 2,
  };
  const userLevel = roleLevels[userRole] || -1;
  return userLevel >= requiredLevel;
};
