import React from 'react';
import Modal from './Modal';
import Button from './Button';
import Icon from '../AppIcon';

const ConfirmationModal = ({
    isOpen,
    onClose,
    onConfirm,
    title = "Are you sure?",
    message,
    confirmText = "Confirm",
    cancelText = "Cancel",
    type = "danger",
    isLoading = false,
    isLocal = false
}) => {
    const typeConfigs = {
        danger: {
            icon: "AlertTriangle",
            color: "text-destructive",
            bg: "bg-destructive/10",
            btnVariant: "danger"
        },
        warning: {
            icon: "AlertCircle",
            color: "text-warning",
            bg: "bg-warning/10",
            btnVariant: "warning"
        },
        info: {
            icon: "Info",
            color: "text-brand-blue",
            bg: "bg-brand-blue/10",
            btnVariant: "default"
        }
    };

    const config = typeConfigs[type];

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title={title}
            size="sm"
            isLocal={isLocal}
            footer={
                <>
                    <Button variant="ghost" onClick={onClose} disabled={isLoading}>
                        {cancelText}
                    </Button>
                    <Button
                        variant={config.btnVariant}
                        onClick={onConfirm}
                        loading={isLoading}
                    >
                        {confirmText}
                    </Button>
                </>
            }
        >
            <div className="flex flex-col items-center text-center py-4">
                <div className={`p-4 rounded-full ${config.bg} ${config.color} mb-4`}>
                    <Icon name={config.icon} size={32} />
                </div>
                <p className="text-muted-foreground">{message}</p>
            </div>
        </Modal>
    );
};

export default ConfirmationModal;
