import { useState, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../services/supabaseService';
import { updateFaviconBadge } from '../utils/faviconUtils';

/**
 * useFaviconBadge - Global hook to manage the browser tab notification badge.
 * Consolidates Chat, Banners, and Admin Pending Tasks.
 */
export const useFaviconBadge = () => {
    const { user, role } = useSelector(state => state.auth);
    const [unreadChatCount, setUnreadChatCount] = useState(0);
    const [activeBannerCount, setActiveBannerCount] = useState(0);
    const [adminTaskCount, setAdminTaskCount] = useState(0);
    const chatUnreadsRef = useRef({});

    // 1. Monitor Chat Unread Counts
    useEffect(() => {
        if (!user) {
            // Reset all counts on logout
            chatUnreadsRef.current = {};
            setUnreadChatCount(0);
            setActiveBannerCount(0);
            setAdminTaskCount(0);
            updateFaviconBadge(0);
            return;
        }

        const syncInitialChatUnreads = async () => {
            try {
                const channels = await supabaseService.getChatChannels();
                const unreadMap = {};
                channels.forEach(channel => {
                    const myMemberData = channel.members?.find(m => m.user?.id === user.id);
                    if (!myMemberData || !channel.last_message_at) return;
                    if (new Date(channel.last_message_at) > new Date(myMemberData.last_read_at || 0)) {
                        unreadMap[channel.id] = 1;
                    }
                });
                chatUnreadsRef.current = unreadMap;
                setUnreadChatCount(Object.keys(unreadMap).length);
            } catch (err) {
                console.error("Chat unread sync failed", err);
            }
        };

        syncInitialChatUnreads();

        const messageSub = supabaseService.subscribeToAllMessages((payload) => {
            const msg = payload.new;
            if (msg.sender_id !== user.id && msg.channel_id) {
                chatUnreadsRef.current[msg.channel_id] = (chatUnreadsRef.current[msg.channel_id] || 0) + 1;
                setUnreadChatCount(Object.keys(chatUnreadsRef.current).length);
            }
        });

        const handleRead = (e) => {
            const channelId = e?.detail?.channelId;
            if (channelId && chatUnreadsRef.current[channelId]) {
                delete chatUnreadsRef.current[channelId];
                setUnreadChatCount(Object.keys(chatUnreadsRef.current).length);
            }
        };
        window.addEventListener('chat-marked-read', handleRead);

        return () => {
            if (messageSub) messageSub.unsubscribe();
            window.removeEventListener('chat-marked-read', handleRead);
        };
    }, [user]);

    // 2. Monitor Active Banners & Admin Tasks
    useEffect(() => {
        const fetchPlatformAlerts = async () => {
            try {
                const weekAgo = new Date();
                weekAgo.setDate(weekAgo.getDate() - 7);
                const { data: broadcasts } = await supabaseService.supabase
                    .from('instructor_announcements')
                    .select('id')
                    .gte('created_at', weekAgo.toISOString());
                
                const dismissedId = localStorage.getItem('luc_dismissed_broadcast');
                const activeBanners = broadcasts?.filter(b => b.id.toString() !== dismissedId) || [];
                setActiveBannerCount(activeBanners.length);

                if (role === 'admin' || role === 'founder') {
                    const { data: pendingDrafts } = await supabaseService.supabase
                        .from('course_drafts')
                        .select('id')
                        .eq('status', 'pending_review');
                    setAdminTaskCount(pendingDrafts?.length || 0);
                }
            } catch (err) {
                console.error("Alert fetch failed", err);
            }
        };

        fetchPlatformAlerts();

        const adminSub = supabaseService.supabase.channel('admin_tasks')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'course_drafts' }, () => {
                fetchPlatformAlerts();
            })
            .on('broadcast', { event: 'NEW_BROADCAST' }, () => {
                fetchPlatformAlerts();
            })
            .subscribe();

        return () => {
            adminSub.unsubscribe();
        };
    }, [role]);

    // 3. Global Render Trigger
    useEffect(() => {
        const total = unreadChatCount + activeBannerCount + adminTaskCount;
        updateFaviconBadge(total);
    }, [unreadChatCount, activeBannerCount, adminTaskCount]);

    return { total: unreadChatCount + activeBannerCount + adminTaskCount };
};
