import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Icon from '../AppIcon';
import { supabaseService } from '../../services/supabaseService';
import { cn } from '../../utils/cn';
import { useSelector } from 'react-redux';
import AuthRequiredModal from '../ui/AuthRequiredModal';

const LiveSessionBanner = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const { isAuthenticated, user } = useSelector(state => state.auth);
    const [activeAlert, setActiveAlert] = useState(null);
    const [allSessions, setAllSessions] = useState([]);
    const [isDismissed, setIsDismissed] = useState(false);
    const [lastAlertId, setLastAlertId] = useState(null);
    const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
    // Track which attendance sessions this user has already marked
    const [markedSessionIds, setMarkedSessionIds] = useState(new Set());
    const [eligibleCourseworkIds, setEligibleCourseworkIds] = useState(new Set());
    const [submittedCourseworkIds, setSubmittedCourseworkIds] = useState(new Set());

    const checkMarked = async (sessions) => {
        if (!user?.id || !sessions?.length) return;
        const attendanceSessions = sessions.filter(s =>
            s.title?.startsWith('Attendance:') && s.status === 'live' && new Date(s.end_time) > new Date()
        );
        if (attendanceSessions.length) {
            try {
                const checks = await Promise.all(
                    attendanceSessions.map(s => supabaseService.hasMadeCourseAttendance({ userId: user.id, sessionId: s.id }))
                );
                const marked = new Set(attendanceSessions.filter((_, i) => checks[i]).map(s => s.id));
                setMarkedSessionIds(marked);
            } catch (err) {
                console.error('Failed to check marked sessions', err);
            }
        }

        const courseworkSessions = sessions.filter(s =>
            (s.title?.startsWith('Assignment:') || s.title?.startsWith('Assessment:')) &&
            s.status === 'live' &&
            new Date(s.end_time) > new Date()
        );
        if (courseworkSessions.length) {
            try {
                const checks = await Promise.all(
                    courseworkSessions.map(s => {
                        let meta = {};
                        try { meta = JSON.parse(s.description || '{}'); } catch (_) {}
                        return supabaseService.hasSubmittedCourseWork({ userId: user.id, sessionId: s.id, workType: meta._type || 'assignment' });
                    })
                );
                const submitted = new Set(courseworkSessions.filter((_, i) => checks[i]).map(s => s.id));
                setSubmittedCourseworkIds(submitted);
            } catch (err) {
                console.error('Failed to check submitted coursework', err);
            }
        }
    };

    useEffect(() => {
        fetchAlerts();
        
        // 1. Listen for Database Changes (Postgres)
        const dbSubscription = supabaseService.supabase
            .channel('live_db_changes')
            .on(
                'postgres_changes', 
                { event: '*', schema: 'public', table: 'live_sessions' }, 
                () => {
                    console.log("DB Change detected, refreshing alerts...");
                    fetchAlerts();
                }
            )
            .subscribe();

        // 2. Listen for Instant Broadcasts (Faster than DB sync)
        const broadcastSubscription = supabaseService.supabase
            .channel('platform_notifications')
            .on(
                'broadcast', 
                { event: 'NEW_LIVE_SESSION' }, 
                () => {
                    console.log("Broadcast received! New live session starting...");
                    fetchAlerts();
                }
            )
            .subscribe();

        // 3. When attendance is marked, refresh marked state
        const attendanceBroadcast = supabaseService.supabase
            .channel('banner_attendance_check')
            .on('broadcast', { event: 'ATTENDANCE_OPENED' }, () => fetchAlerts())
            .on('broadcast', { event: 'ATTENDANCE_CLOSED' }, () => fetchAlerts())
            .subscribe();

        // 4. Listen for coursework opened/closed broadcasts
        const courseworkBroadcast = supabaseService.supabase
            .channel('banner_coursework_check')
            .on('broadcast', { event: 'COURSEWORK_OPENED' }, () => fetchAlerts())
            .on('broadcast', { event: 'COURSEWORK_CLOSED' }, () => fetchAlerts())
            .subscribe();

        // 5. Watch lesson_progress so banner hides instantly when this user marks present or submits coursework
        const progressSubscription = supabaseService.supabase
            .channel('banner_lesson_progress')
            .on(
                'postgres_changes',
                { event: 'INSERT', schema: 'public', table: 'lesson_progress' },
                (payload) => {
                    // Re-fetch to update marked/submitted state
                    fetchAlerts();
                }
            )
            .subscribe();

        return () => {
            dbSubscription.unsubscribe();
            broadcastSubscription.unsubscribe();
            attendanceBroadcast.unsubscribe();
            courseworkBroadcast.unsubscribe();
            progressSubscription.unsubscribe();
        };
    }, []);

    const fetchAlerts = async () => {
        try {
            const sessions = await supabaseService.getActiveLiveSessions();
            setAllSessions(sessions);
            updateCurrentAlert(sessions);
            // Also refresh which sessions are already marked
            await checkMarked(sessions);
        } catch (err) {
            console.error("Failed to fetch live alerts", err);
        }
    };

    // Every minute, check if a session is now "5 minutes away"
    useEffect(() => {
        const interval = setInterval(() => {
            updateCurrentAlert(allSessions);
        }, 60000);
        return () => clearInterval(interval);
    }, [allSessions, user?.id]);

    // Re-check marked status when user changes (login/logout)
    useEffect(() => {
        if (allSessions.length) checkMarked(allSessions);
    }, [user?.id]);

    const updateCurrentAlert = (sessions) => {
        if (!sessions || sessions.length === 0) {
            setActiveAlert(null);
            setLastAlertId(null);
            setIsDismissed(false);
            return;
        }

        const now = new Date();
        
        // Separate registers from video sessions
        const attendanceSessions = sessions.filter(s => 
            s.title?.startsWith('Attendance:') && 
            s.status === 'live' && 
            new Date(s.end_time) > now
        );
        const courseworkSessions = sessions.filter(s =>
            (s.title?.startsWith('Assignment:') || s.title?.startsWith('Assessment:')) &&
            s.status === 'live' &&
            new Date(s.end_time) > now
        );
        const validSessions = sessions.filter(s =>
            !s.title?.startsWith('Attendance:') &&
            !s.title?.startsWith('Assignment:') &&
            !s.title?.startsWith('Assessment:')
        );

        let newAlert = null;
        const userName = user?.user_metadata?.full_name?.split(' ')[0] || user?.full_name?.split(' ')[0] || 'there';

        // 1. Check for Active Attendance Registers First (High Priority)
        if (attendanceSessions.length > 0) {
            const att = attendanceSessions[0];
            let meta = {};
            try { meta = JSON.parse(att.description || '{}'); } catch (_) {}
            const courseTitle = meta.courseTitle || att.title.replace('Attendance: ', '');



            newAlert = {
                type: 'attendance',
                title: attendanceSessions.length === 1 ? `Attendance Open: ${courseTitle}` : `${attendanceSessions.length} Attendance Registers Open`,
                message: `Mark yourself present before it closes!`,
                id: null,
                uniqueId: attendanceSessions.length === 1 ? att.id : 'multiple-attendance'
            };
        }
        // 2. Assignment & Assessment registers
        else if (courseworkSessions.length > 0) {
            const work = courseworkSessions[0];
            let meta = {};
            try { meta = JSON.parse(work.description || '{}'); } catch (_) {}
            const workType = meta._type || (work.title?.startsWith('Assessment:') ? 'assessment' : 'assignment');
            const workTitle = meta.workTitle || work.title.replace(/^(Assignment|Assessment): /, '');

            newAlert = {
                type: workType === 'assessment' ? 'assessment' : 'assignment',
                title: courseworkSessions.length === 1
                    ? `${workType === 'assessment' ? 'Assessment' : 'Assignment'} Due: ${workTitle}`
                    : `${courseworkSessions.length} Assignments/Assessments Due`,
                message: 'Submit on your Student Dashboard. Check private chat for details.',
                id: null,
                uniqueId: courseworkSessions.length === 1 ? work.id : 'multiple-coursework'
            };
        }
        
        // 3. Check for Live Sessions (Public or Personal)
        else {
            const liveSessions = validSessions.filter(s => s.status === 'live');
            
            if (liveSessions.length > 0) {
                const myLive = liveSessions.find(s => s.host_id === user?.id || (s.metadata?.invited_member_ids || []).includes(user?.id));
                
                if (myLive) {
                    const isHost = myLive.host_id === user?.id;
                    newAlert = {
                        type: 'live',
                        title: isHost ? `Your room "${myLive.title}" is LIVE!` : `You've been tagged in "${myLive.title}"!`,
                        message: isHost ? `Hey ${userName}, jump in and start the conversation.` : `Ready to collaborate with ${myLive.host?.full_name}?`,
                        id: myLive.meeting_id,
                        uniqueId: myLive.id
                    };
                } else {
                    newAlert = {
                        type: 'live',
                        title: liveSessions.length === 1 ? `Live Now: ${liveSessions[0].title}` : `${liveSessions.length} Brainstorm Rooms Active`,
                        message: liveSessions.length === 1 ? `Hosted by ${liveSessions[0].host?.full_name}` : `Join the community hub`,
                        id: liveSessions.length === 1 ? liveSessions[0].meeting_id : null,
                        uniqueId: liveSessions.length === 1 ? liveSessions[0].id : 'multiple-live'
                    };
                }
            } else {

            // 2. Check for Sessions Starting in <= 5 minutes
            const upcomingSessions = validSessions.filter(s => {
                if (s.status !== 'waiting') return false;
                const startTime = new Date(s.start_time);
                const diffInMins = (startTime - now) / (1000 * 60);
                return diffInMins > 0 && diffInMins <= 5;
            });

            if (upcomingSessions.length > 0) {
                const mySoon = upcomingSessions.find(s => s.host_id === user?.id || (s.metadata?.invited_member_ids || []).includes(user?.id));
                
                if (mySoon) {
                    newAlert = {
                        type: 'soon',
                        title: `Get ready, ${userName}!`,
                        message: `"${mySoon.title}" kicks off in a few minutes.`,
                        id: null,
                        uniqueId: mySoon.id
                    };
                } else {
                    newAlert = {
                        type: 'soon',
                        title: upcomingSessions.length === 1 ? `Starting Soon: ${upcomingSessions[0].title}` : `${upcomingSessions.length} Sessions Starting Soon`,
                        message: upcomingSessions.length === 1 ? `Hosted by ${upcomingSessions[0].host?.full_name}` : `View the upcoming schedule`,
                        id: null,
                        uniqueId: upcomingSessions.length === 1 ? upcomingSessions[0].id : 'multiple-soon'
                    };
                }
            } else if (user?.id) {
                // 3. Check for Pending Sessions (Personalized for Host/Partners)
                const pendingSessions = validSessions.filter(s => {
                    if (s.status !== 'pending') return false;
                    const isHost = s.host_id === user.id;
                    const invitedIds = s.metadata?.invited_member_ids || [];
                    const isInvited = invitedIds.includes(user.id);
                    return isHost || isInvited;
                });

                if (pendingSessions.length > 0) {
                    const myPending = pendingSessions[0];
                    const isHost = myPending.host_id === user.id;
                    newAlert = {
                        type: 'pending',
                        title: isHost ? `Reviewing your room, ${userName}...` : `Tagged in a new brainstorm!`,
                        message: isHost ? `We're checking "${myPending.title}" for approval.` : `Wait for "${myPending.title}" to go live.`,
                        id: null,
                        uniqueId: myPending.id
                    };
                }
            }
        }
        } // Close outer else block

        if (newAlert) {
            if (newAlert.uniqueId !== lastAlertId) {
                setIsDismissed(false);
                setLastAlertId(newAlert.uniqueId);
            }
            setActiveAlert(newAlert);
        } else {
            setActiveAlert(null);
            setLastAlertId(null);
            setIsDismissed(false);
        }
    };

    if (!activeAlert || isDismissed) return null;

    // For attendance banners: hide if the user has already marked present for all open registers
    if (activeAlert.type === 'attendance') {
        const openAttendanceSessions = allSessions.filter(s =>
            s.title?.startsWith('Attendance:') &&
            s.status === 'live' &&
            new Date(s.end_time) > new Date()
        );
        const allMarked = openAttendanceSessions.length > 0 &&
            openAttendanceSessions.every(s => markedSessionIds.has(s.id));

        if (allMarked || location.pathname === '/student-dashboard') {
            return null;
        }
    }

    // For coursework banners: hide if all are submitted or user is on student dashboard
    if (activeAlert.type === 'assignment' || activeAlert.type === 'assessment') {
        const openCourseworkSessions = allSessions.filter(s =>
            (s.title?.startsWith('Assignment:') || s.title?.startsWith('Assessment:')) &&
            s.status === 'live' &&
            new Date(s.end_time) > new Date()
        );
        const allSubmitted = openCourseworkSessions.length > 0 &&
            openCourseworkSessions.every(s => submittedCourseworkIds.has(s.id));

        if (allSubmitted || location.pathname === '/student-dashboard') {
            return null;
        }
    }

    return (
        <AnimatePresence>
            <motion.div 
                key={activeAlert.uniqueId}
                initial={{ y: -100, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: -100, opacity: 0 }}
                className={cn(
                    "relative w-full z-[100] px-4 py-2 flex items-center justify-center transition-all pointer-events-auto",
                    activeAlert.type === 'attendance' ? "bg-emerald-600 shadow-[0_4px_20px_rgba(5,150,105,0.4)]" :
                    activeAlert.type === 'live' ? "bg-red-600 shadow-[0_4px_20px_rgba(220,38,38,0.4)]" : 
                    activeAlert.type === 'pending' ? "bg-indigo-600 shadow-[0_4px_20px_rgba(79,70,229,0.4)]" :
                    activeAlert.type === 'assignment' ? "bg-blue-600 shadow-[0_4px_20px_rgba(59,130,246,0.4)]" :
                    activeAlert.type === 'assessment' ? "bg-purple-600 shadow-[0_4px_20px_rgba(147,51,234,0.4)]" :
                    "bg-amber-500 shadow-[0_4px_20px_rgba(245,158,11,0.4)]"
                )}
            >
                <div className="max-w-7xl w-full flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="relative">
                            <Icon 
                                name={activeAlert.type === 'attendance' ? "ClipboardCheck" : activeAlert.type === 'live' ? "Radio" : activeAlert.type === 'pending' ? "Shield" : activeAlert.type === 'assignment' ? "FileText" : activeAlert.type === 'assessment' ? "FileQuestion" : "Clock"} 
                                className={cn("text-white shrink-0", (activeAlert.type === 'live' || activeAlert.type === 'pending' || activeAlert.type === 'attendance' || activeAlert.type === 'assignment' || activeAlert.type === 'assessment') && "animate-pulse")} 
                                size={18} 
                            />
                            {(activeAlert.type === 'live' || activeAlert.type === 'pending' || activeAlert.type === 'attendance' || activeAlert.type === 'assignment' || activeAlert.type === 'assessment') && (
                                <span className="absolute -top-1 -right-1 w-2 h-2 bg-white rounded-full animate-ping" />
                            )}
                        </div>
                        <div className="min-w-0">
                            <p className="text-white text-[11px] font-black uppercase tracking-[0.1em] leading-none mb-1">
                                {activeAlert.type === 'attendance' ? "Attendance Open" : activeAlert.type === 'live' ? "Happening Now" : activeAlert.type === 'pending' ? "Status: Pending" : activeAlert.type === 'assignment' ? "Assignment Due" : activeAlert.type === 'assessment' ? "Assessment Due" : "Starting Soon"}
                            </p>
                            <h4 className="text-white text-xs font-bold truncate italic tracking-tight">
                                {activeAlert.title} <span className="opacity-70 font-medium not-italic">{activeAlert.message}</span>
                            </h4>
                        </div>
                    </div>

                    <div className="flex items-center gap-2 shrink-0">
                        <button 
                            onClick={() => {
                                if (!isAuthenticated) {
                                    setIsAuthModalOpen(true);
                                    return;
                                }

                                    if (activeAlert.type === 'attendance') {
                                        const attendanceSessions = allSessions.filter(s => 
                                            s.title?.startsWith('Attendance:') && 
                                            s.status === 'live' && 
                                            new Date(s.end_time) > new Date()
                                        ).map(s => {
                                            let meta = {};
                                            try { meta = JSON.parse(s.description || '{}'); } catch (_) {}
                                            return { ...s, course_id: meta.courseId || '', _meta: meta };
                                        });
                                        navigate('/student-dashboard', {
                                            state: { initialAttendances: attendanceSessions }
                                        });
                                    } else if (activeAlert.type === 'live' && activeAlert.id) {
                                        navigate(`/academy/live/${activeAlert.id}`);
                                    } else if (activeAlert.type === 'assignment' || activeAlert.type === 'assessment') {
                                        navigate('/student-dashboard');
                                    } else {
                                        navigate('/academy/brainstorm');
                                    }
                            }}
                            className="bg-white text-[10px] font-black px-4 py-1.5 rounded-full text-black hover:scale-105 active:scale-95 transition-all"
                        >
                            {activeAlert.type === 'attendance' ? "MARK PRESENT" : activeAlert.type === 'live' && activeAlert.id ? "JOIN NOW" : activeAlert.type === 'assignment' ? 'SUBMIT ASSIGNMENT' : activeAlert.type === 'assessment' ? 'TAKE ASSESSMENT' : 'VIEW HUB'}
                        </button>
                        
                        <button 
                            onClick={() => setIsDismissed(true)}
                            className="p-1.5 text-white/60 hover:text-white hover:bg-white/10 rounded-full transition-all"
                            title="Dismiss alert"
                        >
                            <Icon name="X" size={14} />
                        </button>
                    </div>
                </div>
            </motion.div>

            <AuthRequiredModal 
                key="auth-modal"
                isOpen={isAuthModalOpen} 
                onClose={() => setIsAuthModalOpen(false)} 
                context="live"
                redirectTo={activeAlert.type === 'live' && activeAlert.id ? `/academy/live/${activeAlert.id}` : activeAlert.type === 'assignment' || activeAlert.type === 'assessment' ? '/student-dashboard' : '/academy/brainstorm'}
            />
        </AnimatePresence>
    );
};

export default LiveSessionBanner;
