import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { supabaseService } from '../services/supabaseService';
import { normalizeId } from '../utils/idUtils';

// Initial state loads from localStorage to persist user progress across reloads
const loadState = () => {
    try {
        const history = localStorage.getItem('luc_watch_history');
        const bookmarks = localStorage.getItem('luc_bookmarks');
        const progress = localStorage.getItem('luc_course_progress');
        const notes = localStorage.getItem('luc_course_notes');

        return {
            watchHistory: history ? JSON.parse(history) : [],
            bookmarks: bookmarks ? JSON.parse(bookmarks) : [],
            // Structure: { [courseId]: { completedLessons: [], lastAccessed: date, percentage: 0 } }
            courseProgress: progress ? JSON.parse(progress) : {},
            // Structure: { [courseId]: [ { id, lessonId, timestamp, content, date } ] }
            notes: notes ? JSON.parse(notes) : {},
            // track assessment scores { [lessonId]: score }
            assessmentScores: {},
            loading: false,
            error: null
        };
    } catch (e) {
        return {
            watchHistory: [],
            bookmarks: [],
            courseProgress: {},
            notes: {},
            assessmentScores: {},
            loading: false,
            error: null
        };
    }
};

// --- Async Thunks ---

export const syncUserActivity = createAsyncThunk(
    'activity/sync',
    async (userId, { rejectWithValue }) => {
        try {
            const [notes, granularProgress, enrollmentData] = await Promise.all([
                supabaseService.getUserNotes(userId),
                supabaseService.getGranularProgress(userId),
                supabaseService.getStudentDetails(userId) // This contains the enrollments with the stored percentages
            ]);

            const { enrollments } = enrollmentData;

            // Transform granular progress into the structured courseProgress
            const courseProgress = granularProgress.reduce((acc, item) => {
                const cId = normalizeId(item.course_id);
                if (!acc[cId]) {
                    acc[cId] = {
                        completedLessons: [],
                        lessonDetails: {}, // Stores individual lesson timestamps/assessment
                        lastAccessed: item.last_accessed_at,
                        startedAt: item.created_at,
                        percentage: 0
                    };
                }

                const lessonIdStr = normalizeId(item.lesson_id);
                if (item.completed && !acc[cId].completedLessons.includes(lessonIdStr)) {
                    acc[cId].completedLessons.push(lessonIdStr);
                }

                // Store more granular data per lesson
                acc[cId].lessonDetails[lessonIdStr] = {
                    timestamp: item.last_timestamp,
                    completed: item.completed,
                    assessmentData: item.assessment_data
                };

                // Update course-level timestamp if this one is newer
                if (new Date(item.last_accessed_at) > new Date(acc[cId].lastAccessed)) {
                    acc[cId].lastAccessed = item.last_accessed_at;
                }

                return acc;
            }, {});

            // Post-process: Overlay the stored enrollment percentages as the source of truth for UI progress
            enrollments.forEach(enrollment => {
                const cId = normalizeId(enrollment.item_id);
                if (courseProgress[cId]) {
                    courseProgress[cId].percentage = enrollment.progress || 0;
                    courseProgress[cId].status = enrollment.status;
                } else {
                    // Even if no granular progress exists yet, the enrollment record should be represented
                    courseProgress[cId] = {
                        completedLessons: [],
                        lessonDetails: {},
                        lastAccessed: enrollment.updated_at,
                        startedAt: enrollment.created_at,
                        percentage: enrollment.progress || 0,
                        status: enrollment.status
                    };
                }
            });

            // Fallback for courses with granular progress but no explicit enrollment record found (unlikely but safe)
            Object.keys(courseProgress).forEach(cId => {
                const data = courseProgress[cId];
                if (data.percentage === undefined || data.percentage === null) {
                    data.percentage = data.completedLessons.length > 0 ? 5 : 0;
                }
            });

            // Transform flat notes into the grouped structure { [courseId]: [] }
            const groupedNotes = notes.reduce((acc, note) => {
                const cId = note.course_id;
                if (!acc[cId]) acc[cId] = [];
                acc[cId].push({
                    id: note.id,
                    lessonId: note.lesson_id,
                    timestamp: note.timestamp,
                    content: note.content,
                    date: note.created_at
                });
                return acc;
            }, {});

            // Update localStorage for consistent experience
            localStorage.setItem('luc_course_notes', JSON.stringify(groupedNotes));
            localStorage.setItem('luc_course_progress', JSON.stringify(courseProgress));

            return { notes: groupedNotes, courseProgress };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

export const saveLessonProgressAsync = createAsyncThunk(
    'activity/saveProgress',
    async ({ courseId, lessonId, timestamp, completed, assessmentData }, { getState, rejectWithValue }) => {
        const userId = getState().auth.user?.id;
        try {
            if (userId) {
                await supabaseService.saveLessonProgress({
                    userId,
                    courseId,
                    lessonId,
                    timestamp,
                    completed,
                    assessmentData
                });
            }
            return { courseId, lessonId, timestamp, completed, assessmentData };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

export const addNoteAsync = createAsyncThunk(
    'activity/addNote',
    async ({ courseId, lessonId, timestamp, content }, { getState, rejectWithValue }) => {
        const userId = getState().auth.user?.id;
        try {
            if (userId) {
                const note = await supabaseService.addNote({ userId, courseId, lessonId, timestamp, content });
                return {
                    courseId,
                    note: {
                        id: note.id,
                        lessonId: note.lesson_id,
                        timestamp: note.timestamp,
                        content: note.content,
                        date: note.created_at
                    }
                };
            }
            // If guest, return just local data format
            return {
                courseId,
                note: {
                    id: Date.now().toString(),
                    lessonId,
                    timestamp,
                    content,
                    date: new Date().toISOString()
                }
            };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

export const updateNoteAsync = createAsyncThunk(
    'activity/updateNote',
    async ({ courseId, noteId, content }, { getState, rejectWithValue }) => {
        const userId = getState().auth.user?.id;
        try {
            if (userId && !noteId.includes('-')) { // Real UUIDs don't look like Date.now()
                await supabaseService.updateNote(noteId, userId, content);
            }
            return { courseId, noteId, content };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

export const updateEnrollmentProgressAsync = createAsyncThunk(
    'activity/updateEnrollmentProgress',
    async ({ courseId, progress, status, type }, { getState, rejectWithValue }) => {
        const userId = getState().auth.user?.id;
        try {
            if (userId) {
                await supabaseService.updateStudentProgress(userId, courseId, progress, status, type);
            }
            return { courseId, progress, status, type };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

export const deleteNoteAsync = createAsyncThunk(
    'activity/deleteNote',
    async ({ courseId, noteId }, { getState, rejectWithValue }) => {
        const userId = getState().auth.user?.id;
        try {
            if (userId && !noteId.includes('-') && noteId.length > 15) { // Simple check for UUID vs Date.now string
                await supabaseService.deleteNote(noteId, userId);
            }
            return { courseId, noteId };
        } catch (err) {
            return rejectWithValue(err.message);
        }
    }
);

const activitySlice = createSlice({
    name: 'activity',
    initialState: loadState(),
    reducers: {
        addToHistory: (state, action) => {
            const newEntry = { ...action.payload, watchedAt: new Date().toISOString() };
            state.watchHistory = [
                newEntry,
                ...state.watchHistory.filter(item => item.id !== action.payload.id)
            ].slice(0, 20);
            localStorage.setItem('luc_watch_history', JSON.stringify(state.watchHistory));
        },
        removeFromHistory: (state, action) => {
            const courseId = action.payload;
            state.watchHistory = state.watchHistory.filter(item => item.id !== courseId);
            localStorage.setItem('luc_watch_history', JSON.stringify(state.watchHistory));
        },
        toggleBookmark: (state, action) => {
            const exists = state.bookmarks.find(item => item.id === action.payload.id);
            if (exists) {
                state.bookmarks = state.bookmarks.filter(item => item.id !== action.payload.id);
            } else {
                state.bookmarks = [action.payload, ...state.bookmarks];
            }
            localStorage.setItem('luc_bookmarks', JSON.stringify(state.bookmarks));
        },
        updateCourseProgress: (state, action) => {
            const { courseId, lessonId, totalLessons } = action.payload;
            const cId = normalizeId(courseId);
            const lId = normalizeId(lessonId);

            if (!state.courseProgress[cId]) {
                state.courseProgress[cId] = {
                    completedLessons: [],
                    lessonDetails: {},
                    startedAt: new Date().toISOString()
                };
            }
            const courseData = state.courseProgress[cId];
            if (!courseData.completedLessons.includes(lId)) {
                courseData.completedLessons.push(lId);
            }

            if (!courseData.lessonDetails) courseData.lessonDetails = {};
            if (!courseData.lessonDetails[lId]) {
                courseData.lessonDetails[lId] = { completed: true };
            } else {
                courseData.lessonDetails[lId].completed = true;
            }

            courseData.lastAccessed = new Date().toISOString();
            courseData.percentage = Math.round((courseData.completedLessons.length / (totalLessons || 1)) * 100);
            localStorage.setItem('luc_course_progress', JSON.stringify(state.courseProgress));
        },
        saveAssessmentScore: (state, action) => {
            const { lessonId, score, passed } = action.payload;
            state.assessmentScores[lessonId] = { score, passed, date: new Date().toISOString() };
        },
        startCourse: (state, action) => {
            const { courseId } = action.payload;
            if (!state.courseProgress[courseId]) {
                state.courseProgress[courseId] = {
                    completedLessons: [],
                    lessonDetails: {},
                    startedAt: new Date().toISOString(),
                    lastAccessed: new Date().toISOString(),
                    percentage: 0
                };
                localStorage.setItem('luc_course_progress', JSON.stringify(state.courseProgress));
            }
        },
        // Standard reducers for optimistic updates if needed
        addNote: (state, action) => {
            const { courseId, lessonId, timestamp, content } = action.payload;
            if (!state.notes[courseId]) state.notes[courseId] = [];
            state.notes[courseId].unshift({
                id: Date.now().toString(),
                lessonId,
                timestamp,
                content,
                date: new Date().toISOString()
            });
            localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
        },
        deleteNote: (state, action) => {
            const { courseId, noteId } = action.payload;
            if (state.notes[courseId]) {
                state.notes[courseId] = state.notes[courseId].filter(n => n.id !== noteId);
                localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
            }
        },
        updateNote: (state, action) => {
            const { courseId, noteId, content } = action.payload;
            if (state.notes[courseId]) {
                const note = state.notes[courseId].find(n => n.id === noteId);
                if (note) {
                    note.content = content;
                    note.date = new Date().toISOString();
                    localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
                }
            }
        },
        clearActivity: (state) => {
            state.watchHistory = [];
            state.bookmarks = [];
            state.courseProgress = {};
            state.notes = {};
            state.assessmentScores = {};
            localStorage.removeItem('luc_watch_history');
            localStorage.removeItem('luc_bookmarks');
            localStorage.removeItem('luc_course_progress');
            localStorage.removeItem('luc_course_notes');
        }
    },
    extraReducers: (builder) => {
        builder
            .addCase(syncUserActivity.fulfilled, (state, action) => {
                state.notes = action.payload.notes;
                state.courseProgress = action.payload.courseProgress;
                state.loading = false;
            })
            .addCase(saveLessonProgressAsync.fulfilled, (state, action) => {
                const { courseId, lessonId, timestamp, completed, assessmentData } = action.payload;
                if (!state.courseProgress[courseId]) {
                    state.courseProgress[courseId] = {
                        completedLessons: [],
                        lessonDetails: {},
                        lastAccessed: new Date().toISOString()
                    };
                }
                const courseData = state.courseProgress[courseId];
                if (!courseData.lessonDetails) courseData.lessonDetails = {};

                courseData.lessonDetails[lessonId] = {
                    timestamp,
                    completed,
                    assessmentData
                };

                if (completed && !courseData.completedLessons.includes(lessonId)) {
                    courseData.completedLessons.push(lessonId);
                }

                courseData.lastAccessed = new Date().toISOString();
                localStorage.setItem('luc_course_progress', JSON.stringify(state.courseProgress));
            })
            .addCase(addNoteAsync.fulfilled, (state, action) => {
                const { courseId, note } = action.payload;
                if (!state.notes[courseId]) state.notes[courseId] = [];
                // Remove the optimistic one if it exists (by checking content and timestamp roughly, or just replace)
                // Actually, let's just push it properly.
                state.notes[courseId] = [note, ...state.notes[courseId].filter(n => n.id !== note.id && n.content !== note.content)];
                localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
            })
            .addCase(updateNoteAsync.fulfilled, (state, action) => {
                const { courseId, noteId, content } = action.payload;
                if (state.notes[courseId]) {
                    const note = state.notes[courseId].find(n => n.id === noteId);
                    if (note) {
                        note.content = content;
                        note.date = new Date().toISOString();
                        localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
                    }
                }
            })
            .addCase(updateEnrollmentProgressAsync.fulfilled, (state, action) => {
                const { courseId, progress, status } = action.payload;
                const cId = normalizeId(courseId);
                if (!state.courseProgress[cId]) {
                    state.courseProgress[cId] = {
                        completedLessons: [],
                        lessonDetails: {},
                        lastAccessed: new Date().toISOString()
                    };
                }
                state.courseProgress[cId].percentage = progress;
                state.courseProgress[cId].status = status;
                state.courseProgress[cId].lastAccessed = new Date().toISOString();
                localStorage.setItem('luc_course_progress', JSON.stringify(state.courseProgress));
            })
            .addCase(deleteNoteAsync.fulfilled, (state, action) => {
                const { courseId, noteId } = action.payload;
                if (state.notes[courseId]) {
                    state.notes[courseId] = state.notes[courseId].filter(n => n.id !== noteId);
                    localStorage.setItem('luc_course_notes', JSON.stringify(state.notes));
                }
            });
    }
});

export const {
    addToHistory,
    removeFromHistory,
    toggleBookmark,
    updateCourseProgress,
    saveAssessmentScore,
    startCourse,
    addNote, // Sync version
    deleteNote,
    updateNote,
    clearActivity
} = activitySlice.actions;

export default activitySlice.reducer;
