import React, { useState, useEffect } from 'react';
import Icon from '../AppIcon';

const ScrollToTopButton = () => {
    const [isVisible, setIsVisible] = useState(false);

    // Toggle visibility based on scroll position
    useEffect(() => {
        const toggleVisibility = () => {
            if (window.scrollY > 300) {
                setIsVisible(true);
            } else {
                setIsVisible(false);
            }
        };

        window.addEventListener('scroll', toggleVisibility);

        return () => {
            window.removeEventListener('scroll', toggleVisibility);
        };
    }, []);

    // Scroll to top smoothly
    const scrollToTop = () => {
        window.scrollTo({
            top: 0,
            behavior: 'smooth',
        });
    };

    return (
        <>
            {isVisible && (
                <button
                    onClick={scrollToTop}
                    aria-label="Scroll to top"
                    className="fixed z-[30] p-3 rounded-full bg-[var(--color-primary)] text-[var(--color-secondary)] shadow-2xl hover:bg-[var(--color-primary-foreground)]/10 transition-all duration-300 hover:-translate-y-1 focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)] focus:ring-offset-2 animate-in fade-in zoom-in slide-in-from-bottom-4 duration-300"
                    style={{
                        bottom: '6.5rem',
                        right: '2rem',
                        cursor: 'pointer',
                        zIndex: 30
                    }}
                >
                    <Icon name="ArrowUp" size={24} />
                </button>
            )}
        </>
    );
};

export default ScrollToTopButton;
