import React, { useState, useRef, useEffect } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import Icon from '../AppIcon';

const ThemeToggle = () => {
  const { theme, setTheme } = useTheme();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef(null);

  const themeOptions = [
    { value: 'light', label: 'Light', icon: 'Sun' },
    { value: 'dark', label: 'Dark', icon: 'Moon' },
    { value: 'system', label: 'System', icon: 'Monitor' },
  ];

  const currentThemeOption = themeOptions?.find(opt => opt?.value === theme) || themeOptions?.[2];

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef?.current && !dropdownRef?.current?.contains(event?.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleThemeChange = (newTheme) => {
    setTheme(newTheme);
    setIsOpen(false);
  };


  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="relative z-10 flex items-center justify-center w-11 h-11 sm:w-10 sm:h-10 p-0.5 leading-none rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
        aria-label="Toggle theme"
      >
        <Icon name={currentThemeOption?.icon} size={20} className="relative -top-px sm:top-0 text-gray-700 dark:text-gray-300" />
      </button>
      {isOpen && (
        <div className="absolute right-0 top-full mt-2 origin-top-right w-40 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 shadow-xl z-[70]">
          <div className="py-1">
            {themeOptions?.map((option) => (
              <button
                key={option?.value}
                onClick={() => handleThemeChange(option?.value)}
                className={`w-full flex items-center gap-3 px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors ${theme === option?.value
                  ? 'text-cyan-600 dark:text-cyan-400 font-medium' : 'text-gray-700 dark:text-gray-300'
                  }`}
              >
                <Icon name={option?.icon} size={16} className="relative -top-px sm:top-0 transition-all" />
                <span>{option?.label}</span>
                {theme === option?.value && (
                  <Icon name="Check" size={14} className="ml-auto" />
                )}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default ThemeToggle;

