/**
 * Dynamic Favicon Badge Utility (v3 - PNG-based)
 * Renders a notification badge onto the site favicon using HTML5 Canvas.
 * Uses a PNG source instead of ICO for reliable Canvas rendering across browsers.
 */

export const updateFaviconBadge = (count) => {
  count = Number(count) || 0;

  const favicon = document.getElementById('favicon');
  if (!favicon) return;

  // If count is 0, restore original favicon
  if (count === 0) {
    favicon.href = '/luc.ico';
    favicon.type = 'image/x-icon';
    return;
  }

  const canvas = document.createElement('canvas');
  canvas.width = 32;
  canvas.height = 32;
  const ctx = canvas.getContext('2d');

  const img = new Image();
  img.crossOrigin = "anonymous";
  img.src = '/luc-badge.png';

  img.onload = () => {
    try {
      ctx.clearRect(0, 0, 32, 32);
      ctx.drawImage(img, 0, 0, 32, 32);

      // Draw Badge Background (Bottom Right)
      const radius = 10;
      const x = 32 - radius;
      const y = 32 - radius;

      ctx.beginPath();
      ctx.arc(x, y, radius, 0, 2 * Math.PI, false);
      ctx.fillStyle = '#EF4444';
      ctx.fill();

      // Draw Badge Text
      ctx.fillStyle = 'white';
      ctx.font = 'bold 11px Inter, system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      const displayCount = count > 99 ? '99+' : String(count);
      ctx.fillText(displayCount, x, y + 1);

      favicon.href = canvas.toDataURL('image/png');
      favicon.type = 'image/png';
    } catch (err) {
      console.warn("Favicon badge update failed:", err);
    }
  };

  img.onerror = () => {
    // Fallback: draw badge on blank canvas
    try {
      ctx.clearRect(0, 0, 32, 32);
      const radius = 10;
      const x = 32 - radius;
      const y = 32 - radius;
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, 2 * Math.PI, false);
      ctx.fillStyle = '#EF4444';
      ctx.fill();
      ctx.fillStyle = 'white';
      ctx.font = 'bold 11px Inter, system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const displayCount = count > 99 ? '99+' : String(count);
      ctx.fillText(displayCount, x, y + 1);
      favicon.href = canvas.toDataURL('image/png');
      favicon.type = 'image/png';
    } catch (err) {
      console.warn("Favicon badge fallback failed:", err);
    }
  };
};
