import ReactGA from "react-ga4";

/**
 * LUC Analytics Engine (Google Analytics 4)
 * 
 * Tracks scholar behavior, conversion paths, and ecosystem engagement.
 */

export const initGA = (measurementId) => {
    const id = measurementId || import.meta.env.VITE_GA_MEASUREMENT_ID;

    if (id && id !== "G-XXXXXXXXXX") {
        ReactGA.initialize(id);
        console.log(`[LUC ANALYTICS] Global Stream Initialized: ${id}`);
    } else {
        console.warn("[LUC ANALYTICS] Measurement ID missing. Tracking disabled.");
    }
};

/**
 * Tracks a page view event.
 * @param {string} path - The relative URL path
 */
export const trackPageView = (path) => {
    ReactGA.send({ hitType: "pageview", page: path });
};

/**
 * Tracks custom events (e.g., button clicks, mission completions).
 * @param {string} category - High-level category (e.g. 'Academy')
 * @param {string} action - The action performed (e.g. 'Started Course')
 * @param {string} label - Optional descriptor (e.g. 'The Triple Lock')
 * @param {number} value - Optional numeric value
 */
export const trackEvent = (category, action, label = null, value = null) => {
    ReactGA.event({
        category,
        action,
        label,
        value
    });
};

/**
 * Tracks elite scholar behavior (conversions).
 */
export const trackConversion = (type, details = {}) => {
    ReactGA.event("conversion", {
        type,
        ...details
    });
};
