import React, { useState } from 'react';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import Icon from '../../../components/AppIcon';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';

const SubmitOpportunityModal = ({ isOpen, onClose }) => {
    const { addToast } = useToast();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [success, setSuccess] = useState(false);
    const [formData, setFormData] = useState({
        submitter_name: '',
        submitter_email: '',
        title: '',
        organization: '',
        category: '',
        description: '',
        application_link: '',
        deadline: ''
    });

    const categories = [
        { value: 'Scholarship', label: 'Scholarship' },
        { value: 'Internship', label: 'Internship' },
        { value: 'Fellowship', label: 'Fellowship' },
        { value: 'Competition', label: 'Competition' },
        { value: 'Job', label: 'Job/Career' },
        { value: 'Other', label: 'Other Opportunity' }
    ];

    const handleChange = (field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            await supabaseService.submitOpportunity(formData);
            setSuccess(true);
            addToast('Opportunity submitted for review!', 'success');
            setTimeout(() => {
                onClose();
                setSuccess(false);
                setFormData({
                    submitter_name: '',
                    submitter_email: '',
                    title: '',
                    organization: '',
                    category: '',
                    description: '',
                    application_link: '',
                    deadline: ''
                });
            }, 3000);
        } catch (error) {
            console.error('Error submitting opportunity:', error);
            addToast('Failed to submit opportunity. Please try again.', 'error');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Submit an Opportunity"
            size="xl"
        >
            {success ? (
                <div className="text-center py-12">
                    <div className="w-20 h-20 bg-success/10 rounded-full flex items-center justify-center mx-auto mb-6 text-success">
                        <Icon name="CheckCircle" size={48} />
                    </div>
                    <h3 className="text-2xl font-bold text-primary mb-2">Thank You!</h3>
                    <p className="text-muted-foreground">
                        Your submission has been received. Our team will verify the information
                        and list it if it meets our quality standards. Together, we empower more dreams!
                    </p>
                </div>
            ) : (
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="bg-primary/5 p-4 rounded-xl border border-primary/10 mb-6">
                        <p className="text-sm text-primary font-medium flex items-center gap-2">
                            <Icon name="Info" size={16} />
                            Contribute to the community by sharing a life-changing opportunity.
                        </p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Your Name"
                            placeholder="Full Name"
                            required
                            value={formData.submitter_name}
                            onChange={(e) => handleChange('submitter_name', e.target.value)}
                        />
                        <Input
                            label="Your Email"
                            type="email"
                            placeholder="email@example.com"
                            required
                            value={formData.submitter_email}
                            onChange={(e) => handleChange('submitter_email', e.target.value)}
                        />
                    </div>

                    <hr className="border-border" />

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Input
                            label="Opportunity Title"
                            placeholder="e.g. Google Step Internship 2026"
                            required
                            value={formData.title}
                            onChange={(e) => handleChange('title', e.target.value)}
                        />
                        <Input
                            label="Host Organization"
                            placeholder="e.g. Google"
                            required
                            value={formData.organization}
                            onChange={(e) => handleChange('organization', e.target.value)}
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <Select
                            label="Category"
                            placeholder="Select category"
                            required
                            options={categories}
                            value={formData.category}
                            onChange={(val) => handleChange('category', val)}
                        />
                        <Input
                            label="Application Deadline"
                            type="date"
                            required
                            value={formData.deadline}
                            onChange={(e) => handleChange('deadline', e.target.value)}
                        />
                    </div>

                    <Input
                        label="Official Application Link"
                        placeholder="https://..."
                        required
                        type="url"
                        value={formData.application_link}
                        onChange={(e) => handleChange('application_link', e.target.value)}
                    />

                    <div>
                        <label className="block text-sm font-medium text-foreground mb-2">
                            Brief Description / Requirements
                        </label>
                        <textarea
                            required
                            rows={4}
                            placeholder="Summarize what this opportunity is about and what is required to apply..."
                            value={formData.description}
                            onChange={(e) => handleChange('description', e.target.value)}
                            className="w-full px-4 py-3 rounded-lg border border-border bg-background text-foreground focus:ring-2 focus:ring-primary/20 transition-all resize-none"
                        />
                    </div>

                    <div className="flex gap-3 pt-4">
                        <Button variant="ghost" fullWidth onClick={onClose} type="button">
                            Cancel
                        </Button>
                        <Button
                            variant="default"
                            fullWidth
                            type="submit"
                            loading={isSubmitting}
                        >
                            Submit for Review
                        </Button>
                    </div>
                </form>
            )}
        </Modal>
    );
};

export default SubmitOpportunityModal;
