import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useLocation } from 'react-router-dom';
import Icon from '../AppIcon';
import { supabaseService } from '../../services/supabaseService';
import { updateUserDetails } from '../../store/authSlice';

/**
 * SecurityGuard
 * Handles inactivity timeout and persistent screen locking.
 * Includes "On-the-Fly" PIN setup for new users to eliminate default PINs.
 */
const SecurityGuard = ({ children, timeoutMinutes = 30 }) => {
    const { user, isAuthenticated } = useSelector((state) => state.auth);
    const dispatch = useDispatch();
    const location = useLocation();
    
    const [isLocked, setIsLocked] = useState(false);
    const [pin, setPin] = useState('');
    const [confirmPin, setConfirmPin] = useState('');
    const [isSetupMode, setIsSetupMode] = useState(false);
    const [setupStep, setSetupStep] = useState(1); // 1: Enter, 2: Confirm
    const [error, setError] = useState('');
    const [isChecking, setIsChecking] = useState(true);
    const [isShaking, setIsShaking] = useState(false);
    
    const timeoutRef = useRef(null);
    const lastActivityRef = useRef(Date.now());

    // Use Auth Metadata for the session lock PIN
    const userPin = user?.user_metadata?.security_pin || "";

    const lockSystem = useCallback(() => {
        if (!isAuthenticated) return;
        if (['/login', '/signup', '/forgot-password'].includes(location.pathname)) return;

        setIsLocked(true);
        localStorage.setItem('luc_system_locked', 'true');
        
        // If user has no PIN in metadata, force Setup Mode
        if (!user?.user_metadata?.security_pin) {
            setIsSetupMode(true);
            setSetupStep(1);
        }
    }, [isAuthenticated, location.pathname, user?.security_pin]);

    const unlockSystem = useCallback(async () => {
        if (isSetupMode) {
            if (setupStep === 1) {
                // Move to confirmation
                setConfirmPin(pin);
                setPin('');
                setSetupStep(2);
                setError('');
            } else {
                // Finalize Setup
                if (pin === confirmPin) {
                    try {
                        await supabaseService.updateSecurityPin(pin);
                        dispatch(updateUserDetails({ 
                            user_metadata: { ...user?.user_metadata, security_pin: pin } 
                        }));
                        
                        setIsLocked(false);
                        setIsSetupMode(false);
                        setPin('');
                        setConfirmPin('');
                        setError('');
                        localStorage.setItem('luc_system_locked', 'false');
                        lastActivityRef.current = Date.now();
                        resetTimer();
                    } catch (err) {
                        setError('Failed to save PIN. Try again.');
                        setPin('');
                        setSetupStep(1);
                    }
                } else {
                    setError('PINs do not match. Restarting...');
                    setPin('');
                    setConfirmPin('');
                    setSetupStep(1);
                    setIsShaking(true);
                    setTimeout(() => setIsShaking(false), 500);
                }
            }
        } else {
            // Standard Unlock
            if (pin === userPin) {
                setIsLocked(false);
                setPin('');
                setError('');
                localStorage.setItem('luc_system_locked', 'false');
                lastActivityRef.current = Date.now();
                resetTimer();
            } else {
                setError('Invalid Authorization PIN');
                setPin('');
                setIsShaking(true);
                setTimeout(() => setIsShaking(false), 500);
                
                if (window.navigator.vibrate) {
                    window.navigator.vibrate([100, 50, 100]);
                }
            }
        }
    }, [pin, confirmPin, isSetupMode, setupStep, userPin, user?.id, dispatch]);

    const resetTimer = useCallback(() => {
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        if (!isAuthenticated || isLocked) return;

        lastActivityRef.current = Date.now();
        timeoutRef.current = setTimeout(() => {
            lockSystem();
        }, timeoutMinutes * 60 * 1000);
    }, [isAuthenticated, isLocked, timeoutMinutes, lockSystem]);

    useEffect(() => {
        const savedLockStatus = localStorage.getItem('luc_system_locked');
        if (savedLockStatus === 'true' && isAuthenticated) {
            setIsLocked(true);
            if (!user?.security_pin) {
                setIsSetupMode(true);
                setSetupStep(1);
            }
        }
        setIsChecking(false);
    }, [isAuthenticated, user?.security_pin]);

    useEffect(() => {
        const handleActivity = () => {
            if (!isLocked) resetTimer();
        };

        const events = ['mousedown', 'mousemove', 'keypress', 'scroll', 'touchstart'];
        
        if (isAuthenticated && !isLocked) {
            events.forEach(event => window.addEventListener(event, handleActivity));
            resetTimer();
        }

        return () => {
            events.forEach(event => window.removeEventListener(event, handleActivity));
            if (timeoutRef.current) clearTimeout(timeoutRef.current);
        };
    }, [isAuthenticated, isLocked, resetTimer]);

    const handlePinInput = (digit) => {
        if (pin.length < 4) {
            setPin(prev => prev + digit);
            setError('');
        }
    };

    const handleBackspace = () => {
        setPin(prev => prev.slice(0, -1));
    };

    useEffect(() => {
        if (!isLocked) return;
        const handleKeyDown = (e) => {
            if (/^[0-9]$/.test(e.key)) {
                if (pin.length < 4) {
                    setPin(prev => prev + e.key);
                    setError('');
                }
            } else if (e.key === 'Backspace') {
                setPin(prev => prev.slice(0, -1));
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isLocked, pin]);

    useEffect(() => {
        if (pin.length === 4) {
            const timer = setTimeout(() => unlockSystem(), 300);
            return () => clearTimeout(timer);
        }
    }, [pin, unlockSystem]);

    if (isChecking) return null;
    if (!isLocked || !isAuthenticated) return children;

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center overflow-y-auto bg-slate-950/60 backdrop-blur-[20px] py-10 px-4 touch-none">
            {/* Cinematic Background Elements */}
            <div className="fixed inset-0 pointer-events-none overflow-hidden opacity-50">
                <div className="absolute top-1/4 -left-20 w-96 h-96 bg-primary/20 blur-[120px] rounded-full animate-pulse" />
                <div className="absolute bottom-1/4 -right-20 w-96 h-96 bg-secondary/20 blur-[120px] rounded-full animate-pulse delay-700" />
            </div>

            <div className={`relative w-full max-w-[90%] sm:max-w-md my-auto animate-in zoom-in-95 fade-in duration-500 flex justify-center ${isShaking ? 'animate-shake' : ''}`}>
                <div className="bg-white/5 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] sm:rounded-[3rem] p-8 sm:p-12 shadow-2xl flex flex-col items-center w-full">
                    {/* Header */}
                    <div className="mb-6 sm:mb-8 text-center">
                        <div className="w-14 h-14 sm:w-16 sm:h-16 bg-primary/20 rounded-2xl sm:rounded-3xl flex items-center justify-center mx-auto mb-4 border border-primary/30 shadow-2xl shadow-primary/20">
                            <Icon name={isSetupMode ? "ShieldCheck" : "Lock"} size={28} className="text-white animate-pulse sm:w-8 sm:h-8" />
                        </div>
                        
                        {isSetupMode ? (
                            <>
                                <h2 className="text-xl sm:text-2xl font-black text-primary italic tracking-tighter mb-1 uppercase">Secure Your Vault</h2>
                                <p className="text-slate-400 text-[10px] sm:text-xs font-medium leading-relaxed px-4">
                                    {setupStep === 1 
                                        ? "Create a 4-digit security PIN to protect your account during inactivity." 
                                        : "Re-enter your new security PIN to confirm and activate."}
                                </p>
                            </>
                        ) : (
                            <>
                                <h2 className="text-xl sm:text-2xl font-black text-white italic tracking-tighter mb-1">SYSTEM LOCKED</h2>
                                <p className="text-slate-400 text-[10px] sm:text-xs font-medium leading-relaxed px-4">
                                    Due to inactivity, please enter your <br />
                                    <span className="text-primary font-bold">Authorization PIN</span> to resume.
                                </p>
                            </>
                        )}
                    </div>

                    {/* PIN Display */}
                    <div className="flex justify-center gap-3 sm:gap-4 mb-8 sm:mb-10">
                        {[0, 1, 2, 3].map((i) => (
                            <div 
                                key={i} 
                                className={`w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full border-2 transition-all duration-300 ${
                                    pin.length > i 
                                    ? 'bg-primary border-primary scale-125 shadow-[0_0_15px_rgba(var(--color-primary-rgb),0.5)]' 
                                    : 'border-white/20 scale-100'
                                }`}
                            />
                        ))}
                    </div>

                    {/* Keypad */}
                    <div className="grid grid-cols-3 gap-4 sm:gap-6 w-fit mx-auto mb-8 sm:mb-12 justify-items-center">
                        {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((num) => (
                            <button
                                key={num}
                                onClick={() => handlePinInput(num.toString())}
                                className="w-12 h-12 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl bg-white/5 border border-white/10 text-lg sm:text-xl text-white font-black italic flex items-center justify-center hover:bg-white/10 hover:scale-105 active:scale-90 transition-all select-none"
                            >
                                {num}
                            </button>
                        ))}
                        <div className="w-12 h-12 sm:w-14 sm:h-14" /> {/* Empty spacer */}
                        <button
                            onClick={() => handlePinInput("0")}
                            className="w-12 h-12 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl bg-white/5 border border-white/10 text-lg sm:text-xl text-white font-black italic flex items-center justify-center hover:bg-white/10 hover:scale-105 active:scale-90 transition-all select-none"
                        >
                            0
                        </button>
                        <button
                            onClick={handleBackspace}
                            className="w-12 h-12 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl bg-white/5 border border-white/10 text-white flex items-center justify-center hover:bg-destructive/20 hover:text-destructive active:scale-90 transition-all select-none"
                        >
                            <Icon name="Delete" size={18} className="sm:w-5 sm:h-5" />
                        </button>
                    </div>

                    {/* Bottom Actions */}
                    <div className="min-h-[24px] flex flex-col items-center justify-center w-full">
                        {error ? (
                            <p className="text-destructive text-[9px] sm:text-[10px] font-bold uppercase tracking-widest animate-in slide-in-from-bottom-2 text-center px-4">
                                {error}
                            </p>
                        ) : (
                            <button 
                                onClick={() => window.location.href = '/logout'}
                                className="text-[9px] sm:text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 hover:text-white transition-colors text-center"
                            >
                                {isSetupMode ? "Skip & Log Out" : "Sign Out Completely"}
                            </button>
                        )}
                    </div>
                </div>
            </div>

            <style dangerouslySetInnerHTML={{ __html: `
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    25% { transform: translateX(-8px); }
                    75% { transform: translateX(8px); }
                }
                .animate-shake {
                    animation: shake 0.2s ease-in-out 0s 2;
                }
            `}} />
        </div>
    );
};

export default SecurityGuard;
