import { useEffect } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../services/supabaseService';

/**
 * Traffic Sentinel Hook
 * Intelligently tracks daily unique visits and authenticated activity.
 */
export const useTrafficSentinel = () => {
    const { user } = useSelector(state => state.auth);

    useEffect(() => {
        const checkAndPing = async () => {
            const today = new Date().toISOString().split('T')[0];
            const lastPingDate = localStorage.getItem('luc_last_traffic_ping');
            const lastSessionUser = localStorage.getItem('luc_last_auth_state');
            
            const currentAuthState = user ? 'auth' : 'guest';

            // Only ping if:
            // 1. It's a new day
            // 2. OR the auth state has changed (user just logged in)
            if (lastPingDate !== today || lastSessionUser !== currentAuthState) {
                await supabaseService.logTrafficPing(!!user);
                
                // Store state to prevent redundant pings in the same session
                localStorage.setItem('luc_last_traffic_ping', today);
                localStorage.setItem('luc_last_auth_state', currentAuthState);
            }
        };

        checkAndPing();
    }, [user]); // Re-run if user logs in/out to capture the shift from guest to scholar
};
