import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Icon from '../AppIcon';

const CookieConsent = () => {
    const [isVisible, setIsVisible] = useState(false);
    const [isManaging, setIsManaging] = useState(false);
    const [preferences, setPreferences] = useState({
        necessary: true,
        analytics: true,
        marketing: false
    });

    useEffect(() => {
        const consent = localStorage.getItem('cookie-consent');
        const isAuthPage = ['/login', '/signup'].includes(window.location.pathname);
        if (!consent && !isAuthPage) {
            const timer = setTimeout(() => {
                setIsVisible(true);
            }, 1000);
            return () => clearTimeout(timer);
        }
    }, []);

    const handleAcceptAll = () => {
        const consentData = {
            status: 'accepted',
            preferences: { necessary: true, analytics: true, marketing: true },
            timestamp: new Date().toISOString()
        };
        localStorage.setItem('cookie-consent', JSON.stringify(consentData));
        setIsVisible(false);
    };

    const handleSavePreferences = () => {
        const consentData = { status: 'partial', preferences, timestamp: new Date().toISOString() };
        localStorage.setItem('cookie-consent', JSON.stringify(consentData));
        setIsVisible(false);
    };

    const handleDeclineAll = () => {
        const consentData = {
            status: 'declined',
            preferences: { necessary: true, analytics: false, marketing: false },
            timestamp: new Date().toISOString()
        };
        localStorage.setItem('cookie-consent', JSON.stringify(consentData));
        setIsVisible(false);
    };

    const togglePreference = (key) => {
        if (key === 'necessary') return;
        setPreferences(prev => ({ ...prev, [key]: !prev[key] }));
    };

    return (
        <AnimatePresence>
            {isVisible && (
                <motion.div
                    initial={{ y: 100, opacity: 0, x: '-50%' }}
                    animate={{ y: 0, opacity: 1, x: '-50%' }}
                    exit={{ y: 100, opacity: 0, x: '-50%' }}
                    transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                    className="fixed bottom-4 md:bottom-6 left-1/2 z-[100001] w-[calc(100%-1.5rem)] md:w-[calc(100%-4rem)] max-w-6xl"
                >
                    <div className="bg-white/95 dark:bg-[#1B365D]/95 backdrop-blur-2xl border border-gray-200/50 dark:border-white/10 rounded-2xl md:rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.15)] dark:shadow-[0_20px_50px_rgba(0,0,0,0.4)] p-4 md:py-6 md:px-8 lg:py-6 lg:px-10 overflow-hidden relative group">
                        {/* Decorative dynamic backgrounds */}
                        <div className="absolute -top-24 -right-24 w-64 h-64 bg-cyan-500/10 rounded-full blur-3xl pointer-events-none" />
                        <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-white/5 rounded-full blur-3xl pointer-events-none" />

                        {!isManaging ? (
                            <div className="relative z-10">
                                <div className="flex flex-col lg:flex-row lg:items-center gap-4 lg:gap-8">
                                    {/* Icon & Message Section */}
                                    <div className="flex items-start md:items-center gap-3 md:gap-4 flex-1">
                                        <div className="flex-shrink-0 w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl bg-gradient-to-br from-cyan-400 to-blue-500 flex items-center justify-center text-white shadow-xl shadow-cyan-500/20">
                                            <Icon name="Cookie" size={20} className="md:size-7" />
                                        </div>
                                        <div className="flex-1">
                                            <h3 className="text-base md:text-xl font-bold text-gray-900 dark:text-white mb-0.5">
                                                We value your privacy
                                            </h3>
                                            <p className="text-[12px] md:text-sm text-gray-600 dark:text-gray-100/70 leading-relaxed max-w-4xl opacity-90">
                                                We use cookies to enhance your experience and analyze site traffic.
                                                <span className="hidden md:inline"> By clicking "Accept All", you consent to our use of cookies.</span>
                                            </p>
                                        </div>
                                    </div>

                                    {/* Buttons Section */}
                                    <div className="flex flex-col sm:flex-row items-stretch lg:items-center gap-2 md:gap-3 shrink-0">
                                        <div className="grid grid-cols-2 gap-2 sm:flex sm:items-center">
                                            <button
                                                onClick={() => setIsManaging(true)}
                                                className="px-4 py-2 md:px-5 md:py-2.5 rounded-xl text-gray-700 dark:text-gray-100 font-bold text-[12px] md:text-sm hover:bg-gray-100 dark:hover:bg-white/10 transition-all border border-gray-200 dark:border-white/10 sm:border-transparent"
                                            >
                                                Preferences
                                            </button>
                                            <button
                                                onClick={handleDeclineAll}
                                                className="px-4 py-2 md:px-5 md:py-2.5 rounded-xl text-gray-500 dark:text-gray-100/60 hover:text-gray-900 dark:hover:text-white font-semibold text-[12px] md:text-sm transition-colors border border-gray-200 dark:border-white/10 sm:border-transparent"
                                            >
                                                Necessary Only
                                            </button>
                                        </div>
                                        <button
                                            onClick={handleAcceptAll}
                                            className="px-8 py-2.5 md:px-10 md:py-3.5 rounded-xl md:rounded-2xl bg-gray-900 dark:bg-gradient-to-r dark:from-cyan-500 dark:to-blue-600 text-white font-bold text-[13px] md:text-base hover:scale-[1.01] active:scale-[0.99] transition-all shadow-xl shadow-cyan-500/10"
                                        >
                                            Accept All
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <motion.div
                                initial={{ opacity: 0, scale: 0.98 }}
                                animate={{ opacity: 1, scale: 1 }}
                                className="relative z-10"
                            >
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4 md:mb-8">
                                    <div className="flex items-center gap-3">
                                        <button
                                            onClick={() => setIsManaging(false)}
                                            className="p-2 rounded-xl text-gray-500 dark:text-gray-100 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors border border-gray-100 dark:border-white/10"
                                        >
                                            <Icon name="ArrowLeft" size={18} />
                                        </button>
                                        <div>
                                            <h3 className="text-base md:text-xl font-bold text-gray-900 dark:text-white">
                                                Settings
                                            </h3>
                                        </div>
                                    </div>

                                    <button
                                        onClick={handleSavePreferences}
                                        className="w-full md:w-auto px-6 py-2.5 rounded-xl bg-gray-900 dark:bg-gradient-to-r dark:from-cyan-500 dark:to-blue-600 text-white font-bold text-sm shadow-xl shadow-cyan-500/10"
                                    >
                                        Save Selections
                                    </button>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-3 gap-2 md:gap-4">
                                    {[
                                        { id: 'necessary', title: 'Necessary', desc: 'Required for site.', icon: 'ShieldCheck', required: true },
                                        { id: 'analytics', title: 'Analytics', desc: 'Helps us improve.', icon: 'BarChart3' },
                                        { id: 'marketing', title: 'Marketing', desc: 'Targeting ads.', icon: 'Target' }
                                    ].map((pref) => (
                                        <div
                                            key={pref.id}
                                            onClick={() => !pref.required && togglePreference(pref.id)}
                                            className={`p-3 md:p-4 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${pref.required ? 'bg-gray-50 dark:bg-white/5 border-gray-100 dark:border-transparent' : (preferences[pref.id] ? 'bg-white dark:bg-white/10 border-cyan-500/50 shadow-md' : 'bg-transparent border-gray-200 dark:border-white/10 opacity-80')}`}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className={`p-2 rounded-lg ${preferences[pref.id] || pref.required ? 'bg-cyan-500/10 text-cyan-600 dark:text-cyan-400' : 'bg-gray-100 dark:bg-white/5 text-gray-500 dark:text-gray-300'}`}>
                                                    <Icon name={pref.icon} size={18} />
                                                </div>
                                                <div>
                                                    <h4 className="font-bold text-gray-900 dark:text-white text-sm">{pref.title}</h4>
                                                    <p className="text-[10px] text-gray-500 dark:text-gray-300/70">{pref.desc}</p>
                                                </div>
                                            </div>
                                            {!pref.required ? (
                                                <div className={`w-8 h-4.5 rounded-full relative transition-colors ${preferences[pref.id] ? 'bg-cyan-500' : 'bg-gray-300 dark:bg-white/20'}`}>
                                                    <div className={`absolute top-0.5 w-3.5 h-3.5 bg-white rounded-full transition-all ${preferences[pref.id] ? 'left-4' : 'left-0.5'}`} />
                                                </div>
                                            ) : (
                                                <span className="text-[9px] font-bold text-gray-400 uppercase">Fixed</span>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </motion.div>
                        )}
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

export default CookieConsent;
