import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';
import Icon from '../AppIcon';
import Button from './Button';
import { cn } from '../../utils/cn';

const Modal = ({
    isOpen,
    onClose,
    title,
    children,
    footer,
    size = 'md',
    showClose = true,
    className,
    isLocal = false
}) => {
    // Prevent scrolling when modal is open
    useEffect(() => {
        if (isLocal) return; // Skip for local modals
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, isLocal]);

    // Handle ESC key
    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [onClose]);

    if (!isOpen) return null;

    const sizeClasses = {
        sm: 'max-w-sm',
        md: 'max-w-md',
        lg: 'max-w-lg',
        xl: 'max-w-2xl',
        full: 'max-w-[95vw]'
    };

    const modalContent = (
        <div className={cn(
            isLocal ? "absolute inset-0 z-[50]" : "fixed inset-0 z-[200]",
            "flex items-end sm:items-center justify-center sm:p-4"
        )}>
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-background/80 backdrop-blur-sm animate-in fade-in duration-300"
                onClick={onClose}
            />

            {/* Modal Content */}
            <div className={cn(
                "relative bg-card border border-border shadow-2xl overflow-hidden animate-in duration-300 w-full flex flex-col",
                // Mobile: slide up from bottom, full width, rounded top corners
                // Desktop: centered card with rounded corners and max-height
                "rounded-t-3xl sm:rounded-3xl",
                "max-h-[92dvh] sm:max-h-[90vh]",
                "zoom-in-95 sm:zoom-in-95 slide-in-from-bottom-4 sm:slide-in-from-bottom-0",
                size === 'sm' && 'sm:max-w-sm',
                size === 'md' && 'sm:max-w-md',
                size === 'lg' && 'sm:max-w-lg',
                size === 'xl' && 'sm:max-w-2xl',
                size === 'full' && 'sm:max-w-[95vw]',
                className
            )}>
                {/* Mobile Drag Handle */}
                <div className="sm:hidden flex justify-center pt-3 pb-1 shrink-0">
                    <div className="w-10 h-1 bg-border rounded-full" />
                </div>

                {/* Header */}
                <div className="flex items-center justify-between px-4 sm:px-6 py-3 sm:py-4 border-b border-border shrink-0">
                    <h2 className="text-base sm:text-lg font-bold text-primary">{title}</h2>
                    {showClose && (
                        <button
                            onClick={onClose}
                            className="p-2 hover:bg-muted rounded-full transition-colors text-muted-foreground hover:text-primary"
                        >
                            <Icon name="X" size={18} />
                        </button>
                    )}
                </div>

                {/* Body */}
                <div className="px-4 sm:px-6 py-4 overflow-y-auto flex-1 custom-scrollbar relative">
                    {children}
                </div>

                {/* Footer */}
                {footer && (
                    <div className="flex justify-end gap-3 px-4 sm:px-6 py-3 sm:py-4 border-t border-border bg-muted/20 shrink-0 pb-[calc(env(safe-area-inset-bottom)+12px)]">
                        {footer}
                    </div>
                )}
            </div>
        </div>
    );

    if (isLocal) return modalContent;

    return createPortal(modalContent, document.body);
};

export default Modal;
