import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';
import { compareIds } from '../../../utils/idUtils';
import HeartSplash from './HeartSplash';

const CourseCard = ({ course, onEnroll, isLoading, isLiked, likeCount, onLike, isEnrolled, isTrackMode, liveSession }) => {
    const [showSplash, setShowSplash] = useState(false);
    const user = useSelector(state => state.auth.user);
    const academyTracks = useSelector(state => state.content.academyTracks) || [];
    const belongsToTrack = !course.isTrack && academyTracks.some(t =>
        (t.courses || []).some(cId => compareIds(cId, course.id))
    );
    const instructors = useSelector(state => state.content.instructors) || [];
    const instructor = instructors.find(i =>
        (course.instructorId && i.id === course.instructorId) ||
        (i.name === course.instructor)
    );

    const isInstructor = user?.id && (course.instructor_id === user.id || course.instructorId === user.id);

    const handleLikeClick = (e) => {
        e.preventDefault();
        e.stopPropagation();

        if (!isLiked) {
            setShowSplash(true);
            setTimeout(() => setShowSplash(false), 800);
        }

        onLike();
    };

    return (
        <div className="group bg-card border border-border rounded-[2rem] overflow-hidden hover:shadow-2xl hover:shadow-primary/5 transition-all duration-500 flex flex-col h-full">
            {/* Course Image */}
            <div className="relative aspect-[16/10] overflow-hidden">
                <Image
                    src={course.image}
                    alt={course.title}
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

                {/* Category Badge */}
                <div className="absolute top-4 left-4 flex items-center gap-2">
                    <span className="px-3 py-1 bg-white/90 dark:bg-black/60 backdrop-blur-md rounded-full text-[10px] font-bold uppercase tracking-wider text-primary border border-white/20">
                        {course.category}
                    </span>
                    {liveSession && (
                        <span className="px-3 py-1 bg-red-500 backdrop-blur-md rounded-full text-[10px] font-black uppercase tracking-wider text-white flex items-center gap-1 animate-pulse shadow-lg shadow-red-500/30">
                            <span className="w-1.5 h-1.5 bg-white rounded-full" />
                            LIVE
                        </span>
                    )}
                </div>

                {/* Level Badge */}
                <div className="absolute bottom-4 left-4">
                    <div className="flex items-center gap-1.5 px-3 py-1 bg-primary/90 text-primary-foreground rounded-full text-xs font-medium shadow-lg">
                        <Icon name="BarChart" size={12} />
                        <span>{course.level}</span>
                    </div>
                </div>

                {/* Like Button */}
                {(!isTrackMode || isEnrolled) && (
                    <div className="absolute top-4 right-4 z-20">
                        <div className="relative">
                            <HeartSplash active={showSplash} />
                            <button
                                onClick={handleLikeClick}
                                className={cn(
                                    "flex items-center gap-1.5 px-3 py-1.5 rounded-full backdrop-blur-md transition-all duration-300 border relative z-10",
                                    isLiked
                                        ? "bg-red-500/20 border-red-500/30 text-red-500"
                                        : "bg-black/40 border-white/10 text-white hover:bg-black/60",
                                    showSplash && "animate-heart-pop"
                                )}
                            >
                                <Icon
                                    name="Heart"
                                    size={14}
                                    fill={isLiked ? "currentColor" : "none"}
                                    className={cn(isLiked && !showSplash && "animate-pulse", isLiked && "text-red-500")}
                                />
                                <span className="text-xs font-black italic">{(likeCount || 0).toLocaleString()}</span>
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Content */}
            <div className="p-6 flex flex-col flex-1">
                <div className="flex items-center gap-4 text-xs text-muted-foreground mb-3">
                    <div className="flex items-center gap-1">
                        <Icon name="Clock" size={14} className="text-secondary" />
                        <span>{course.duration}</span>
                    </div>
                    <div className="flex items-center gap-1">
                        <Icon name="BookOpen" size={14} className="text-brand-blue" />
                        <span>{course.lessons} lessons</span>
                    </div>
                </div>

                <h3 className="text-lg font-bold text-primary mb-2 line-clamp-2 group-hover:text-secondary transition-colors duration-300 italic">
                    {course.title}
                </h3>

                <p className="text-sm text-muted-foreground line-clamp-2 mb-6 flex-1">
                    {course.description}
                </p>

                {/* Progress Bar (Visible if progress > 0) */}
                {(course.progress > 0) && (
                    <div className="mb-6 space-y-2">
                        <div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-wider">
                            <span className="text-muted-foreground">Learning Progress</span>
                            <span className="text-secondary">{course.progress}%</span>
                        </div>
                        <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                            <div
                                className="h-full bg-secondary transition-all duration-1000 ease-out"
                                style={{ width: `${course.progress}%` }}
                            />
                        </div>
                    </div>
                )}

                {/* Footer */}
                <div className="pt-4 border-t border-border flex items-center justify-between mt-auto">
                    <Link 
                        to={`/instructor/${course.instructor_id || course.instructorId}`} 
                        className="flex items-center gap-2 hover:opacity-80 transition-opacity group/instructor"
                    >
                        <div className="w-8 h-8 rounded-full bg-muted flex items-center justify-center overflow-hidden border border-border group-hover/instructor:border-secondary transition-colors">
                            <img
                                src={instructor?.avatar || course.instructorAvatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(course.instructor || 'I')}&background=random`}
                                alt={course.instructor}
                                className="w-full h-full object-cover"
                            />
                        </div>
                        <span className="text-xs font-semibold text-primary group-hover/instructor:text-secondary transition-colors">{course.instructor}</span>
                    </Link>
                    <div className="text-right">
                        <div className="flex flex-col items-end gap-1 mb-1">
                            <div className="flex items-center gap-1">
                                <Icon name="Users" size={10} className="text-secondary" />
                                <span className="text-[10px] font-black italic">{course.students || 0}</span>
                                <span className="text-[8px] uppercase font-bold text-muted-foreground ml-0.5 tracking-tighter">Enrolled</span>
                            </div>
                            <div className="flex items-center gap-1">
                                <Icon name="Star" size={10} fill="currentColor" className="text-orange-400" />
                                <span className="text-[10px] font-black italic">{parseFloat(course.rating) > 0 ? course.rating : "0.0"}</span>
                            </div>
                        </div>
                        {!isTrackMode ? (
                            <>
                                <span className="block text-[10px] text-muted-foreground uppercase font-bold tracking-tighter">Price</span>
                                <span className="text-sm font-black text-success">
                                    {(Number(course.price) === 0 || course.price === 'Free') ? 'FREE' : `₦${Number(course.price).toLocaleString()}`}
                                </span>
                            </>
                        ) : (
                            <>
                                <span className="block text-[10px] text-muted-foreground uppercase font-bold tracking-tighter">Status</span>
                                <span className="text-sm font-black text-secondary">
                                    {isEnrolled ? 'ENROLLED' : 'INCLUDED'}
                                </span>
                            </>
                        )}
                    </div>
                </div>

                {(!isTrackMode || isEnrolled) && (
                    <div className="mt-6">
                        <Button
                            fullWidth
                            variant={isInstructor ? "outline" : (isEnrolled ? "default" : (course.price === 0 ? "outline" : "default"))}
                            iconName={isLoading ? "Loader2" : (isInstructor ? "Presentation" : (isEnrolled ? "Play" : "ArrowRight"))}
                            iconPosition="right"
                            onClick={onEnroll}
                            disabled={isLoading}
                            className={cn(
                                isLoading && "animate-pulse",
                                isEnrolled && !isInstructor && "bg-secondary hover:bg-secondary/90 border-none shadow-lg shadow-secondary/20",
                                isInstructor && "border-primary/20 text-primary hover:bg-primary/5"
                            )}
                        >
                            {isLoading ? "Preparing Classroom..." : (isInstructor ? "Manage in Hub" : (isEnrolled ? (course.progress > 0 ? "Resume Learning" : "Start Learning") : (isTrackMode ? "View Included Course" : (belongsToTrack ? "Enroll in Track" : "Enroll Now"))))}
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default CourseCard;
