import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { updateMaintenanceModeAsync } from '../../store/contentSlice';

const MaintenanceMode = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const maintenanceModeData = useSelector(state => state.content.maintenanceMode);
    const { user, role, roles } = useSelector(state => state.auth);
    const [isDisabling, setIsDisabling] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const isAdmin = role === 'admin' || roles?.includes('admin');

    const {
        title = "Institutional Refinement in Progress",
        message = "We are currently deploying elite upgrades to the Venture Ecosystem. Your path to funding is being polished.",
        estimatedReturn = "2 hours"
    } = maintenanceModeData || {};

    const handleDisableMaintenance = async () => {
        setIsDisabling(true);
        try {
            await dispatch(updateMaintenanceModeAsync({
                active: false,
                title: maintenanceModeData?.title || title,
                message: maintenanceModeData?.message || message,
                estimatedReturn: maintenanceModeData?.estimatedReturn || estimatedReturn
            })).unwrap();
            setShowSuccess(true);
            setTimeout(() => window.location.reload(), 1500);
        } catch (err) {
            console.error('Failed to disable maintenance mode:', err);
        } finally {
            setIsDisabling(false);
        }
    };

    return (
        <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 relative overflow-hidden">
            {/* Ambient Background Glows */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary/10 rounded-full blur-[120px] animate-pulse" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-secondary/10 rounded-full blur-[120px] animate-pulse" />

            <div className="max-w-2xl w-full text-center space-y-8 relative z-10">
                {/* Branding Section */}
                <div className="flex flex-col items-center gap-4 animate-in fade-in zoom-in duration-1000">
                    <div className="w-20 h-20 bg-white/5 backdrop-blur-2xl rounded-[1.5rem] border border-white/10 flex items-center justify-center shadow-2xl relative">
                        <div className="absolute inset-0 bg-primary/20 rounded-[1.5rem] blur-xl animate-ping opacity-50" />
                        <Icon name="Settings" size={40} className="text-primary animate-spin-slow" />
                    </div>

                    <div className="flex items-center gap-2">
                        <span className="text-3xl font-black text-white uppercase tracking-tighter">LUC</span>
                        <span className="text-3xl font-black text-gradient not-italic">Hub</span>
                    </div>
                </div>

                {/* Main Message */}
                <div className="space-y-3 animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-300">
                    <h1 className="text-4xl md:text-6xl font-black text-white italic tracking-tighter leading-tight" dangerouslySetInnerHTML={{ __html: title.replace('Refinement', '<span class="text-primary">Refinement</span>') }} />
                    <p className="text-slate-400 text-base md:text-lg max-w-lg mx-auto font-medium">
                        {message}
                    </p>
                </div>

                {/* Status Indicator */}
                <div className="flex flex-col items-center gap-3 animate-in fade-in duration-1000 delay-500">
                    <div className="px-5 py-2.5 bg-white/5 backdrop-blur-xl border border-white/10 rounded-full flex items-center gap-3">
                        <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" />
                        <span className="text-amber-500 font-bold tracking-widest text-xs uppercase">Deployment Status: Active</span>
                    </div>
                    <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em]">
                        Estimated Return: <span className="text-white">{estimatedReturn}</span>
                    </p>
                </div>

                {/* Action / Socials */}
                <div className="pt-4 flex flex-col sm:flex-row items-center justify-center gap-4 animate-in fade-in duration-1000 delay-700">
                    <Button
                        variant="outline"
                        className="border-white/10 text-white hover:bg-white/5"
                        onClick={() => window.open('https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V', '_blank')}
                    >
                        Join the Community Hub
                    </Button>
                    <Button
                        variant="ghost"
                        className="text-slate-500 hover:text-white"
                        onClick={() => window.location.reload()}
                    >
                        Check Connectivity
                    </Button>
                </div>

                {/* Admin Emergency Toggle */}
                {isAdmin && (
                    <div className="pt-6 animate-in fade-in duration-1000 delay-1000">
                        {showSuccess ? (
                            <div className="px-4 py-2 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
                                <p className="text-emerald-400 text-sm font-medium">
                                    Refinement Mode disabled. Redirecting...
                                </p>
                            </div>
                        ) : (
                            <Button
                                variant="destructive"
                                className="bg-red-500/10 border border-red-500/20 text-red-400 hover:bg-red-500/20 hover:text-red-300"
                                onClick={handleDisableMaintenance}
                                disabled={isDisabling}
                            >
                                {isDisabling ? (
                                    <span className="flex items-center gap-2">
                                        <Icon name="Loader2" size={16} className="animate-spin" />
                                        Disabling...
                                    </span>
                                ) : (
                                    <span className="flex items-center gap-2">
                                        <Icon name="Power" size={16} />
                                        Disable Refinement Mode
                                    </span>
                                )}
                            </Button>
                        )}
                    </div>
                )}
            </div>

            {/* Bottom Branding */}
            <div className="mt-12 relative z-10 text-center animate-in fade-in duration-1000 delay-1000">
                <p className="text-[10px] text-slate-600 font-black uppercase tracking-[0.5em]">
                    Advanced Venture Architecture © 2026
                </p>
                <button
                    onClick={() => navigate('/admin/emergency')}
                    className="mt-4 text-[10px] text-slate-700 hover:text-primary/60 transition-colors cursor-pointer"
                >
                    Access
                </button>
            </div>
        </div>
    );
};

export default MaintenanceMode;
