import React from 'react';
import { cn } from '../../../utils/cn';

const HeartSplash = ({ active }) => {
    if (!active) return null;

    const particles = [
        { angle: 0, distance: 40, color: 'bg-red-500' },
        { angle: 45, distance: 35, color: 'bg-secondary' },
        { angle: 90, distance: 40, color: 'bg-orange-500' },
        { angle: 135, distance: 35, color: 'bg-red-400' },
        { angle: 180, distance: 40, color: 'bg-secondary' },
        { angle: 225, distance: 35, color: 'bg-primary' },
        { angle: 270, distance: 40, color: 'bg-orange-400' },
        { angle: 315, distance: 35, color: 'bg-red-500' },
    ];

    return (
        <div className="absolute inset-0 pointer-events-none z-30">
            {particles.map((p, i) => {
                const rad = (p.angle * Math.PI) / 180;
                const x = Math.cos(rad) * p.distance;
                const y = Math.sin(rad) * p.distance;

                return (
                    <div
                        key={i}
                        className={cn("heart-particle animate-ribbon", p.color)}
                        style={{
                            '--burst-transform': `translate(calc(-50% + ${x}px), calc(-50% + ${y}px))`,
                            '--burst-rotate': `${p.angle + 90}deg`,
                        }}
                    />
                );
            })}
        </div>
    );
};

export default HeartSplash;
