import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { newsletterService } from '../../../services/newsletterService';
import { useToast } from '../../../contexts/ToastContext';
import { trackEvent } from '../../../utils/analytics';

const NewsletterSection = () => {
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const { addToast } = useToast();

    const handleSubscribe = async (e) => {
        e.preventDefault();
        if (!email) return;

        setIsLoading(true);
        try {
            await newsletterService.subscribeUser(email, 'Strategic Partner');
            
            // Track the conversion in GA
            trackEvent('Newsletter', 'Subscribe', 'Homepage Section');
            
            addToast('Welcome to the Tribe. The first Dispatch is on its way.', 'success');
            setEmail('');
        } catch (error) {
            addToast('Failed to connect to the network. Try again.', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <section className="py-24 relative overflow-hidden bg-slate-950">
            {/* Background elements */}
            <div className="absolute top-0 left-1/4 w-96 h-96 bg-primary/10 rounded-full blur-[100px] -translate-y-1/2" />
            <div className="absolute bottom-0 right-1/4 w-96 h-96 bg-secondary/10 rounded-full blur-[100px] translate-y-1/2" />

            <div className="max-w-7xl mx-auto px-4 relative z-10">
                <div className="bg-white/[0.03] border border-white/10 rounded-[3rem] p-8 md:p-20 text-center relative overflow-hidden">
                    {/* Floating Icons for Aesthetic */}
                    <div className="absolute top-10 left-10 text-white/5 -rotate-12 hidden md:block">
                        <Icon name="Mail" size={120} />
                    </div>
                    <div className="absolute bottom-10 right-10 text-white/5 rotate-12 hidden md:block">
                        <Icon name="Send" size={100} />
                    </div>

                    <div className="max-w-2xl mx-auto">
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-white/5 border border-white/10 rounded-lg mb-6">
                            <div className="w-1.5 h-1.5 bg-primary rounded-full animate-pulse" />
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">The LUC Dispatch</span>
                        </div>
                        
                        <h2 className="text-4xl md:text-6xl font-black text-white italic tracking-tighter mb-6 leading-tight">
                            STRATEGY. OPS. <br />
                            <span className="text-primary italic">ADVANTAGE.</span>
                        </h2>
                        
                        <p className="text-slate-400 font-medium text-lg mb-12">
                            Stop chasing trends. Start building leverage. Join problem solvers receiving weekly high-stakes opportunities and research directly in their inbox.
                        </p>

                        <form onSubmit={handleSubscribe} className="flex flex-col md:flex-row gap-4 max-w-lg mx-auto">
                            <div className="flex-1 relative">
                                <Icon name="Mail" size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                    type="email" 
                                    placeholder="Enter your professional email" 
                                    required
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:border-primary/50 transition-colors font-medium"
                                />
                            </div>
                            <Button 
                                type="submit" 
                                loading={isLoading}
                                className="px-10 py-4 font-black italic rounded-2xl bg-white text-slate-950 hover:bg-primary hover:text-white transition-all shadow-xl shadow-white/5"
                            >
                                SECURE ACCESS
                            </Button>
                        </form>

                        <div className="mt-8 flex flex-wrap justify-center gap-8 opacity-40">
                            <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                <Icon name="ShieldCheck" size={14} />
                                No Spam. Ever.
                            </div>
                            <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                <Icon name="Zap" size={14} />
                                High-Signal Only
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default NewsletterSection;
