import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const HeroSection = () => {
  const navigate = useNavigate();
  const hero = useSelector((state) => state.content.hero) || {};
  const {
    title = "Every Opportunity Shared is a Life Potentially Transformed",
    subtitle = "LUC is a community-driven opportunity discovery platform where curated knowledge meets global ambition.",
    primaryCTA = "Explore Opportunities",
    secondaryCTA = "Join WhatsApp Community",
    secondaryLink = "https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V"
  } = hero;
  const { spotlight, academy, vault, isLoading } = useSelector((state) => state.content);
  const { courseProgress } = useSelector((state) => state.activity);
  const dbStats = useSelector((state) => state.content.stats);
  const [liveCounts, setLiveCounts] = useState({ members: 0, opportunities: 0, likes: 0, loading: true });
  const [enrolledCount, setEnrolledCount] = useState(0);
  const [shouldPulse, setShouldPulse] = useState(false);

  const spotlightItem = (spotlight && (spotlight.type === 'course'
    ? academy.find(c => (c.id || '').toString() === (spotlight.id || '').toString())
    : vault.find(c => (c.id || '').toString() === (spotlight.id || '').toString()))) || academy[0] || vault[0];

  const isEnrolled = spotlightItem && courseProgress[spotlightItem.id.toString()];

  const handleSpotlightAction = (e) => {
    if (e) e.stopPropagation();
    if (!spotlightItem) return;

    if (isEnrolled) {
      navigate(`/academy/${spotlight?.type === 'course' ? 'course' : 'lesson'}/${spotlightItem.id}`);
    } else {
      if (spotlight?.type === 'course') {
        navigate(`/academy?enroll=${spotlightItem.id}`);
      } else {
        navigate(`/academy`);
      }
    }
  };

  useEffect(() => {
    const fetchEnrollmentCount = async () => {
      if (spotlightItem?.id) {
        try {
          const count = await supabaseService.getEnrollmentCount(spotlightItem.id);
          // If the DB count is low (e.g. brand new site), we can combine with the "seed" number 
          // or just show the DB count. Given the request, showing DB count + manual seed is standard.
          const seedCount = parseInt(spotlightItem?.students) || 0;
          setEnrolledCount(seedCount + count);
        } catch (error) {
          console.error("Error fetching enrollment count:", error);
          setEnrolledCount(parseInt(spotlightItem?.students) || 0);
        }
      }
    };
    fetchEnrollmentCount();
  }, [spotlightItem]);

  useEffect(() => {
    const fetchCounts = async () => {
      try {
        const [memberCount, opportunities] = await Promise.all([
          supabaseService.getUserCount(),
          supabaseService.getOpportunities()
        ]);
        const totalLikes = opportunities.reduce((acc, curr) => acc + (curr.likes_count || 0), 0);
        setLiveCounts({
          members: memberCount,
          opportunities: opportunities.length,
          likes: totalLikes,
          loading: false
        });
      } catch (error) {
        console.error("Error fetching live counts:", error);
      }
    };
    fetchCounts();

    // Set up Realtime Subscription
    const usersChannel = supabaseService.subscribeToTable('profiles', (payload) => {
      if (payload.eventType === 'INSERT') setLiveCounts(prev => ({ ...prev, members: prev.members + 1 }));
      if (payload.eventType === 'DELETE') setLiveCounts(prev => ({ ...prev, members: Math.max(0, prev.members - 1) }));
    });

    const oppsChannel = supabaseService.subscribeToTable('opportunities', (payload) => {
      if (payload.eventType === 'INSERT') setLiveCounts(prev => ({ ...prev, opportunities: prev.opportunities + 1 }));
      if (payload.eventType === 'DELETE') setLiveCounts(prev => ({ ...prev, opportunities: Math.max(0, prev.opportunities - 1) }));
      if (payload.eventType === 'UPDATE') {
        const oldLikes = payload.old?.likes_count || 0;
        const newLikes = payload.new?.likes_count || 0;
        if (oldLikes !== newLikes) {
          setLiveCounts(prev => ({ ...prev, likes: prev.likes - oldLikes + newLikes }));
        }
      }
    });

    const enrollChannel = supabaseService.subscribeToTable('enrollments', (payload) => {
      if (payload.eventType === 'INSERT') {
        const item = payload.new;
        if (String(item.item_id) === String(spotlightItem?.id)) {
          setEnrolledCount(prev => prev + 1);
          setShouldPulse(true);
          setTimeout(() => setShouldPulse(false), 2000);
        }
      }
    });

    return () => {
      supabaseService.unsubscribe(usersChannel);
      supabaseService.unsubscribe(oppsChannel);
      supabaseService.unsubscribe(enrollChannel);
    };
  }, [spotlightItem]);

  const stats = [
    { label: "Active Opportunities", value: liveCounts.loading ? "..." : (liveCounts.opportunities).toLocaleString() + "+" },
    { label: "Community Members", value: liveCounts.loading ? "..." : (liveCounts.members).toLocaleString() + "+" },
    { label: "Loves Received", value: liveCounts.loading ? "..." : (liveCounts.likes).toLocaleString() + "+" }
  ];

  return (
    <section className="relative min-h-[90vh] flex items-center overflow-hidden bg-slate-950">
      {/* Cinematic Background Image */}
      <div className="absolute inset-0 z-0">
        <img 
          src="/global_hub_hero.webp" 
          className="w-full h-full object-cover opacity-50 mix-blend-overlay scale-105 animate-pulse-slow"
          alt="Global Hub"
        />
        <div className="absolute inset-0 bg-gradient-to-r from-slate-950 via-slate-950/80 to-transparent lg:block hidden" />
        <div className="absolute inset-0 bg-gradient-to-b from-slate-950/20 via-slate-950/80 to-slate-950" />
      </div>

      {/* Decorative Elements */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/4 -left-20 w-96 h-96 bg-primary/20 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute bottom-1/4 -right-20 w-96 h-96 bg-secondary/20 blur-[120px] rounded-full animate-pulse delay-700" />
      </div>

      <div className="relative max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-20 lg:py-32">
        <div className={`grid grid-cols-1 ${spotlightItem ? 'lg:grid-cols-2' : 'max-w-4xl mx-auto'} gap-12 lg:gap-20 items-center relative z-10`}>
          <div className={spotlightItem ? "text-center lg:text-left" : "text-center"}>
            <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 backdrop-blur-md rounded-full mb-8 border border-white/10 animate-in fade-in slide-in-from-bottom-4 duration-700">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
              </span>
              <span className="text-[10px] md:text-xs font-black text-white uppercase tracking-[0.2em]">
                Join Students from 50+ Countries
              </span>
            </div>

            <h1 className="text-4xl md:text-6xl lg:text-7xl font-black mb-6 leading-[0.9] tracking-tighter text-white italic animate-in fade-in slide-in-from-bottom-8 duration-700 delay-100">
              Your Gateway to <br />
              <span className="bg-gradient-to-r from-secondary via-brand-blue to-primary bg-clip-text text-transparent">Global Success</span>
            </h1>

            <p className="text-lg md:text-xl text-slate-300 mb-10 max-w-2xl mx-auto lg:mx-0 font-medium leading-relaxed animate-in fade-in slide-in-from-bottom-8 duration-700 delay-200">
              LUC Hub is the premier community-driven engine where world-class opportunities meet the next generation of global leaders. Discover, learn, and grow without borders.
            </p>

            <div className={`flex flex-col sm:flex-row gap-4 justify-center ${spotlightItem ? 'lg:justify-start' : ''} animate-in fade-in slide-in-from-bottom-8 duration-700 delay-300`}>
              <Button
                variant="default"
                size="lg"
                iconName="Search"
                iconPosition="left"
                className="bg-primary hover:bg-primary/90 text-white shadow-2xl shadow-primary/20 py-6 px-10 text-lg font-black italic rounded-2xl shrink-0"
                asChild
              >
                <Link to="/opportunity-discovery">Find Opportunities</Link>
              </Button>

              <Button
                variant="outline"
                size="lg"
                iconName="UserCheck"
                iconPosition="left"
                className="bg-white/5 backdrop-blur-md border-white/10 text-white hover:bg-white/10 py-6 px-10 text-lg font-black italic rounded-2xl shrink-0"
                asChild
              >
                <Link to="/recruiter-portal">Hire Talent</Link>
              </Button>
            </div>

            <div className={`flex flex-wrap lg:flex-nowrap items-center justify-center ${spotlightItem ? 'lg:justify-start' : ''} gap-8 lg:gap-12 mt-16 animate-in fade-in slide-in-from-bottom-8 duration-700 delay-500`}>
              {stats?.map((stat, index) => (
                <div key={index} className="text-center lg:text-left">
                  <div className="text-3xl md:text-5xl font-black text-white italic leading-none mb-2">{stat?.value}</div>
                  <div className="text-[10px] font-black uppercase tracking-widest text-slate-400 whitespace-nowrap">{stat?.label}</div>
                </div>
              ))}
            </div>
          </div>

          {(spotlightItem || (isLoading && !hero.title)) ? (
            <div className="block mt-12 lg:mt-0 lg:translate-x-8 lg:max-w-md lg:ml-auto animate-in fade-in zoom-in duration-1000 delay-300">
              <div className="spotlight-glow rounded-2xl lg:rounded-[2.5rem]">
                <div className="relative bg-white/5 backdrop-blur-2xl rounded-2xl lg:rounded-[2.5rem] p-5 sm:p-8 border border-white/10 shadow-2xl overflow-hidden">
                  {/* Glass Shine */}
                  <div className="absolute -top-full -left-full w-full h-full bg-gradient-to-br from-white/10 to-transparent rotate-45 animate-glass-shine" />
                  
                  {isLoading && !spotlightItem ? (
                    <div className="animate-pulse space-y-6">
                      <div className="flex items-center gap-4 mb-6">
                        <div className="w-12 h-12 lg:w-16 lg:h-16 bg-white/5 rounded-xl lg:rounded-2xl" />
                        <div className="space-y-2">
                          <div className="h-4 w-32 bg-white/5 rounded" />
                          <div className="h-3 w-24 bg-white/5 rounded" />
                        </div>
                      </div>
                      <div className="aspect-video bg-white/5 rounded-xl lg:rounded-2xl" />
                    </div>
                  ) : (
                    <>
                      <div className="flex items-center gap-3 sm:gap-5 mb-5 sm:mb-8">
                        <div className="w-12 h-12 sm:w-16 sm:h-16 rounded-xl sm:rounded-2xl bg-gradient-to-br from-secondary to-orange-500 flex items-center justify-center shadow-2xl shadow-secondary/20 shrink-0">
                          <Icon name={spotlight?.type === 'vault' ? "Zap" : "GraduationCap"} size={20} color="white" className="sm:hidden" />
                          <Icon name={spotlight?.type === 'vault' ? "Zap" : "GraduationCap"} size={28} color="white" className="hidden sm:block" />
                        </div>
                        <div>
                          <div className="text-base sm:text-xl font-black italic text-white tracking-tight">{spotlight?.badgeText || 'Academy Spotlight'}</div>
                          <div className="text-[10px] sm:text-[11px] font-black uppercase tracking-widest text-secondary">{spotlight?.label || 'Featured learning'}</div>
                        </div>
                      </div>

                      <div className="group/item cursor-pointer" onClick={handleSpotlightAction}>
                        <div className="relative aspect-video rounded-2xl lg:rounded-3xl overflow-hidden mb-4 sm:mb-6 border border-white/10 shadow-2xl">
                          <img
                            src={spotlightItem?.image || spotlightItem?.thumbnail}
                            alt={spotlightItem?.title}
                            className="w-full h-full object-cover group-hover/item:scale-110 transition-transform duration-1000"
                          />
                          <div className="absolute top-3 left-3 sm:top-4 sm:left-4 px-2.5 py-1 sm:px-3 sm:py-1.5 bg-secondary text-white rounded-lg sm:rounded-xl text-[9px] sm:text-[10px] font-black uppercase tracking-widest leading-none shadow-lg">
                            {spotlight?.type === 'course'
                              ? (spotlightItem?.price === 0 ? 'FREE' : `₦${spotlightItem?.price?.toLocaleString()}`)
                              : (spotlightItem?.isFree || !spotlightItem?.isProtected ? 'FREE' : 'PREMIUM')
                            }
                          </div>
                        </div>

                        <h2 className="font-black text-lg sm:text-2xl mb-2 sm:mb-3 line-clamp-2 leading-tight group-hover/item:text-secondary transition-colors italic text-white tracking-tight">
                          {spotlightItem?.title}
                        </h2>

                        <div className="flex items-center gap-3 sm:gap-5 text-[10px] sm:text-[11px] font-black text-slate-400 uppercase tracking-widest mb-5 sm:mb-8">
                          <div className="flex items-center gap-1.5 sm:gap-2">
                            <Icon name="Clock" size={12} className="text-secondary sm:hidden" />
                            <Icon name="Clock" size={14} className="text-secondary hidden sm:block" />
                            <span>{spotlightItem?.duration}</span>
                          </div>
                          <div className="flex items-center gap-1.5 sm:gap-2">
                            <Icon name="Users" size={12} className="text-orange-400 sm:hidden" />
                            <Icon name="Users" size={14} className="text-orange-400 hidden sm:block" />
                            <span className={`${shouldPulse ? 'text-secondary font-black animate-bounce scale-110' : ''} transition-all duration-500`}>
                              {(enrolledCount).toLocaleString()}+ Scholars
                            </span>
                          </div>
                        </div>

                        <Button
                          variant="default"
                          fullWidth
                          className={cn(
                            "bg-white text-slate-950 hover:bg-secondary hover:text-white border-none font-black italic py-4 sm:py-5 text-base sm:text-lg rounded-xl sm:rounded-2xl shadow-xl transition-all duration-300",
                            isEnrolled && "bg-secondary text-white shadow-secondary/20"
                          )}
                          onClick={handleSpotlightAction}
                          iconName={isEnrolled ? "Play" : "ArrowRight"}
                          iconPosition="right"
                        >
                          {isEnrolled ? "Resume Mastery" : "Enroll Now"}
                        </Button>
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  );
};

export default HeroSection;