import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import { cn } from '../../../utils/cn';

const HallOfFameShowcase = () => {
    const [spotlights, setSpotlights] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchLatestSpotlights();
    }, []);

    const fetchLatestSpotlights = async () => {
        try {
            const { data, error } = await supabaseService.supabase
                .from('student_spotlights')
                .select(`
                    *,
                    profiles:user_id (full_name, avatar_url, bio)
                `)
                .order('created_at', { ascending: false });

            if (error) throw error;

            // Debugging log for Admin
            console.log("Spotlight Data Received:", data);

            // Robust matching (Case-insensitive)
            const latestWeek = data?.find(s => s.title.toLowerCase().includes('week'));
            const latestMonth = data?.find(s => s.title.toLowerCase().includes('month'));
            
            const results = [];
            if (latestMonth) results.push(latestMonth);
            if (latestWeek) results.push(latestWeek);
            
            setSpotlights(results);
        } catch (error) {
            console.error("Error fetching Hall of Fame:", error);
        } finally {
            setIsLoading(false);
        }
    };

    if (isLoading) return null;

    return (
        <section className="py-24 lg:py-32 bg-slate-950 relative overflow-hidden">
            {/* Background Decorations */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-secondary/5 blur-[150px] rounded-full" />
            
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16 md:mb-24">
                    <div className="text-center md:text-left">
                        <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full mb-8 backdrop-blur-md">
                            <Icon name="Trophy" size={20} className="text-secondary" />
                            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white">The Legacy Wall</span>
                        </div>
                        <h2 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-4 tracking-tighter italic leading-[0.9]">
                            Global <span className="bg-gradient-to-r from-secondary to-amber-500 bg-clip-text text-transparent">Hall of Fame</span>
                        </h2>
                        <p className="text-lg md:text-xl text-slate-400 max-w-2xl font-medium leading-relaxed">
                            A living record of excellence. Swipe to explore the legends who mastered the Hub.
                        </p>
                    </div>
                    
                    {/* Navigation Hint */}
                    <div className="hidden md:flex items-center gap-4 text-slate-500">
                        <div className="w-12 h-px bg-white/10" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Scroll to Explore History</span>
                        <div className="w-12 h-px bg-white/10" />
                    </div>
                </div>

                {spotlights.length === 0 ? (
                    <div className="p-20 rounded-[3.5rem] bg-white/5 border border-dashed border-white/10 flex flex-col items-center justify-center text-center backdrop-blur-3xl">
                        <Icon name="Award" size={48} className="text-slate-600 mb-8" />
                        <h3 className="text-2xl font-black italic text-white mb-3">Legacy in the Making...</h3>
                        <p className="text-slate-400 font-medium">Be the first to claim your spot in the Global Hall of Fame.</p>
                    </div>
                ) : (
                    <div className="relative group/scroll">
                        {/* Edge Fades for visual depth */}
                        <div className="absolute top-0 left-0 bottom-0 w-20 bg-gradient-to-r from-slate-950 to-transparent z-20 pointer-events-none opacity-0 group-hover/scroll:opacity-100 transition-opacity duration-500" />
                        <div className="absolute top-0 right-0 bottom-0 w-20 bg-gradient-to-l from-slate-950 to-transparent z-20 pointer-events-none opacity-0 group-hover/scroll:opacity-100 transition-opacity duration-500" />

                        {/* Scrollable Track */}
                        <div className="flex gap-8 lg:gap-10 overflow-x-auto pb-12 pt-4 px-4 no-scrollbar scroll-smooth snap-x snap-mandatory">
                            {spotlights.map((item, idx) => (
                            <div 
                                key={item.id}
                                className={cn(
                                    "flex-shrink-0 w-[320px] md:w-[450px] snap-center group relative p-8 md:p-10 rounded-[3.5rem] border transition-all duration-700 hover:-translate-y-2 hover:shadow-2xl overflow-hidden",
                                    item.title.toLowerCase().includes('month') 
                                        ? "bg-gradient-to-br from-amber-500/10 to-orange-600/5 border-amber-500/20 shadow-amber-500/5" 
                                        : "bg-gradient-to-br from-slate-400/10 to-slate-500/5 border-white/10 shadow-white/5"
                                )}
                            >
                                {/* Trophy Watermark */}
                                <div className="absolute -top-12 -right-12 opacity-5 group-hover:opacity-15 group-hover:scale-110 transition-all duration-1000">
                                    <Icon name="Trophy" size={300} className={item.title.toLowerCase().includes('month') ? "text-amber-500" : "text-slate-300"} />
                                </div>

                                <div className="flex flex-col gap-8 relative z-10">
                                    <div className="flex items-center gap-6">
                                        <div className="relative shrink-0">
                                            <div className={cn(
                                                "absolute inset-0 rounded-full blur-[30px] opacity-20 animate-pulse-slow",
                                                item.title.toLowerCase().includes('month') ? "bg-amber-400" : "bg-white"
                                            )} />
                                            <div className="relative w-20 h-20 md:w-24 md:h-24 rounded-full p-1.5 bg-white/10 backdrop-blur-3xl border border-white/20 shadow-2xl">
                                                <img 
                                                    src={item.profiles?.avatar_url || `https://ui-avatars.com/api/?name=${item.profiles?.full_name}&background=random`} 
                                                    alt={item.profiles?.full_name}
                                                    className="w-full h-full rounded-full object-cover grayscale-[30%] group-hover:grayscale-0 transition-all duration-700"
                                                />
                                            </div>
                                            <div className={cn(
                                                "absolute -bottom-1 -right-1 w-8 h-8 rounded-xl flex items-center justify-center shadow-2xl border border-white/20 rotate-12 group-hover:rotate-0 transition-transform duration-500",
                                                item.title.toLowerCase().includes('month') ? "bg-gradient-to-br from-amber-400 to-orange-600 text-white" : "bg-gradient-to-br from-slate-200 to-slate-400 text-slate-900"
                                            )}>
                                                <Icon name={item.title.toLowerCase().includes('month') ? "Crown" : "Star"} size={16} />
                                            </div>
                                        </div>

                                        <div>
                                            <div className={cn(
                                                "text-[9px] font-black uppercase tracking-[0.3em] py-1 px-3 rounded-full border mb-2 backdrop-blur-md inline-block",
                                                item.title.toLowerCase().includes('month') ? "text-amber-500 border-amber-500/20 bg-amber-500/5" : "text-slate-400 border-white/10 bg-white/5"
                                            )}>
                                                {item.title}
                                            </div>
                                            <h3 className="text-2xl md:text-3xl font-black text-white italic tracking-tighter leading-none">
                                                {item.profiles?.full_name}
                                            </h3>
                                        </div>
                                    </div>

                                    <p className="text-base md:text-lg text-slate-300 font-medium leading-relaxed italic line-clamp-3">
                                        "{item.caption}"
                                    </p>

                                    <div className="flex flex-wrap gap-2.5 pt-2">
                                        <div className="px-3 py-1.5 bg-white/5 rounded-xl border border-white/10 flex items-center gap-2">
                                            <Icon name="Target" size={14} className="text-secondary" />
                                            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Elite</span>
                                        </div>
                                        <div className="px-3 py-1.5 bg-white/5 rounded-xl border border-white/10 flex items-center gap-2">
                                            <Icon name="Globe" size={14} className="text-brand-blue" />
                                            <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Global</span>
                                        </div>
                                        <div className="flex items-center gap-1.5 px-3 py-1.5 bg-black/30 rounded-xl border border-white/5 ml-auto">
                                            <Icon name="Coins" size={12} className="text-primary" />
                                            <span className="text-[9px] font-black italic text-white">+{item.reward_amount || '500'}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </section>
    );
};

export default HallOfFameShowcase;
